window.__D("text/zohar-hebrew-translation/c037",{"p":[[9522012643,"<p>רוֹעָה הַנֶּאֱמָן, בַּעֲלֵי הַפֶּסַח, בִּזְמַן שֶׁשּׁוֹלֵט עֲלֵיהֶם לֵיל שִׁמּוּרִים, כֻּלָּם צְרִיכִים לִהְיוֹת שִׁמּוּרִים, וּשְׁמוּרִים מֵחָמֵץ וּשְׂאוֹר בְּכָל שֶׁהוּא, וְכָל הַמַּאֲכָלִים וְהַמַּשְׁקִים <Nonesmall>[כלי הפסח]</small> כֻּלָּם שְׁמוּרִים. וּמִי שֶׁשּׁוֹמְרָם מֵחָמֵץ וּשְׂאוֹר, גּוּפוֹ שָׁמוּר מִיֵּצֶר הָרָע לְמַטָּה, וְנִשְׁמָתוֹ לְמַעְלָה, וּבוֹ נֶאֱמַר <Nonesmall>[תהלים ה]</small> לֹא יְגֻרְךְ רָע. מִשּׁוּם שֶׁהֲרֵי גּוּפוֹ נַעֲשֶׂה קֹדֶשׁ, וְנִשְׁמָתוֹ קֹדֶשׁ קָדָשִׁים, וְנֶאֱמַר בַּיֵּצֶר הָרָע <Nonesmall>[ויקרא כה]</small> וְכָל זָר לֹא יֹאכַל קֹדֶשׁ, <Nonesmall>[במדבר א]</small> וְהַזָּר הַקָּרֵב יוּמָת.</p>\n<p>פֶּסַח, זְרוֹעַ יָמִין שֶׁל אַבְרָהָם, כֶּסֶף מְזֻקָּק. מִי שֶׁעֵרַב בּוֹ עוֹפֶרֶת, מְשַׁקֵּר אוֹתוֹ. כָּךְ מִי שֶׁעֵרַב חָמֵץ אוֹ שְׂאוֹר כָּל שֶׁהוּא בַּמַּצָּה, כְּאִלּוּ מְשַׁקֵּר בְּחוֹתַם הַמֶּלֶךְ. וְכָךְ מִי שֶׁעֵרַב בַּטִּפָּה שֶׁלּוֹ שׁוּם תַּעֲרֹבֶת, כְּאִלּוּ מְשַׁקֵּר אֶת חוֹתַם הַמֶּלֶךְ. זֶה בָּזֶה תָּלוּי.</p>"],[9522012644,"<p>רֹאשׁ הַשָּׁנָה, זְרוֹעַ שְׂמֹאל שֶׁל יִצְחָק, שָׁם דִּינֵי נְפָשׁוֹת, וַעֲקֵדַת יִצְחָק שָׁם הָיְתָה, שֶׁעֲקָדוֹ אַבְרָהָם. קֶשֶׁר שֶׁל תְּפִלָּה שֶׁל יָד כְּמוֹ עֲקֵדַת יִצְחָק. אַשְׁרֵי הַבֵּן שֶׁנֶּעֱקַד בְּאָבִיו וְנִקְשַׁר בּוֹ לַעֲשׂוֹת מַעֲשֵׂהוּ בַּתּוֹרָה וּבַמִּצְוָה, וְאַשְׁרֵי הָעֶבֶד שֶׁנִּקְשַׁר תַּחַת רַבּוֹ לַעֲשׂוֹת רְצוֹנוֹ, הוּא בַּמָּקוֹם שֶׁל בֶּן הַמֶּלֶךְ.</p>\n<p>מְטַטְרוֹ\"ן, אַשְׁרֶיךְ וְאַשְׁרֵי בָנֶיךְ, שֶׁהֵם קְשׁוּרִים וַעֲקוּדִים בִּתְפִלִּין תַּחַת רְשׁוּת רִבּוֹנְךְ. וְלָכֵן, אַף עַל גַּב שֶׁאַתָּה עֶבֶד לְרִבּוֹנְךְ, מֶלֶךְ אַתָּה עַל כָּל הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים, מֶלֶךְ עַל כָּל הַמַּלְאָכִים, מֶלֶךְ שֶׁשֵּׁדִים וְכָל מַחֲנוֹתֵיהֶם פּוֹחֲדִים מִמְּךְ. מִי גָרַם אֶת זֶה? מִשּׁוּם שֶׁאַתָּה שְׁרַפְרָף לְרִבּוֹנְךְ וְאַתָּה מְשַׁמֵּשׁ אֶת רִבּוֹנְךְ. שַׁדַּי שֶׁל הַמְּזוּזָה מִבַּחוּץ, שׁוֹמֵר הַפֶּתַח. יְהֹוָ\"ה שֶׁהוּא רִבּוֹנְךְ מִבִּפְנִים.</p>\n<p>וְכָךָ הוּא כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד לִשְׁלֹט עַל עֵץ הַדַּעַת טוֹב וָרָע, שֶׁהוּא טוֹב מְטַטְרוֹ\"ן. רָע סָמָאֵל, שֵׁד, מֶלֶךְ הַשֵּׁדִים. מְטַטְרוֹן מַלְאָךְ, מֶלֶךְ הַמַּלְאָכִים. אֲבָל מִצַּד עֵץ הַחַיִּים, שַׁדַּי הוּא יְסוֹד. וְלָכֵן לְמַטָּה שְׁנַיִם, עֶבֶד וְרַבּוֹ, שֶׁאֵינָם יִחוּד אֶחָד, וּלְמַעְלָה אֶחָד. תִּפְאֶרֶת יְסוֹד, שֶׁגּוּף וּבְרִית נֶחְשָׁבִים לְאֶחָד, שֶׁהִיא עַמּוּד הָאֶמְצָעִי וְצַדִּיק.</p>\n<p>כְּמוֹ שֶׁתְּפִלִּין שֶׁל רֹאשׁ, שֶׁהוּא בִּינָה עַל תִּפְאֶרֶת, מִצַּד שֶׁל עֵץ הַחַיִּים שֶׁל אֲצִילוּת, וּמַלְכוּת תְּפִלָּה שֶׁל יָד – כָּךְ לְמַטָּה בְּעֵץ הַחַיִּים שֶׁל בְּרִיאָה, מִצַּד הַכִּסֵּא הָעֶלְיוֹן, תְּפִלִּין שֶׁל רֹאשׁ מְטַטְרוֹן. תְּפִלִּין שֶׁל יָד שֶׁלּוֹ, כִּסֵּא תַּחְתּוֹן. וְזֶהוּ מַה שֶּׁאָמַר עָלָיו הַנָּבִיא, <Nonesmall>[ירמיה יז]</small> כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן.</p>"],[9522012645,"<p>אֲבָל מִצַּד עֵץ הַדַּעַת טוֹב וָרָע, בְּקֶשֶׁר הַתְּפִלִּין נִקְשָׁר יֵצֶר הָרָע תַּחַת יֵצֶר הַטּוֹב כְּמוֹ עֶבֶד תַּחַת רַבּוֹ, בְּקוֹל הַתּוֹרָה, בְּקוֹל הַתְּפִלָּה, בְּקוֹל הַשּׁוֹפָר. קוֹל שֶׁהוּא רוֹמַ\"ח אֵלָיו, וְזֶה קוֹל הַשּׁוֹפָר, קוֹל הָעַמּוּד הָאֶמְצָעִי, שֶׁכָּלוּל מֵאֵשׁ מַיִם וְרוּחַ, שֶׁהֵם שְׁלֹשָׁה אָבוֹת שֶׁבָּהֶם הי\"ו, ה' בְּאַבְרָהָם, י' בְּיִצְחָק. בְּכָל מָקוֹם ה' שֶׁשּׁוֹלֶטֶת עַל י' – דִּין הוּא, וְזֶהוּ ה\"י מֵאֱלֹהִים, וְלָכֵן <Nonesmall>[תהלים מז]</small> עָלָה אֱלֹהִים בִּתְרוּעָה. ו' מִן וֵאלֹהֵי יַעֲקֹב, וְזֶה רוּחַ הַשּׁוֹפָר. שְׁכִינָה כְּלִי שֶׁל כָּל הַשָּׁלֹשׁ, וְהוּא ה' מִן הַשּׁוֹפָר.</p>\n<p>שֶׁהֵם עֲשָׂרָה שׁוֹפָרוֹת, שֶׁהֵם קשר\"ק קש\"ק קר\"ק, מִתְלַבְּשִׁים בָּהֶם הֵ\"א יוֹ\"ד וָא\"ו הֵ\"א. שֶׁכָּל הָאוֹתִיּוֹת הַלָּלוּ <Nonesmall>[הן]</small> דִּינִים לִצְדָדִים אֲחֵרִים וְלָרְשָׁעִים. הֵם כְּמוֹ שַׁלְשְׁלָאוֹת וּרְמָחִים וַחֲרָבוֹת. תְּרוּעָה הִיא שַׁלְשֶׁלֶת. וּשְׁתֵּי תְרוּעוֹת יֵשׁ בַּעֲשָׂרָה שׁוֹפָרוֹת, וְהֵן אַחַת.</p>\n<p>שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[דברים כב]</small> וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים <Nonesmall>[או על הביצים. והם]</small>. יִשְׂרָאֵל מְצַפְצְפִים לָהּ בְּכַמָּה צִפְצוּפֵי תְפִלָּה, וְהִיא לֹא רוֹצָה לָרֶדֶת אֲלֵיהֶם. מָה עוֹשִׂים יִשְׂרָאֵל? לוֹקְחִים אֶת הָאִמָּא, שֶׁהִיא שְׁכִינָה אֲלֵיהֶם, וְקוֹשְׁרִים אוֹתָהּ בְּקֶשֶׁר שֶׁל תְּפִלִּין, וּכְשֶׁמַּגִּיעִים לִקְרִיאַת שְׁמַע, קוֹרְאִים בָּנֶיהָ בְּשֵׁשׁ תֵּבוֹת הַיִּחוּד, שֶׁהֵן <Nonesmall>[דברים ח]</small> שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. הֲרֵי הֵם יוֹרְדִים לְאִמָּם וְקוֹשְׁרִים אוֹתָם עִמָּהּ. וְזוֹהִי <Nonesmall>[ויקרא כג]</small> אֲשֶׁר תִּקְרְאוּ אֹתָם, שֶׁהוּא עוֹנָתָהּ, כְּמוֹ מוֹעֲדֵי.</p>"],[9522012646,"<p>כָּךָ כְּמוֹ זֶה מַצָּה, בָּהּ מְזַמְּנִים לְשִׁבְעַת יְמֵי הַפֶּסַח. מְזַמְּנִים אֶת שִׁבְעַת יְמֵי הַסֻּכָּה בְּשִׁבְעָה מִינִים, שֶׁהֵם לוּלָב וְאֶתְרוֹג וּשְׁלֹשָׁה הֲדַסִּים וּשְׁנֵי בַדֵּי עֲרָבָה. שָׁבוּעוֹת קוֹרְאִים לָהֶם בַּתּוֹרָה. רֹאשׁ הַשָּׁנָה יוֹם הַדִּין. כָּל אֶחָד בְּמִינוֹ.</p>\n<p>כָּל מִי שֶׁקָּרָא כָּל דַּרְגָּה בְּמִינָהּ, יִתְקַיֵּם בּוֹ <Nonesmall>[ישעיה נח]</small> אָז תִּקְרָא וַה' יַעֲנֶה. אָ\"ז – שִׁבְעָה יְמֵי סֻכּוֹת, וְחַג שְׁמִינִי עֲצֶרֶת. אָ\"ז – מַצָּה, וְשִׁבְעָה יְמֵי הַפֶּסַח. אָ\"ז – סֻכָּה, וְשִׁבְעָה מִינֵי הַלּוּלָב, שֶׁהֵם שְׁלֹשָׁה הֲדַסִּים וּשְׁתֵּי עֲרָבוֹת, לוּלָב וְאֶתְרוֹג. וּכְלוּלִים בְּאַרְבָּעָה. הֲרֵי אַחַד עָשָׂר כְּחֶשְׁבּוֹן ה\"ו. וְצָרִיךְ לוֹמַר הַלֵּל עֲלֵיהֶם, הַלְלוּיָהּ, לְהַשְׁלִים שֵׁם ה'.</p>\n<p>וְצָרִיךָ לְהַעֲלוֹתָהּ בַּמַּחֲשָׁבָה בְּאַרְבָּעָה מִינִים, זֶהוּ שֶׁכָּתוּב <Nonesmall>[שיר השירים ז]</small> אָמַרְתִּי אֶעֱלֶה בְתָמָר. אֶעֱלֶ\"ה סִימַן: אֶתְרוֹ\"ג, עֲרָבָ\"ה, לוּלָ\"ב, הֲדַ\"ס. וּמַחֲשָׁבָה שֵׁם הַמְפֹרָשׁ, נִשְׁלָם בָּהּ י\"ד, כְּמוֹ י\"ד פִּרְקֵי יַד יָמִין, שֶׁבָּהּ צָרִיךְ לִטֹּל הַלּוּלָב. הֲרֵי מַתַּן תּוֹרָה, שָׁבוּעוֹת, שִׁבְעָה בְשִׁבְעָה – י\"ד. בְּרֹאשׁ הַשָּׁנָה י\"ד בְּקוֹל הַשּׁוֹפָר, וּבְעֶשֶׂר שׁוֹפָרוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ לְמַעְלָה.</p>\n<p>בְּפֶסַח הִיא שְׁכִינָה, יָ\"ד הַגְּדוֹלָה מִצַּד הַחֶסֶד. בְּרֹאשׁ הַשָּׁנָה הִיא יָ\"ד הַחֲזָקָה מִצַּד הַגְּבוּרָה. בְּמַתַּן תּוֹרָה יָ\"ד רָמָה, מִצַּד הָעַמּוּד הָאֶמְצָעִי. וְשָׁלֹשׁ פְּעָמִים י\"ד – מ\"ב. וּשְׁלֹשָׁה אָבוֹת שֶׁתְּלוּיִים מֵהֶם עוֹלִים אַרְבָּעִים וַחֲמִשָּׁה, כְּחֶשְׁבּוֹן יוֹ\"ד הֵ\"א וָא\"ו ה\"א, בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012647,"<p>וַיֵּלֶךָ מֹשֶׁה וַיְדַבֵּר אֶת הַדְּבָרִים הָאֵלֶּה אֶל כָּל יִשְׂרָאֵל. רַבִּי חִזְקִיָּה פָּתַח, <Nonesmall>[ישעיה סג]</small> מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, וּמִשּׁוּם שֶׁהִתְרַצָּה בָהֶם קָרָא לָהֶם בָּנִים בְּכוֹרִים קְדוֹשִׁים, אַחִים <Nonesmall>[כביכול]</small>, וְיָרַד לָדוּר עִמָּהֶם. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמות לה]</small> וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְרָצָה לְהַתְקִינָם כְּמוֹ לְמַעְלָה, וְהִשְׁרָה עֲלֵיֶם שִׁבְעָה עַנְנֵי כָבוֹד, שְׁכִינָה הָלְכָה לִפְנֵיהֶם, זֶהוּ שֶׁכָּתוּב <Nonesmall>[שם יג]</small> וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם.</p>\n<p>שְׁלֹשָה אַחִים קְדוֹשִׁים הָלְכוּ בֵינֵיהֶם, וּמִי הֵם? מֹשֶׁה, אַהֲרֹן וּמִרְיָם. וּבִזְכוּתָם נָתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא מַתָּנוֹת עֶלְיוֹנוֹת <Nonesmall>[והרי נתבאר]</small>. כָּל יְמֵי אַהֲרֹן לֹא זָזוּ עַנְנֵי הַכָּבוֹד מִיִּשְׂרָאֵל, וַהֲרֵי פֵּרְשׁוּהָ <Nonesmall>[משום]</small> שֶׁאַהֲרֹן הָיָה זְרוֹעַ יָמִין שֶׁל יִשְׂרָאֵל, וְהַיְנוּ שֶׁכָּתוּב <Nonesmall>[במדבר כא]</small> וַיִּשְׁמַע הַכְּנַעֲנִי מֶלֶךְ עֲרָד וְגוֹ', כִּי בָּא יִשְׂרָאֵל דֶּרֶךְ הָאֲתָרִים וְגוֹ'. כְּאָדָם שֶׁהוֹלֵךְ לְלֹא זְרוֹעַ וְסוֹמֵךְ עַצְמוֹ לְכָל מָקוֹם, וְאָז – וַיִּלָּחֶם בְּיִשְׂרָאֵל וַיִּשְׁבְּ מִמֶּנּוּ שֶׁבִי, מִשּׁוּם שֶׁהָיוּ בְּלִי זְרוֹעַ יָמִין. <Nonesmall>[ועל זה הצטרכו ישראל לנדר נדר עליו. זהו שכתוב <Nonesmall>[במדבר כא]</small> וידר ישראל נדר לה' ויאמר אם נתן תתן וגו']</small>. בֹּא וּרְאֵה, אַהֲרֹן הָיָה זְרוֹעַ יָמִין שֶׁל הַגּוּף, וְעַל זֶה כָּתוּב מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּמִי הוּא? אַהֲרֹן.</p>\n<p>וַיֵּלֶךָ מֹשֶׁה. מַה זֶּה וַיֵּלֶךְ? לְאָן הָלַךְ? אֶלָּא וַיֵּלֶךְ, כְּגוּף בְּלִי זְרוֹעַ, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[איכה א]</small> וַיֵּלְכוּ בְּלֹא כֹחַ לִפְנֵי רוֹדֵף. שֶׁהֲרֵי מֵת אַהֲרֹן, זְרוֹעַ יָמִין, וְרָצָה לְהִסְתַּלֵּק הַגּוּף. <Nonesmall>[כל ימיו של משה השמש האיר בעולם]</small>.</p>\n<p>כָּל יְמֵי מֹשֶׁה אָכְלוּ יִשְׂרָאֵל לֶחֶם מִן הַשָּׁמַיִם. כֵּיוָן שֶׁבָּא יְהוֹשֻׁעַ מַה כָּתוּב? <Nonesmall>[יהושע ה]</small> וַיִּשְׁבֹּת הַמָּן מִמָּחֳרָת וְגוֹ'. וַיֹּאכְלוּ מֵעֲבוּר הָאָרֶץ מִמָּחֳרַת הַפֶּסַח. מַה בֵּין זֶה לָזֶה? אֶלָּא זֶה מִלְמַעְלָה וְזֶה לְמַטָּה. <Nonesmall>[מכאן למדנו]</small> כָּל הַזְּמַן שֶׁמֹּשֶׁה נִמְצָא, גּוּף הַשֶּׁמֶשׁ שׁוֹלֵט וּמֵאִיר לָעוֹלָם. כֵּיוָן שֶׁהִסְתַּלֵּק מֹשֶׁה, הִתְכַּנֵּס גּוּף הַשֶּׁמֶשׁ, וְיָצָא גוּף הַלְּבָנָה.</p>"],[9522012648,"<p>כָּתוּב <Nonesmall>[שמות לג]</small> אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה וּבַמֶּה יִוָּדַע אֵפוֹא וְגוֹ'. כָּךְ לָמַדְנוּ, כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשׁה <Nonesmall>[שם לב]</small> הִנֵּה מַלְאָכִי יֵלֵךְ לְפָנֶיךְ, אָמַר מֹשֶׁה, וּמַה הַנְהָגַת הַשֶּׁמֶשׁ שֶׁתִּתְכַּנֵּס וְתַנְהִיג הַלְּבָנָה – גּוּף הַלְּבָנָה אֵינִי רוֹצֶה. אִם אֵין פָּנֶיךְ הֹלְכִים, אֲנִי רוֹצֶה אֶת גּוּף הַשֶּׁמֶשׁ, וְלֹא אֶת שֶׁל הַלְּבָנָה. וְאָז גּוּף הַשֶּׁמֶשׁ הוּאַר, וְנַעֲשָׂה מֹשֶׁה כְּמוֹ גוּף הַשֶּׁמֶשׁ לִפְנֵי יִשְׂרָאֵל. כֵּיוָן שֶׁהִתְכַּנֵּס מֹשֶׁה, הִתְכַּנֵּס הַשֶּׁמֶשׁ וְהוּאֲרָה הַלְּבָנָה, וְהָיָה יְהוֹשֻׁעַ מִשְׁתַּמֵּשׁ לְאוֹר הַלְּבָנָה. אוֹי לְאוֹתָהּ בּוּשָׁה!</p>\n<p>וַיֹּאמֶר אֲלֵהֶם בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה וְגוֹ' <Nonesmall>[דברים לא]</small>. הַיְנוּ שֶׁאָמַר רַבִּי אֶלְעָזָר, אַרְבָּעִים שָׁנָה הֵאִיר הַשֶּׁמֶשׁ לְיִשְׂרָאֵל, וְהִתְכַּנֵּס לְסוֹף אַרְבָּעִים שָׁנָה, וְהֵאִירָה הַלְּבָנָה. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי כָּךְ הוּא, הַיְנוּ שֶׁכָּתוּב <Nonesmall>[משלי יג]</small> וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, וְאָנוּ נְבָאֵר אֶת הַפָּסוּק. אֲבָל עַל מַה שֶּׁהִתְעוֹרְרוּ הַחֲבֵרִים, הַכֹּל הוּא צָרִיךְ לָעוֹלָם לְגַלּוֹת <Nonesmall>[לתועלת האדם]</small>, שֶׁהָאָדָם שֶׁנֶּאֱסָף עַד שֶׁלֹּא יַגִּיעוּ יָמָיו.</p>\n<p>בֹּא וּרְאֵה, וַהֲרֵי נִתְבָּאֵר, שֶׁכָּל הָרוּחוֹת שֶׁיּוֹצְאוֹת מִלְמַעְלָה, יוֹצְאוֹת זָכָר וּנְקֵבָה וְנִפְרָדוֹת. וְלִפְעָמִים תֵּצֵא נִשְׁמַת הַנְּקֵבָה עַד שֶׁלֹּא יוֹצֵאת הַזָּכָר, שֶׁהוּא בֶּן זוּגָהּ. וְכָל פְּעָמִים שֶׁזָּכָר לֹא הִגִּיעַ זְמַנּוֹ לְהִזְדַּוֵּג עִם נְקֵבָתוֹ וּבָא אַחֵר וְנָשָׂא אוֹתָהּ – כֵּיוָן שֶׁמַּגִּיעַ זְמַן שֶׁל זֶה לְהִזְדַּוֵּג, כְּשֶׁמִּתְעוֹרֵר צֶדֶק בָּעוֹלָם לִפְקֹד עַל חֲטָאֵי הָעוֹלָם, כּוֹנֵס אֶת הָאַחֵר הַזֶּה שֶׁנָּשָׂא אוֹתָהּ, וּבָא הָאַחֵר וְלוֹקֵחַ אוֹתָהּ. וְעַל זֶה קָשִׁים זִוּוּגִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְכָל זֶה מִשּׁוּם שֶׁהַזָּכָר סָרַח בְּמַעֲשָׂיו. וְאַף עַל גַּב שֶׁלֹּא סָרַח כָּל כָּךְ מַעֲשָׂיו בְּחֶטְאוֹ, הִתְכַּנֵּס בְּאוֹתוֹ זְמַן עַד שֶׁלֹּא הִגִּיעוּ יָמָיו, שֶׁלֹּא עוֹשֶׂה כֵּן בְּמִשְׁפָּט, וְעָלָיו כָּתוּב וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. וּפוֹגֵשׁ בֵּית דִּין שֶׁל צֶדֶק בְּחֶטְאוֹ, מִשּׁוּם שֶׁהִגִּיעַ זְמַנּוֹ שֶׁל הָאַחֵר, וְלוֹקֵחַ אוֹתָהּ, שֶׁהֲרֵי הִיא שֶׁלּוֹ.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, וְלָמָּה יַפְרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְיָבֹא אַחֵר וְיִתֵּן לוֹ? אָמַר לוֹ, זוֹהִי תוֹעַלְתּוֹ שֶׁל הָאָדָם, וְטוֹב שֶׁעוֹשֶׂה עִמּוֹ שֶׁלֹּא תַגִּיעַ <Nonesmall>[יראה את]</small> אִשְׁתּוֹ בְּיַד אַחֵר. וּבֹא וּרְאֵה, אִם זֶה מַעֲשָׂיו אֵינָם כְּשֵׁרִים, אַף עַל גַּב שֶׁהָאִשָּׁה הַזּוֹ הִיא שֶׁלּוֹ, לֹא יִדָּחֶה אַחֵר מִלְּפָנָיו.</p>\n<p>בֹּא וּרְאֵה, שָׁאוּל הַמֶּלֶךְ נָטַל מַלְכוּת, <Nonesmall>[למה, ']</small> מִשּׁוּם שֶׁעֲדַיִן לֹא הִגִּיעַ זְמַנּוֹ שֶׁל דָּוִד לָזֶה, שֶׁהֲרֵי מַלְכוּת הָיְתָה וַדַּאי שֶׁל דָּוִד, וּבָא שָׁאוּל וְלָקַח אוֹתָהּ. כֵּיוָן שֶׁהִגִּיעַ זְמַנּוֹ שֶׁל דָּוִד לָרֶשֶׁת אֶת שֶׁלּוֹ, אָז הִתְעוֹרֵר צֶדֶק <Nonesmall>[מלכות שלמעלה]</small> וְכָנַס אֶת שָׁאוּל בְּחֶטְאוֹ, וְנִדְחָה מִלִּפְנֵי דָוִד, וּבָא דָוִד וְלָקַח אֶת שֶׁלּוֹ.</p>\n<p>וְלָמָּה לֹא הֵסִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שָׁאוּל מֵהַמַּלְכוּת וְלֹא יָמוּת? אֶלָּא טוֹבָה עָשָׂה עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּנַס אוֹתוֹ בְמַלְכוּת, וְלֹא יִרְאֶה עַבְדּוֹ שׁוֹלֵט עָלָיו וְלוֹקֵחַ מַה שֶּׁהָיָה שֶׁלּוֹ בַּתְּחִלָּה. כָּךְ זֶה. מִשּׁוּם כָּךְ צָרִיךְ הָאָדָם לְבַקֵּשׁ רַחֲמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁמִּזְדַּוֵּג, שֶׁלֹּא יִדָּחֶה מִלִּפְנֵי אַחֵר.</p>\n<p>כָּתוּב <Nonesmall>[דברים ג]</small> וַיֹּאמֶר ה' אֵלַי רַב לָךְ אַל תּוֹסֶף דַּבֵּר אֵלַי וְגוֹ'. וַהֲרֵי בֵּאַרְנוּ, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, מֹשֶׁה, הֲתִרְצֶה לְחַדֵּשׁ <Nonesmall>[להחליש]</small> עוֹלָם?! רָאִיתָ מִיָּמֶיךְ שֶׁמֶשׁ עוֹבֵד לַלְּבָנָה?! רָאִיתָ מִיָּמֶיךְ שֶׁתִּשְׁלֹט הַלְּבָנָה בְּעוֹד שֶׁהַשֶּׁמֶשׁ עוֹמֵד?! אֶלָּא – הֵן קָרְבוּ יָמֶיךְ לָמוּת קְרָא אֶת יְהוֹשֻׁעַ. יִתְכַּנֵּס הַשֶּׁמֶשׁ וְתִשְׁלֹט הַלְּבָנָה. וְלֹא עוֹד, אֶלָּא אִם אַתָּה תִּכָּנֵס לָאָרֶץ, תִּתְכַּנֵּס הַלְּבָנָה מִלְּפָנֶיךְ וְלֹא תִשְׁלֹט. וַדַּאי שֶׁשִּׁלְטוֹן הַלְּבָנָה הִגִּיעַ, וְלֹא תִשְׁלֹט בְּעוֹד שֶׁאַתָּה קַיָּם בָּעוֹלָם.</p>\n<p>קְרָא אֶת יְהוֹשֻׁעַ וְגוֹ'. וּמָה אָמַר? הִנְּךְ שֹׁכֵב עִם אֲבֹתֶיךְ וְקָם הָעָם הַזֶּה וְגוֹ'. וְלֹא מָצָאנוּ שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְהוֹשֻׁעַ, אֶלָּא אֶת מֹשֶׁה. שֶׁאָמַר לוֹ לְמֹשֶׁה כָּל זֶה, שֶׁכָּתוּב <Nonesmall>[שם לא]</small> וַעֲזָבַנִי וְהֵפֵר אֶת בְּרִיתִי. וְחָרָה אַפִּי בוֹ בַּיּוֹם הַהוּא. וְעַתָּה כִּתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת וְלַמְּדָהּ אֶת בְּנֵי יִשְׂרָאֵל שִׂימָהּ בְּפִיהֶם. אִם כֵּן, מַהוּ וַאֲצַוֶּנּוּ?</p>\n<p>אֶלָּא הַכָּתוּב אָמַר, הִנְּךְ שֹׁכֵב עִם אֲבֹתֶיךְ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, אַף עַל גַּב שֶׁתִּשְׁכַּב עִם אֲבוֹתֶיךְ, הֲרֵי אַתָּה תָּמִיד קַיָּם לְהָאִיר לַלְּבָנָה, כְּמוֹ שֶׁהַשֶּׁמֶשׁ, שֶׁאַף עַל גַּב שֶׁמִּתְכַּנֵּס, לֹא מִתְכַּנֵּס אֶלָּא לְהָאִיר לַלְּבָנָה, וְאָז מֵאִיר לַלְּבָנָה כְּשֶׁמִּתְכַּנֵּס. וְעַל זֶה הִנְּךְ שּכֵב, לְהָאִיר, וְזֶהוּ וַאֲצַוֶּנּוּ. וְאָז <Nonesmall>[הכשר]</small> הִתְבַּשֵּׂר יְהוֹשֻׁעַ לִהְיוֹת מוּאָר, וְעַל זֶה כָּתוּב הִנְּךְ שֹׁכֵב עִם אֲבֹתֶיךְ, לְהָאִיר לִיהוֹשֻׁעַ, וְזֶהוּ <Nonesmall>[דברים ג]</small> וְצַו אֶת יְהוֹשֻׁעַ וְחַזְּקֵהוּ. וְצַו אֶת יְהוֹשֻׁעַ, הַכֹּל כְּדֵי לְהָאִיר.</p>\n<p>כִּי אַתָּה תָּבֹא, וְאַחַר כָּךְ תָּבִיא, מַה בֵּין זֶה לָזֶה? אֶלָּא אֶחָד תָּבֹא, לְבַשֵּׂר לוֹ שֶׁיִּכָּנֵס לָאָרֶץ וְיִתְקַיֵּם בָּהּ. וְאֶחָד תָּבִיא, לְבַשֵּׂר לוֹ אֶת הַשִּׁלְטוֹן עַל יִשְׂרָאֵל, וְהִתְבַּשֵּׂר עַל קִיּוּם שֶׁל עַצְמוֹ, וְהִתְבַּשֵּׂר עַל שִׁלְטוֹן שֶׁל יִשְׂרָאֵל.</p>"],[9522012649,"<p>רַבִּי שִׁמְעוֹן פָּתַח, <Nonesmall>[ישעיה כד]</small> מִכְּנַף הָאָרֶץ זְמִרֹת שָׁמַעְנוּ צְבִי לַצַּדִּיק וְגוֹ'. אוֹי לָהֶם לִבְנֵי אָדָם, לְאוֹתָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא מִשְׁתַּדְּלִים בִּכְבוֹד רִבּוֹנָם וְלֹא מִסְתַּכְּלִים בַּקְּדֻשָּׁה הָעֶלְיוֹנָה לְהִתְקַדֵּשׁ בָּעוֹלָם הַזֶּה, לִהְיוֹת קְדוֹשִׁים בָּעוֹלָם הַבָּא. מִכְּנַף הָאָרֶץ – זוֹ כְּסוּת עֶלְיוֹנָה קְדוֹשָׁה. זְמִרֹת שָׁמַעְנוּ, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[איוב לה]</small> נֹתֵן זְמִרוֹת בַּלָּיְלָה. זְמִרוֹת, תִּשְׁבָּחוֹת שֶׁל כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בַּלַּיְלָה. בַּלָּיְלָה, בִּזְמַן שֶׁהִיא הִזְדַּמְּנָה <Nonesmall>[שהקדוש ברוך הוא]</small> <Nonesmall>[מזדוגת ומצויה]</small> וּמְצוּיָה לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן.</p>\n<p>וּמָתַי, ? מֵחֲצוֹת הַלַּיְלָה וְאֵילָךְ. וְאָז זְמִרֹת שָׁמַעְנוּ <Nonesmall>[בלילה]</small>, תִּשְׁבָּחוֹת. וּזְמִירוֹת, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[ויקרא כה]</small> לֹא תִזְמֹר. וְכָתוּב <Nonesmall>[ישעיה כה]</small> זְמִיר עָרִיצִים יַעֲנֶה, עִקּוּר מִמְּקוֹמָם שֶׁל כָּל אוֹתָם תַּקִּיפִים. שֶׁהֲרֵי כְּשֶׁנִּכְנָס הַלַּיְלָה, כַּמָּה עָרִיצִים מַחֲנוֹת מַזִּיקִים שׁוֹמְרֵי הַחֻקִּים מְצוּיִים בָּעוֹלָם, הוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם לְקַטְרֵג. מֵחֲצוֹת הַלַּיְלָה וְאֵילָךְ מִתְעוֹרֶרֶת רוּחַ אַחַת וְעוֹקֶרֶת אֶת כֻּלָּם מִמְּקוֹמוֹתֵיהֶם, וּמַעֲבִירָה אוֹתָם כְּדֵי שֶׁלֹּא יִשְׁלְטוּ. זְמִרֹת שָׁמַעְנוּ, תִּשְׁבָּחוֹת שֶׁל כְּנֶסֶת יִשְׂרָאֵל בַּלַּיְלָה. וְכָל זֶה לָמָּה? צְבִי לַצַּדִּיק, לְהִזְדַּוֵּג בְּזִוּוּג אֶחָד <Nonesmall>[לקדוש]</small> שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְקַדֵּשׁ בִּקְדֻשָּׁה אַחַת.</p>\n<p>וָאֹמַר רָזִי לִי רָזִי לִי – זֶהוּ סוֹד עֶלְיוֹן, זֶהוּ רוּחַ קְדוֹשָׁה. אֲבָל, אוֹי לִי – עַל הַדּוֹר וְעַל הָעוֹלָם. בּוֹגְדִים בָּגָדוּ, שֶׁכֻּלָּם מְשַׁקְּרִים בּוֹ, מְשַׁקְּרִים בָּהֶם בְּעַצְמָם. וְלֹא דַי שֶׁמְּשַׁקְּרִים בְּעַצְמָם <Nonesmall>[ממש]</small>, אֶלָּא אוֹתָם בָּנִים שֶׁיָּלְדוּ מִשְׁתַּקְּרִים בְּאוֹתוֹ שֶׁקֶר שֶׁלָּהֶם, וְנִמְצָאִים פְּגוּמִים לְמַעְלָה וּמַטָּה.</p>\n<p>כֵּיוָן שֶׁיְּשַׁעְיָהוּ הִסְתַּכֵּל בָּזֶה, כִּנֵּס אֶת אוֹתָם יִרְאֵי חֵטְא וְלִמֵּד אוֹתָם דֶּרֶךְ קְדוֹשָׁה לְהִתְקַדֵּשׁ בִּקְדֻשַּׁת הַמֶּלֶךְ וּלְהִמָּצֵא בְנֵיהֶם קְדוֹשִׁים. כֵּיוָן שֶׁאֵלֶּה הִתְקַדְּשׁוּ, אוֹתָם בָּנִים שֶׁיָּלְדוּ נִקְרְאוּ עַל שְׁמוֹ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה ח]</small> הִנֵּה אָנֹכִי וְהַיְלָדִים אֲשֶׁר נָתַן לִי ה' לְאֹתוֹת וּלְמוֹפְתִים בְּיִשְׂרָאֵל, שֶׁפְּרוּשִׁים מִשְּׁאָר הָעַמִּים.</p>\n<p>דָּבָר אַחֵר מִכְּנַף הָאָרֶץ זְמִרֹת שָׁמַעְנוּ – בְּשָׁעָה שֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ וְהָאָרוֹן הַקָּדוֹשׁ עוֹמֵד לִפְנֵיהֶם, שָׁמְעוּ יִשְׂרָאֵל שֶׁמִּצַּד אֶחָד שֶׁל הָאָרֶץ תִּשְׁבָּחוֹת וְשִׂמְחָה וְקוֹל מְזַמְּרִים עֶלְיוֹנִים שֶׁמְּזַמְּרִים בָּאָרֶץ, וְאָז צְבִי לַצַּדִּיק, תִּשְׁבַּחַת מֹשֶׁה הָיְתָה בְּאוֹתָהּ שָׁעָה. שֶׁבְּכָל מָקוֹם שֶׁבּוֹ הָיָה שָׁרוּי הָאָרוֹן, הָיוּ שׁוֹמְעִים קוֹל שֶׁאוֹמֵר: <Nonesmall>[דברים ד]</small> וְזֹּאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. אֲבָל אוֹי לִי שֶׁבּוֹגְדִים בָּגָדוּ, שֶׁעֲתִידִים יִשְׂרָאֵל לְשַׁקֵּר בַּהַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהֵעָקֵר מֵהָאָרֶץ פַּעַם אַחַת. וּמִשּׁוּם שֶׁנֶּאֱחַז בֵּינֵיהֶם הַשֶּׁקֶר שֶׁלָּהֶם, יֵעָקֵר פַּעַם שְׁנִיָּה, עַד שֶׁיֻּשְׁלַם חַטָּאתָם בְּאֶרֶץ אַחֶרֶת.</p>"],[9522012650,"<p>לָקֹחַ אֵת סֵפֶר הַתּוֹרָה הַזֶּה וְגוֹ'. הֲרֵי בֵּאַרְנוּ הַדְּבָרִים. אֱלֹהֵיכֶם. אֱלֹהֶיךְ. אֵל. אֱלֹהֵינוּ.</p>\n<p>שֶׁאָמַר רַבִּי אַבָּא אָמַר רַבִּי יְהוּדָה, מַהוּ שֶׁכָּתוּב <Nonesmall>[שמות ג]</small> כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא? אַדְמַת קֹדֶשׁ וַדַּאי, שֶׁהַיְנוּ אֶרֶץ הַחַיִּים. אֶרֶץ אֲשֶׁר אַתָּה עֹמֵד עָלָיו, עָלָיו וַדַּאי, הַיְנוּ בַּתְּחִלָּה, וְכָל שֶׁכֵּן לְאַחַר כָּךְ. לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, כָּתוּב וְהָיָה שָׁם בְּךְ לְעֵד, לְעֵד וַדַּאי, שֶׁיָּעִיד עֵדוּת.</p>\n<p>שְׁלֹשָה הֵם שֶׁעוֹמְדִים בְּעֵדוּת לְהָעִיד, וְאֵלֶּה הֵם: בְּאֵר יִצְחָק, גּוֹרָל, וְהָאֲבָנִים שֶׁשָּׂם יְהוֹשֻׁעַ. וְשִׁירָה זוֹ עֵדוּת יוֹתֵר מֵהַכֹּל. אָמַר רַבִּי יִצְחָק, אִם כָּךְ, אַרְבָּעָה הֵם. אָמַר לוֹ, וַדַּאי, אֲבָל בַּגּוֹרָל לֹא כָתוּב עֵדוּת.</p>\n<p>בְּאֵר שֶׁל יִצְחָק מִנַּיִן לָנוּ? שֶׁכָּתוּב <Nonesmall>[בראשית כא]</small> בַּעֲבוּר תִּהְיֶה לִּי לְעֵדָה וְגוֹ'. גּוֹרָל – שֶׁכָּתוּב <Nonesmall>[במדבר כו]</small> עַל פִּי הַגּוֹרָל תֵּחָלֵק נַחֲלָתוֹ. שֶׁהָיָה אוֹמֵר: זֶה לִיהוּדָה, וְזֶה לְבִנְיָמִין, וְכֵן לְכֻלָּם. הָאֲבָנִים שֶׁל יְהוֹשֻׁעַ – שֶׁכָּתוּב <Nonesmall>[יהושע כד]</small> הִנֵּה הָאֶבֶן הַזֹּאת תִּהְיֶה בָּנוּ לְעֵדָה. וְכָאן, וְהָיָה שָׁם בְּךְ לְעֵד. וְכָתוּב וְעָנְתָה הַשִּׁירָה הַזֹּאת לְפָנָיו לְעֵד. הִיא וַדַּאי הֵעִידָה בָהֶם בְּיִשְׂרָאֵל.</p>"],[9522012651,"<p>לָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, מַה שֶּׁכָּתוּב וַיְדַבֵּר מֹשֶׁה וְגוֹ', אֶת דִּבְרֵי הַשִּׁירָה הַזֹּאת עַד תֻּמָּם? כָּאן יֵשׁ לְהִסְתַּכֵּל, מַהוּ אֶת דִּבְרֵי? אֶת הַשִּׁירָה הַזֹּאת צָרִיךְ לוֹ לִהְיוֹת! וּמַה זֶּה עַד תֻּמָּם? אֶלָּא כָּךְ לָמַדְנוּ בְּסוֹד הַמִּשְׁנָה, כָּל אוֹתָם דְּבָרִים שֶׁאָמַר מֹשֶׁה, כֻּלָּם נֶחְקְקוּ בְשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל אוֹתָם דְּבָרִים הָיוּ בָאִים, וְעוֹלִים וְיוֹרְדִים, וְנֶחְקָקִים שָׁם. וְכָל דָּבָר וְדָבָר הָיָה בָּא לִפְנֵי מֹשֶׁה לְהֵחָקֵק עַל יָדוֹ וְעוֹמֵד לְפָנָיו. וְהַיְנוּ מַה שֶּׁכָּתוּב עַד תֻּמָּם.</p>\n<p>רַבִּי אַבָּא אָמַר, אֶת דִּבְרֵי הַשִּׁירָה הַזֹּאת, שִׁירָה הַזֹּאת צָרִיךְ לוֹ לִהְיוֹת! מַה זֶּה רוֹמֵז? אֶלָא שִׁירָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, מֶלֶךְ שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים. <Nonesmall>[ששנינו שכתוב]</small> <Nonesmall>[תהלים צב]</small> מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, לְיוֹם הַשַּׁבָּת מַמָּשׁ. שִׁיר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר. <Nonesmall>[שיר השירים אשר לשלמה, שיר שהקדוש ברוך הוא אמר. וכאן את דברי השירה הזאת, שיר שהקדוש ברוך הוא אמר]</small>.</p>\n<p>אֶלָּא כָּאן יֵשׁ לְהִסְתַּכֵּל, שָׁם שִׁיר, וְכָאן שִׁירָה. זֶה זָכָר, וְזוֹ נְקֵבָה. וַהֲרֵי שָׁנִינוּ, כָּל הַנְּבִיאִים כֻּלָּם לְגַבֵּי מֹשֶׁה כְּמוֹ קוֹף בְּעֵינֵי בְּנֵי אָדָם, וְהֵם אָמְרוּ שִׁיר, וּמֹשֶׁה אָמַר שִׁירָה. <Nonesmall>[ומנין לנו שזו היא נקבה, ' שכתוב וענתה השירה וגו']</small> מֹשֶׁה הָיָה לוֹ לוֹמַר שִׁיר, וְהֵם שִׁירָה. אֶלָּא זֶהוּ סוֹד הַדָּבָר, מֹשֶׁה לֹא אָמַר אֶת זֶה לְעַצְמוֹ, אֶלָּא לְיִשְׂרָאֵל.</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, לֹא כָּךְ, אֶלָּא מֹשֶׁה וַדַּאי נוֹדַע מִכָּאן שֶׁהוּא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה מֵהַכֹּל. מֹשֶׁה עָלָה מִלְּמַטָּה לְמַעְלָה, וְהֵם יָרְדוּ מִלְמַעְלָה לְמַטָּה. הוּא עָלָה מִלְּמַטָּה לְמַעְלָה, כְּמוֹ שֶׁשָּׁנִינוּ, מַעֲלִין בַּקֹּדֶשׁ וְאֵין מוֹרִידִין. מֹשֶׁה עָלָה מִלְּמַטָּה לְמַעְלָה, שֶׁאָמַר שִׁירָה, תִּשְׁבַּחַת הַמַּלְכָּה שֶׁהִיא מְשַׁבַּחַת לַמֶּלֶךְ. וּמֹשֶׁה נֶאֱחַז בַּכֹּל <Nonesmall>[במלך]</small>. וְהֵם יָרְדוּ מִלְמַעְלָה לְמַטָּה, שֶׁאָמְרוּ שִׁיר, שֶׁהוּא שֶׁבַח שֶׁמְּשַׁבֵּחַ הַמֶּלֶךְ אֶת הַמַּלְכָּה, וְהֵם נֶאֶחְזוּ בַמַּלְכָּה. וְעַל זֶה בָּזֶה נוֹדַע שִׁבְחוֹ שֶׁל מֹשֶׁה יוֹתֵר מִכֻּלָּם. וְהַיְנוּ שֶׁכָּתוּב, <Nonesmall>[שמות טו]</small> אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַה'. שִׁיר הַמַּלְכָּה. לְמִי? לַה'. וְלָכֵן וַיִּכְתֹּב מֹשֶׁה אֶת דִּבְרֵי הַשִּׁירָה הַזֹּאת, וְעָנְתָה הַשִּׁירָה הַזֹּאת.</p>\n<p>וְעָנְתָה הַשִּׁירָה הַזֹּאת?! וְעָנוּ הַדְּבָרִים הָאֵלֶּה הָיָה צָרִיךְ לוֹ לִהְיוֹת! אֶלָּא סוֹד הַדָּבָר כְּפִי שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב <Nonesmall>[איוב כ]</small> וְאֶרֶץ מִתְקוֹמָמָה לוֹ, וּמֹשֶׁה הִסְתַּכֵּל בַּכֹּל, וְעַל זֶה אָמַר שִׁירָה, כְּדֵי לֶאֱחֹז דְּבָרִים בַּמָּקוֹם הַזֶּה לִהְיוֹת עֲלֵיהֶם דִּין, שֶׁכָּתוּב וְעָנְתָה הַשִּׁירָה הַזֹּאת לְפָנָיו. וְלָמָּה? שֶׁכָּתוּב כִּי אֲנִי יָדַעְתִּי אֶת יִצְרוֹ, וְכָתוּב כִּי יָדַעְתִּי אַחֲרֵי מוֹתִי וְגוֹ'. וּכְשֶׁתַּעֲשׂוּ אֶת זֶה, מִיָּד – וְעָנְתָה הַשִּׁירָה הַזֹּאת לְפָנָיו לְעֵד.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב יְגַלּוּ שָׁמַיִם עֲונוֹ, וְלֹא יוֹתֵר, אֲבָל – וְאֶרֶץ מִתְקוֹמָמָה לוֹ. בָּזֶה נַעֲשֶׂה דִין לְמִי שֶׁנַּעֲשֶׂה.</p>\n<p>כָּתוּב, <Nonesmall>[שמואל ב כב]</small> וַיְדַבֵּר דָּוִד לַה' אֶת דִּבְרֵי הַשִּׁירָה הַזֹּאת. כָּאן תִּשְׁבַּחַת שֶׁל דָּוִד הִיא, מִשּׁוּם שֶׁאָמַר שִׁירָה מִלְּמַטָּה לְמַעְלָה, וְזָכָה לַדַּרְגָּה הַזּוֹ, וְלֹא אָמַר שִׁירָה זוֹ אֶלָּא בְּסוֹף יָמָיו, שֶׁהָיָה יוֹתֵר בִּשְׁלֵמוּת מֵהַשִּׁירָה הַזּוֹ, כְּמוֹ שֶׁשָּׁנִינוּ <Nonesmall>[אבות פ\"ב]</small> אַל תַּאֲמֵן בְּעַצְמָךְ עַד יוֹם מוֹתָךְ. וְכָאן לָמָּה זָכָה דָוִד לוֹמַר שִׁירָה מִלְּמַטָּה לְמַעְלָה בְּסוֹף יָמָיו? שֶׁהָיָה בִמְנוּחָה מִכָּל צְדָדָיו, שֶׁכָּתוּב בְּיוֹם הִצִּיל ה' אֹתוֹ מִכַּף כָּל אֹיְבָיו.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, שִׁירָה מְעֻלָּה מֵהַכֹּל מַהִי? כְּמוֹ שֶׁשָּׁנִינוּ בְּסוֹד הַמִּשְׁנָה, בְּדִבּוּרִים וּבְמַעֲשֶׂה כָּךְ <Nonesmall>[הוא]</small> גַּם מִלְּמַטָּה לְמַעְלָה וּמִלְמַעְלָה לְמַטָּה, וְאַחַר כָּךְ לְכַוֵּן אֶת הַלֵּב, וְלִקְשֹׁר הַכֹּל בְּקֶשֶׁר אֶחָד.</p>"],[9522012652,"<p>מִנַּיִן לָנוּ? מִמֹּשֶׁה, בַּהַתְחָלָה מִלְּמַטָּה לְמַעְלָה, <Nonesmall>[דברים לב]</small> כִּי שֵׁם ה' אֶקְרָא. מַה זֶּה אֶקְרָא? כְּמוֹ שֶׁכָּתוּב וַיִּקְרָא אֶל מֹשֶׁה – זוֹ הַשְּׁכִינָה. אַחַר כָּךְ, הָבוּ גֹדֶל לֵאלֹהֵינוּ – זֶה מֶלֶךְ הָעֶלְיוֹן. אַחַר כָּךְ יָרַד בְּדַרְגוֹתָיו מִלְּמַעְלָה לְמַטָּה, שֶׁכָּתוּב צַדִּיק וְיָשָׁר. אַחַר כָּךְ קוֹשֵׁר קֶשֶׁר הָאֱמוּנָה וְאוֹמֵר הוּא, וְזֶהוּ קֶשֶׁר לַכֹּל.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ אָדָם לְסַדֵּר שֶׁבַח רִבּוֹנוֹ כְּמוֹ זֶה. בַּהַתְחָלָה מִלְּמַטָּה לְמַעְלָה, לְהַעֲלוֹת כְּבוֹד רִבּוֹנוֹ לְמָקוֹם שֶׁהַשְׁקָאַת עֹמֶק הַבְּאֵר שׁוֹפַעַת וְיוֹצֵאת. אַחַר כָּךְ <Nonesmall>[שופע]</small> לְהַמְשִׁיךְ מִלְמַעְלָה לְמַטָּה מֵאוֹתָהּ הַשְׁקָאַת הַנַּחַל לְכָל דַּרְגָּה וְדַרְגָּה, עַד הַדַּרְגָּה הָאַחֲרוֹנָה, לְהַמְשִׁיךְ בְּרָכוֹת לַכֹּל מִלְמַעְלָה לְמַטָּה. אַחַר כָּךְ צָרִיךְ לִקְשֹׁר קֶשֶׁר בַּכֹּל, קֶשֶׁר הָאֱמוּנָה. וְזֶהוּ הָאָדָם שֶׁמְּכַבֵּד שֵׁם רִבּוֹנוֹ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְעַל זֶה כָּתוּב <Nonesmall>[שמואל א ב]</small> כִּי מְכַבְּדַי אֲכַבֵּד. כִּי מְכַבְּדַי – לָעוֹלָם הַזֶּה. אֲכַבֵּד – לָעוֹלָם הַבָּא.</p>\n<p>וּבֹזַי יֵקָלּוּ. מַה זֶה וּבֹזַי יֵקָלּוּ? זֶהוּ מִי שֶׁלֹּא יוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְלִקְשֹׁר קֶשֶׁר הָאֱמוּנָה, וּלְהַמְשִׁיךְ בְּרָכוֹת לְמָקוֹם שֶׁצָּרִיךְ וּלְכַבֵּד שֵׁם רִבּוֹנוֹ. וְכָל מִי שֶׁלֹּא יוֹדֵעַ לְכַבֵּד אֶת שֵׁם רִבּוֹנוֹ, טוֹב לוֹ שֶׁלֹּא נִבְרָא.</p>"],[9522012653,"<p>אָמַר רַבִּי יְהוּדָה, וּבזַי יֵקָלּוּ, מִי שֶׁלֹּא לְכַבֵּד אֶת רִבּוֹנוֹ וְלֹא מִתְכַּוֵּן בָּאָמֵן, שֶׁשָּׁנִינוּ, גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְבָרֵךְ. וַהֲרֵי בֵּאַרְנוּ לִפְנֵי רַבִּי שִׁמְעוֹן, שֶׁאָמֵן מוֹשֵׁךְ בְּרָכוֹת מִמַּבּוּעַ הַמֶּלֶךְ, וּמֵהַמֶּלֶךְ לַמַּלְכָּה <Nonesmall>[זו כנסת ישראל]</small>. וּבְאוֹתִיּוֹת חֲקוּקוֹת שֶׁל רַבִּי אֶלְעָזָר, מֵאָלֶ\"ף לְמֵ\"ם, וּמִמֵּ\"ם לְנוּ\"ן. כֵּיוָן שֶׁמַּגִּיעוֹת הַבְּרָכוֹת לְנוּ\"ן, מִשָּׁם שׁוֹפְעוֹת וְיוֹצְאוֹת בְּרָכוֹת לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים וּמִתְפַּשְּׁטוֹת בַּכֹּל. וְקוֹל יוֹצֵא: הִשָּׁקוּ מֵהַשְׁקָאַת הַבְּרָכוֹת שֶׁהוֹצִיא פְּלוֹנִי עֶבֶד הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וּכְשֶׁיִּשְׂרָאֵל לְמַטָּה מְשַׁמְּרִים לְהָשִׁיב אָמֵן, לְכַוֵּן לִבָּם כְּמוֹ שֶׁצָּרִיךְ, כַּמָּה פִּתְחֵי בְרָכוֹת פְּתוּחִים לוֹ לְמַעְלָה, כַּמָּה טוֹבוֹת נִמְצָאוֹת בְּכָל הָעוֹלָמוֹת, כַּמָּה שִׂמְחָה בַּכֹּל. מָה הַשָּׂכָר לְיִשְׂרָאֵל שֶׁגָּרְמוּ אֶת זֶה? שָׂכָר לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. בָּעוֹלָם הַזֶּה בְּשָׁעָה שֶׁמְּצִיקִים לָהֶם <Nonesmall>[לישראל]</small> וּמִתְפַּלְלִים תְּפִלָּה לִפְנֵי רִבּוֹנָם, קוֹל מַכְרִיז בְּכָל הָעוֹלָמוֹת: <Nonesmall>[ישעיה כו]</small> פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק שֹׁמֵר אֱמֻנִים. אַל תִּקְרֵי אֱמוּנִים אֶלָּא אֲמֵנִים. פִּתְחוּ שְׁעָרִים, כְּמוֹ שֶׁלְּיִשְׂרָאֵל פּוֹתְחִים שַׁעֲרֵי הַבְּרָכוֹת, כָּךְ כָּעֵת פִּתְחוּ שְׁעָרִים, וְתִתְקַבֵּל תְּפִלָּתָם מֵאוֹתָם שֶׁמְּצִיקִים לָהֶם.</p>\n<p>זְהִ בָּעוֹלָם הַזֶּה. בָּעוֹלָם הַבָּא מַה שְּׂכָרָם? שֶׁכְּשֶׁיֵּצֵא אָדָם מֵהָעוֹלָם הַזֶּה, שֶׁהָיָה שׁוֹמֵר לְהָשִׁיב אָמֵן, מַה זֶּה שׁוֹמֵר? כְּלוֹמַר, שׁוֹמֵר אוֹתָהּ בְּרָכָה שֶׁאָמַר אוֹתוֹ הַמְבָרֵךְ, וּמְחַכֶּה לוֹ לְהָשִׁיב אָמֵן כְּמוֹ שֶׁצָּרִיךְ. נִשְׁמָתוֹ עוֹלָה, וּמַכְרִיזִים לְפָנֶיהָ: פִּתְחוּ שְׁעָרִים לְפָנָיו, כְּמוֹ שֶׁהוּא הָיָה פּוֹתֵחַ שְׁעָרִים כָּל יוֹם כְּשֶׁהָיָה שׁוֹמֵר אֱמוּנִים.</p>\n<p>אָמַר רַבִּי יוֹסֵי אָמַר רַבִּי יְהוּדָה, מַה זֶּה אָמֵן? אָמַר רַבִּי אַבָּא, הֲרֵי פֵּרְשׁוּהָ הַכֹּל. אָמֵן נִקְרָא מַבּוּעַ שֶׁל אוֹתוֹ הַנַּחַל שֶׁשּׁוֹפֵעַ, אָמֵן נִקְרָא, שֶׁכָּתוּב <Nonesmall>[משלי ח]</small> וָאֶהְיֶה אֶצְלוֹ אָמוֹן. אַל תִּקְרֵי אָמוֹן אֶלָּא אָמֵן. קִיּוּם הַכֹּל אוֹתוֹ הַנַּחַל <Nonesmall>[הטל]</small> שֶׁשּׁוֹפֵעַ וְיוֹצֵא, אָמֵן נִקְרָא. שֶׁלָּמַדְנוּ, <Nonesmall>[תהלים קו]</small> מִן הָעוֹלָם וְעַד הָעוֹלָם – עוֹלָם שֶׁלְּמַעְלָה, עוֹלָם שֶׁלְּמַטָּה. גַּם כָּךְ אָמֵן וְאָמֵן – אָמֵן שֶׁלְּמַעְלָה, אָמֵן שֶׁלְּמַטָּה. אָמֵן קִיּוּם שֶׁל כֻּלָּם, וַהֲרֵי בֵּאַרְנוּ אָמֵן בְּאוֹתָן אוֹתִיּוֹת.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אָלֶ\"ף עֹמֶק הַבְּאֵר שֶׁכָּל הַבְּרָכוֹת, מִשָּׁם נוֹבְעוֹת וְיוֹצְאוֹת וְנִמְצָאוֹת. מֵ\"ם פְּתוּחָה, נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְנִקְרָא מֵ\"ם. וְהוּא סוֹד שֶׁשָּׁנִינוּ, מֵ\"ם פְּתוּחָה, מֵ\"ם סְתוּמָה, כְּמוֹ שֶׁבֵּאַרְנוּ <Nonesmall>[ישעיה ט]</small> לְםַרְבֵּה הַמִּשְׂרָה.</p>\n<p>נוּ\"ן פְּשׁוּטָה, כְּלָל שֶׁל שְׁתֵּי נוּנִין. נוּ\"ן כְּפוּפָה, כְּלָל שֶׁל הָאוֹת וָא\"ו, כְּלָל שֶׁל נוּן כְּפוּפָה <Nonesmall>[פשוטה]</small>. <Nonesmall>[מ\"ם פתוחה, כלל של שתי נונין נון פשוטה, נון כפופה. נון פשוטה כלל של האות וא\"ו,]</small> מִשּׁוּם כָּךְ הַכֹּל נִקְרָא נוּן וָאו נוּן. וּבְסוֹד הַמִּשְׁנָה כָּךְ שָׁנִינוּ, ו' זָכָר, ן' פְּשׁוּטָה כְּלָל שֶׁל זָכָר וּנְקֵבָה. נוּן כְּפוּפָה בִּכְלָל שֶׁל פְּשׁוּטָה הִיא. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, מֵ\"ם שֶׁל כָּאן הִיא נוֹטְרִיקוֹן מֶלֶ\"ךְ, וְהַיְנוּ אָמֵן. אָמֵ\"ן נוֹטְרִיקוֹן אֵ\"ל מֶ\"לֶךְ נֶ\"אֱמָן. כְּלָל שֶׁל הַכֹּל, וְיָפֶה הוּא, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>לָמַדְנוּ, כָּל מִי שֶׁשָּׁמַע בְּרָכָה מֵאוֹתוֹ מְבָרֵךְ וְלֹא מְכַוֵּן בָּאָמֵן, עָלָיו נֶאֱמַר וּבֹזַי יֵקָלּוּ, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[מלאכי א]</small> לָכֶם הַכֹּהֲנִים בּוֹזֵי שְׁמִי. מָה עָנְשׁוֹ? כְּמוֹ שֶׁלֹּא פָתַח בְּרָכוֹת לְמַעְלָה, כָּךְ לֹא פוֹתְחִים לוֹ. וְלֹא עוֹד, אֶלָּא כְּשֶׁיּוֹצֵא מֵהָעוֹלָם הַזֶּה, מַכְרִיזִים לְפָנָיו וְאוֹמְרִים: סִגְרוּ הַפְּתָחִים לִפְנֵי פְּלוֹנִי וְלֹא יִכָּנֵס, וְאַל תְּקַבְּלוּ אוֹתוֹ. אוֹי לוֹ! אוֹי לְנִשְׁמָתוֹ!</p>"],[9522012654,"<p>לָמַדְנוּ, כָּל רִשְׁעֵי הַגֵּיהִנֹּם נִכְנָסִים לִמְדוֹרִים יְדוּעִים, וְכַמָּה פְתָחִים יֵשׁ לַגֵּיהִנֹּם, וְכָל הַפְּתָחִים כְּנֶגֶד פִּתְחֵי הַגַּן עֵדֶן. וּבְשָׁעָה שֶׁמּוֹצִיאִים אוֹתָם רְשָׁעִים שֶׁקִּבְּלוּ עָנְשָׁם, הֵם פּוֹתְחִים פְּתָחִים, וְשָׂמִים <Nonesmall>[ושואבים]</small> אוֹתָם לַחוּץ. וְכָל הַפְּתָחִים נִקְרְאוּ בִשְׁמָם כְּנֶגֶד פִּתְחֵי הַגַּן עֵדֶן, וְכָל פֶּתַח וּפֶתַח נִקְרָא שֵׁם כְּנֶגֶד אוֹתוֹ פֶּתַח הַגֵּיהִנֹּם, וְהַפְּתָחִים נוֹדָעִים כְּנֶגֶד הַפְּתָחִים, אוֹתָם פִּתְחֵי הַגַּן עֵדֶן.</p>\n<p>בַּגֵּיהִנֹּם יֵשׁ מָדוֹר אַחֲרוֹן תַּחְתּוֹן שֶׁל כֻּלָּם, וְאוֹתוֹ מָדוֹר הוּא מָדוֹר עַל מָדוֹר, וְנִקְרָא <Nonesmall>[איוב י]</small> אֶרֶץ עֵיפָתָה. מַה זֶּה עֵיפָתָה? כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שמות כח]</small> רָבוּעַ יִהְיֶה כָּפוּל, וּמְתַרְגְּמִים – מְרֻבָּע יִהְיֶה עֵיף. גַּם כָּאן עֵיפָתָה, כְּלוֹמַר כְּפוּלָה. וְאוֹתוֹ נִקְרָא שְׁאוֹל תַּחְתִּית, שְׁאוֹל הוּא מָדוֹר אֶחָד, תַּחְתִּית הוּא מָדוֹר תַּחְתּוֹן. וְלָכֵן נִקְרֵאת אֶרֶץ עֵיפָתָה תַּחְתִּית, וְנִקְרֵאת אֲבַדּוֹן, וְעַל זֶה כָּתוּב <Nonesmall>[משלי טו]</small> שְׁאוֹל וַאֲבַדּוֹן. וְכָל הַמְּדוֹרִים לֹא נִכְפְּלוּ, וְכֻלָּם לֹא מִתְעַיְּפִים חוּץ מִזֶּה.</p>\n<p>וְלָמַדְנוּ, מִי שֶׁיּוֹרֵד לַאֲבַדּוֹן, שֶׁנִּקְרָא תַחְתִּית, לֹא עוֹלֶה לְעוֹלָמִים. וְהַהוּא נִקְרָא אִישׁ שֶׁמֻּשְׁמָד וְנֶאֱבָד מִכָּל הָעוֹלָמוֹת. וְלָמַדְנוּ, לְאוֹתוֹ מָקוֹם מוֹרִידִים אוֹתָם אֲנָשִׁים שֶׁמְּבַזִּים לְהָשִׁיב אָמֵן, וְעַל אָמֵן הַרְבֵּה שֶׁנֶּאֶבְדוּ מִמֶּנּוּ, שֶׁלֹּא הֶחֱשִׁיב אוֹתָם, דָּנִים אוֹתוֹ בַּגֵּיהִנֹּם, וּמוֹרִידִים אוֹתוֹ לְאוֹתוֹ מָדוֹר תַּחְתּוֹן שֶׁאֵין בּוֹ פֶּתַח, וְנֶאֱבָד וְלֹא עוֹלֶה מִמֶּנּוּ לְעוֹלָמִים. וְעַל זֶה כָּתוּב <Nonesmall>[איוב ז]</small> כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לֹא יַעֲלֶה. וָלֹא?! וַהֲרֵי כָּתוּב <Nonesmall>[יונה ב]</small> מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי שָׁמַעְתָּ וְגוֹ'. וְכָתוּב <Nonesmall>[שמואל א ב]</small> מוֹרִיד שְׁאוֹל וַיָּעַל. אֶלָּא כָּאן שְׁאוֹל, שָׁם תַּחְתִּית. וּבֵאַרְנוּ, זֶה כְּשֶׁחָזַר בּוֹ, וְזֶה כְּשֶׁלֹּא חָזַר בּוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַהוּ שֶׁכָּתוּב <Nonesmall>[ירמיה ב]</small> כִּי שְׁתַּיִם רָעוֹת עָשָׂה עַמִּי אֹתִי עָזְבוּ מְקוֹר מַיִם חַיִּים לַחְצֹב לָהֶם בֹּארוֹת וְגוֹ'? אֹתִי עָזְבוּ מְקוֹר מַיִם חַיִּים – זֶהוּ מִי שֶׁלֹּא רוֹצֶה לְקַדֵּשׁ שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאָמֵן. מָה עָנְשׁוֹ? כָּתוּב לַחְצֹב לָהֶם בֹּארוֹת בֹּארֹת נִשְׁבָּרִים. שֶׁיּוֹרְדִים לַגֵּיהִנֹּם דַּרְגָּה אַחַר דַּרְגָּה, עַד שֶׁיּוֹרְדִים לַאֲבַדּוֹן שֶׁנִּקְרָא תַחְתִּית. וְאִם הוּא קִדֵּשׁ שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַוֵּן בְּאָמֵן כָּרָאוּי, עוֹלֶה דַרְגָּה אַחַר דַּרְגָּה לְהִתְעַדֵּן מֵאוֹתוֹ עוֹלָם הַבָּא, שֶׁשּׁוֹפֵעַ תָּמִיד לֹא פוֹסֵק. זֶהוּ שֶׁכָּתוּב <Nonesmall>[תהלים לא]</small> אֱמוּנִים נֹצֵר ה' וּמְשַׁלֵּם עַל יֶתֶר עֹשֵׂה גַאֲוָה.</p>"],[9522012655,"<p>לָמַדְנוּ, שִׁירָה מוֹשֶׁכֶת בְּרָכוֹת מִלְמַעְלָה לְמַטָּה, עַד שֶׁיִּמָּצְאוּ בְרָכוֹת בְּכָל הָעוֹלָמוֹת. <Nonesmall>[אמר רבי יוסי, עתידים הם ישראל לומר שירה שלמה, שירה שכוללת כל שאר השירים, זהו שכתוב <Nonesmall>[ישעיה יב]</small> ואמרתם ביום ההוא הודו לה' קראו בשמו הודיעו בעמים עלילתיו]</small> אָמַר רַבִּי אֶלְעָזָר, עֲתִידִים יִשְׂרָאֵל לוֹמַר שִׁירָה מִלְּמַטָּה לְמַעְלָה וּמִלְמַעְלָה לְמַטָּה וְלִקְשֹׁר אֶת קֶשֶׁר הָאֱמוּנָה, שֶׁכָּתוּב <Nonesmall>[במדבר כא]</small> אָז יָשִׁיר יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת. אָז שָׁר לֹא נֶאֱמַר, אֶלָּא אָז יָשִׁיר. וְכֵן כֻּלָּם כְּמוֹ זֶה. אֶת הַשִּׁירָה הַזֹּאת, מִלְּמַטָּה לְמַעְלָה. עֲלִי בְאֵר עֱנוּ לָהּ. עֲלִי בְאֵר, כְּלוֹמַר עֲלִי לִמְקוֹמֵךְ לְהִתְאַחֵד בְּבַעְלֵךְ, זֶהוּ מִלְּמַטָּה לְמַעְלָה.</p>\n<p>וְאַחַר כָּךְ מִלְמַעְלָה לְמַטָּה, <Nonesmall>[שהרי עד עכשו בגלות נמצאת עמנו]</small> בְּאֵר חֲפָרוּהָ שָׂרִים, שֶׁיָּלְדוּ אוֹתָהּ אַבָּא וְאִמָּא <Nonesmall>[למעלה]</small>. כָּרוּהָ נְדִיבֵי הָעָם – אֵלּוּ הָאָבוֹת שֶׁנִּקְרְאוּ <Nonesmall>[תהלים מז]</small> נְדִיבֵי עַמִּים. כָּרוּהָ, מָקוֹם לְהִזְדַּוֵּג בָּהּ הַמֶּלֶךְ בִּבְרָכוֹת. וּבַמָּה הוּא הַזִּוּוּג? בִּמְחֹקֵק – זֶה יְסוֹד. בְּמִשְׁעֲנֹתָם – זֶה נֵצַח וְהוֹד, מִלְמַעְלָה לְמַטָּה. וּמִמִּדְבָּר מַתָּנָה, וּמִמַּתָּנָה נַחֲלִיאֵל, וּמִנַּחֲלִיאֵל בָּמוֹת. זֶהוּ קֶשֶׁר שָׁלֵם, קֶשֶׁר הָאֱמוּנָה, קִשּׁוּר קַיָּם שֶׁבּוֹ הַכֹּל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, עֲתִידִים יִשְׂרָאֵל לוֹמַר שִׁירָה שְׁלֵמָה, שִׁירָה שֶׁכּוֹלֶלֶת כָּל שְׁאָר הַשִּׁירִים. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה יב]</small> וַאֲמַרְתֶּם בַּיּוֹם הַהוּא הוֹדוּ לַה' קִרְאוּ בִשְׁמוֹ הוֹדִיעוּ בָעַמִּים עֲלִילֹתָיו. בְּאוֹתוֹ זְמַן כָּתוּב, <Nonesmall>[זכריה יד]</small> וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. וְכָתוּב <Nonesmall>[תהלים קכו]</small> אָז יִמָּלֵא שְׂחוֹק פִּינוּ וּלְשׁוֹנֵנוּ רִנָּה, אָז יֹאמְרוּ בַגּוֹיִם הִגְדִּיל ה' לַעֲשׂוֹת עִם אֵלֶּה. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012656,"<p>הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי <Nonesmall>[דברים לב]</small>. רַבִּי יְהוּדָה פָּתַח, <Nonesmall>[שיר השירים ה]</small> פָּתַחְתִּי אֲנִי לְדוֹדִי וְדוֹדִי חָמַק עָבָר וְגוֹ', בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ קְרָאתִיו וְלֹא עָנָנִי. מַה כָּתוּב לְמַעְלָה? אֲנִי יְשֵׁנָה וְלִבִּי עֵר וְגוֹ'. אֲנִי יְשֵׁנָה. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, אֲנִי יְשֵׁנָה – מִמִּצְווֹת הַתּוֹרָה, בִּזְמַן שֶׁהָלַכְתִּי בַמִּדְבָּר. וְלִבִּי עֵר – לַעֲלוֹת לָאָרֶץ, לַעֲשׂוֹת אוֹתָם <Nonesmall>[חובות]</small>, שֶׁהֲרֵי כָּל מִצְווֹת הַתּוֹרָה נִמְצָאוֹת בָּאָרֶץ. קוֹל דּוֹדִי דוֹפֵק – זֶה מֹשֶׁה, שֶׁהוֹכִיחַ לָהֶם לְיִשְׂרָאֵל בְּכַמָּה וִכּוּחִים, בְּכַמָּה מְרִיבוֹת, שֶׁכָּתוּב <Nonesmall>[דברים א]</small> אֵלֶּה הַדְּבָרִים וְגוֹ', <Nonesmall>[שם ט]</small> מַמְרִים הֱיִיתֶם וְגוֹ', <Nonesmall>[שם]</small> וּבְחֹרֵב הִקְצַפְתֶּם וְגוֹ'. זֶהוּ שֶׁכָּתוּב דּוֹפֵק.</p>\n<p>וְעִם כָּל זֶה שֶׁמֹּשֶׁה הוֹכִיחַ לָהֶם לְיִשְׂרָאֵל, בְּאַהֲבָה הָיוּ כָּל דְּבָרָיו, שֶׁכָּתוּב <Nonesmall>[דברים ז]</small> כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ, <Nonesmall>[שם יד]</small> וּבְךְ בָּחַר ה' אֱלֹהֶיךְ לִהְיוֹת לוֹ לְעַם וְגוֹ', בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, <Nonesmall>[שם ד]</small> וְאַתֶּם הַדְּבֵקִים בַּה'. וְעַל זֶה <Nonesmall>[שם כז]</small> וְשָׁמַעְתָּ בְּקוֹל ה' אֱלֹהֶיךְ. <Nonesmall>[שם ז]</small> כִּי מֵאַהֲבַת ה' אֶתְכֶם. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שיר השירים ה]</small> פִּתְחִי לִי אֲחֹתִי רַעְיָתִי.</p>\n<p>מַה כָּתוּב? <Nonesmall>[שם]</small> קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי. אָמְרוּ יִשְׂרָאֵל, בְּעוֹד שֶׁהָיִינוּ מְזֻמָּנִים לַעֲלוֹת לָאָרֶץ וּלְקַבֵּל מִצְווֹת הַתּוֹרָה הָאֵלּוּ עַל יְדֵי מֹשֶׁה, מַה כָּתוּב? <Nonesmall>[שם]</small> וְדוֹדִי חָמַק עָבָר, שֶׁכָּתוּב <Nonesmall>[דברים לד]</small> וַיָּמָת שָׁם מֹשֶׁה עֶבֶד ה'. בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ, שֶׁכָּתוּב וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה. קְרָאתִיו וְלֹא עָנָנִי, שֶׁלֹּא הָיָה דוֹר כְּדוֹרוֹ שֶׁל מֹשֶׁה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמַע לְקוֹלָם וְעָשָׂה לָהֶם נִסִּים וְחֻקִּים, כְּמוֹ שֶׁעָשָׂה עַל יָדָיו.</p>\n<p>רַבִּי יִצְחָק אָמַר, קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי – זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָמָיו שֶׁל מֹשֶׁה, שֶׁכָּל יָמָיו לֹא רָצָה שֶׁמַּלְאָךְ אוֹ שָׁלִיחַ לְהַנְהִיג עִמּוֹ, שֶׁכָּתוּב <Nonesmall>[שמות לג]</small> אִם אֵין פָּנֶיךְ הֹלְכִים וְגוֹ'. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַסְכִּים לִרְצוֹנוֹ. וְדוֹדִי חָמַק עָבָר, בְּיָמָיו שֶׁל יְהוֹשֻׁעַ, שֶׁכָּתוּב <Nonesmall>[יהושע ה]</small> לֹא כִּי אֲנִי שַׂר צְבָא ה'.</p>\n<p>בֹּא רְאֵה, מֹשֶׁה הָיָה שׁוֹמֵעַ קוֹל קָדוֹשׁ שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן וְלֹא נִזְדַּעֲזַע, וְכָל שֶׁכֵּן מַלְאָךְ שֶׁלֹּא רָצָה <Nonesmall>[ולא קבלו]</small>. אַחַר שֶׁמֵּת מֹשֶׁה, מַה כָּתוּב? וַיֹּאמֶר לֹא כִּי אֲנִי שַׂר צְבָא ה'. וְכָתוּב <Nonesmall>[שם]</small> וַיִּפֹּל יְהוֹשֻׁעַ אֶל פָּנָיו אַרְצָה. עַתָּה בָאתִי, בְּיָמָיו שֶׁל מֹשֶׁה רַבְּךְ בָּאתִי וְלֹא קִבְּלַנִי. בְּאוֹתָהּ שָׁעָה יָדְעוּ יִשְׂרָאֵל שִׁבְחוֹ שֶׁל מֹשֶׁה. בְּאוֹתוֹ זְמַן בִּקְּשׁוּ יִשְׂרָאֵל לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא נִזְדַּמֵּן לָהֶם כָּךְ כְּבִימֵי מֹשֶׁה. זֶהוּ שֶׁכָּתוּב בִּקַּשְׁתִּיהוּ וְלֹא מְצָאתִיהוּ וְגוֹ'.</p>"],[9522012657,"<p>הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה <Nonesmall>[דברים לב]</small>. רַבִּי חִיָּיא אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה יוֹתֵר מִכָּל נְבִיאֵי הָעוֹלָם. בֹּא רְאֵה, כָּתוּב <Nonesmall>[ישעיה א]</small> שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אֶרֶץ כִּי ה' דִּבֵּר. שִׁמְעוּ שָׁמַיִם. יְשַׁעְיָה שֶׁהָיָה רָחוֹק יוֹתֵר מֵהַמֶּלֶךְ, כָּתוּב שִׁמְעוּ שָׁמַיִם. מֹשֶׁה שֶׁהָיָה קָרוֹב יוֹתֵר לַמֶּלֶךְ, כָּתוּב הַאֲזִינוּ הַשָּׁמַיִם.</p>\n<p>לָמַדְנוּ, בְּאוֹתוֹ זְמַן שֶׁאָמַר יְשַׁעְיָהוּ שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אֶרֶץ, כַּמָּה בַּעֲלֵי דִינִים מְאִירִים הִזְדַּמְּנוּ לִשְׁבֹּר אֶת רֹאשׁוֹ. יָצָא קוֹל וְאָמַר: מִי הוּא זֶה שֶׁרוֹצֶה לְהַרְעִישׁ עוֹלָמוֹת? עַד שֶׁפָּתַח וְאָמַר: לֹא אֲנִי וְלֹא שֶׁלִּי, אֶלָּא כִּי ה' דִּבֵּר, וְלֹא אֲנִי. בְּמֹשֶׁה מַה כָּתוּב? הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, אֲנִי וְלֹא אַחֵר. וַאֲדַבֵּרָה – בְּלֹא פַחַד. וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי – וְלֹא מֵאַחֵר. אַשְׁרֵי חֶלְקוֹ. אָמַר רַבִּי אַבָּא, בְּאוֹתִיּוֹת חֲקוּקוֹת שֶׁל רַבִּי אֶלְעָזָר, הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ – כָּאן נִרְמָז שֵׁם הַקָּדוֹשׁ הָעֶלְיוֹן.</p>\n<p>רַבִּי יוֹסֵי אָמַר, עוֹד מַה בֵּין מֹשֶׁה לִישַׁעְיָהוּ? מֹשֶׁה אָמַר הַאֲזִינוּ הַשָּׁמַיִם. הַשָּׁמַיִם – הַשָּׁמַיִם הָעֶלְיוֹנִים, אֵלּוּ הַנּוֹדָעִים, שֶׁנִּקְרָאִים שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְתִשְׁמַע הָאָרֶץ – הָאָרֶץ הָעֶלְיוֹנָה, אוֹתָהּ הַנּוֹדַעַת, וְהִיא אֶרֶץ הַחַיִּים. בִּישַׁעְיָה כָתוּב שִׁמְעוּ שָׁמַיִם, וְלֹא הַשָּׁמַיִם. הַאֲזִינִי אֶרֶץ, וְלֹא הָאָרֶץ. וְאֵלּוּ שָׁמַיִם וְאֶרֶץ תַּחְתּוֹנִים. וְעִם כָּל זֶה רָצוּ לְהַעֲנִישׁ אוֹתוֹ, עַד שֶׁאָמַר כִּי ה' דִּבֵּר, וְלֹא אֲנִי. וּמֹשֶׁה אָמַר כָּל זֶה, שֶׁכָּתוּב הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה וְתִשְׁמַע הָאָרֶץ אִמְרֵי פִי.</p>"],[9522012658,"<p>רַבִּי יִצְחָק פָּתַח, <Nonesmall>[שיר השירים ב]</small> כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל אֻמּוֹת עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, שֶׁהֲרֵי כָּל שְׁאָר הָאֻמּוֹת נִתְּנוּ לְשָׂרִים מְמֻנִּים שַׁלִּיטִים עֲלֵיהֶם. וְיִשְׂרָאֵל קְדוֹשִׁים, אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁלֹּא נָתַן אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא לְמַלְאָךְ וְלֹא לְשַׁלִּיט אַחֵר, אֶלָּא הוּא יִחֵד אוֹתָם לְחֶלְקוֹ. זֶהוּ שֶׁכָּתוּב כִּי חֵלֶק ה' עַמּוֹ, וְכָתוּב <Nonesmall>[תהלים קלה]</small> כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר, מַה תַּפּוּחַ מִתְחַלֵּק בִּגְוָנָיו עַל כָּל שְׁאָר עֲצֵי הַשָּׂדֶה, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְחַלֵּק וְנִרְשָׁם עַל כָּל חֲיָלוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים, מִשּׁוּם זֶה <Nonesmall>[ישעיה מח]</small> ה' צְבָאוֹת שְׁמוֹ, אוֹת הוּא בְּכָל צָבָא שֶׁל מַעְלָה.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא כְּתַפּוּחַ, שֶׁיֵּשׁ בּוֹ שְׁלֹשָׁה גְוָנִים. כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שׁוֹשַׁנָּה. אֵיזוֹ שׁוֹשַׁנָּה? אָמַר רַבִּי אַבָּא, שׁוֹשַׁנָּה מֻקֶּפֶת, סְתָם שׁוֹשַׁנָּה שֶׁנִּכְלֶלֶת בְּשִׁשָּׁה עָלִים. שׁוֹשַׁנָּה זוֹ גְּוָנֶיהָ לָבָן וְאָדם, וְהַכֹּל הוּא בִּשְׁנֵי גְוָנִים – אָדם וְלָבָן. כָּךְ כְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>הַקָּדוֹשׁ בָּרוּךָ הוּא כְּמוֹ תַפּוּחַ, כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שׁוֹשַׁנָּה. שֶׁכָּךְ אָמְרָה כְנֶסֶת יִשְׂרָאֵל, <Nonesmall>[שיר השירים ח]</small> תַּחַת הַתַּפּוּחַ עוֹרַרְתִּיךְ. תַּחַת הַתַּפּוּחַ – בְּאֵיזֶה מָקוֹם זֶה? אֶלָּא אֵלּוּ הָאָבוֹת שֶׁאָמַרְנוּ. רַבִּי יוֹסֵי אָמַר, זֶה יוֹבֵל. רַבִּי אַבָּא אָמַר, הַכֹּל יָפֶה, אֶלָּא אֵלּוּ הָאָבוֹת שֶׁאָנוּ אוֹמְרִים, אֵלּוּ הֵם שְׁלֹשָׁה גְוָנִים שֶׁמִּתְחַבְּרִים בַּתַּפּוּחַ.</p>\n<p>רַבִּי יִצְחָק אָמַר, בְּאֵיזֶה מָקוֹם נִכְלֶלֶת כְּנֶסֶת יִשְׂרָאֵל? בַּשּׁוֹשַׁנָּה. בְּאֵלּוּ הַנְּשִׁיקוֹת שֶׁל אַהֲבָה שֶׁנִּדְבֶּקֶת בַּמֶּלֶךְ הָעֶלְיוֹן, לוֹקַחַת שְׁתֵּי שׁוֹשַׁנִּים, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שם ה]</small> שִׂפְתוֹתָיו שׁוֹשַׁנִּים. וּמִשּׁוּם זֶה אָמְרָה כְנֶסֶת יִשְׂרָאֵל, <Nonesmall>[שם א]</small> יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ <Nonesmall>[כמו שנאמר <Nonesmall>[בראשית מא]</small> ועל פיך ישק כל עמי]</small>, מִשּׁוּם שֶׁנִּכְלֶלֶת בַּשּׁוֹשַׁנִּים בִּשְׁתֵּי שְׂפָתַיִם שֶׁלּוֹ.</p>"],[9522012659,"<p>רַבִּי יְהוּדָה אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא שָׁמַיִם, וּמִשּׁוּם שֶׁנִּקְרָא שָׁמַיִם, כָּל אֵלּוּ הָרְקִיעִים שֶׁנִּכְלָלִים בְּשֵׁם זֶה, <Nonesmall>[שבעה הם שכאשר מתחברים וכו']</small> כַּאֲשֶׁר מִתְחַבְּרִים כְּאֶחָד, נִקְרָאִים שָׁמַיִם, וְנִקְרָאִים שֵׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מָה אֵלּוּ הָרְקִיעִים? שִׁבְעָה הֵם.</p>\n<p>כְּמוֹ שֶׁלָּמַדְנוּ, וִילוֹן, רָקִיעַ, שְׁחָקִים, זְבוּל, מָעוֹן, מָכוֹן, עֲרָבוֹת. וּבָאַגָּדוֹת שֶׁל יְשִׁיבַת רַב הַמְנוּנָא סָבָא כָּךְ לָמַדְנוּ. רַבִּי יִצְחָק אָמַר, אֵלּוּ הַבָּרַיְתוֹת שֶׁל יְשִׁיבַת רַב הַמְנוּנָא סָבָא כָּךְ, וְרַבִּים הֵם בְּכָל אֵלּוּ הָאֳפָנִים. כְּמוֹ שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ בְּאֵלּוּ הַבָּרַיְתוֹת <Nonesmall>[החיצוניות]</small>, שֶׁאֵצֶל כָּל אֵלּוּ הַשִּׁבְעִים כְּתָרִים שֶׁל הַמֶּלֶךְ, כְּנֶגְדָּם יֵשׁ שִׁבְעָה רְקִיעִים וְשִׁבְעָה כּוֹכָבִים שֶׁרָצִים וְהוֹלְכִים, וְקוֹרְאִים לָהֶם שֵׁמוֹת כִּשְׁמוֹתָם, וְאַף עַל גַּב שֶׁשָּׁוִים כֻּלָּם. כִּסְאוֹת הָרְקִיעִים שֶׁל שִׁבְעָה כּוֹכָבִים – שַׁבְּתַאי, צֶדֶק, מַאְדִּים, חַמָּה נֹגַהּ, כּוֹכָב, לְבָנָה. וְשָׁוִים אֵלּוּ כְּנֶגֶד אֵלּוּ בְּכִסּוּי הַדְּבָרִים. אֵצֶל אֵלּוּ כָּתוּב, <Nonesmall>[ישעיה מז]</small> יַעַמְדוּ נָא וְיוֹשִׁיעֻךְ הֹבְרֵי שָׁמַיִם הַחֹזִים בַּכּוֹכָבִים. כָּל הַדְּבָרִים נֶעְלָמִים, וְאַף עַל גַּב שֶׁאֵינָם דַּרְכֵי הַתּוֹרָה. וְאָנוּ אַחַר דַּרְכֵי הַתּוֹרָה אָנוּ הוֹלְכִים, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[בראשית כו]</small> וַיִּקְרָא לָהֶן שֵׁמוֹת כַּשֵּׁמֹת אֲשֶׁר קָרָא לָהֶן אָבִיו. כְּמוֹ שֶׁדִּבֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא אָנוּ הוֹלְכִים, וְעִמּוֹ הוֹלְכִים, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[דברים כח]</small> וְהָלַכְתָּ בִּדְרָכָיו.</p>\n<p>אָמַר רַבִּי יוֹסֵי, פְּשׁוּטִים דְּבָרִים אֵלּוּ אֵצֶל הַחֲבֵרִים, וְנוֹדָעִים דְּבָרִים בָּהֶם, וְאַף עַל גַּב שֶׁמְּכֻסִּים. אָמַר לוֹ, וְכָךְ שָׁנִינוּ, כְּמוֹ שֶׁאָמַר רַבִּי יְהוּדָה, אָמַר רַבִּי חִיָּיא לְפָנֵינוּ. וְכָךְ לָמַדְנוּ מֵאֵלּוּ הַבָּרַיְתוֹת, שֶׁשָּׁנִינוּ, בְּיָמָיו שֶׁל שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, וּבִמְקוֹמוֹת רַבִּים נוֹדָעִים דְּבָרִים שֶׁהֵם בָּרַיְתוֹת.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הֵרַמְתִּי יָדִי בִתְפִלָּה לַקָּדוֹשׁ הָעֶלְיוֹן, שֶׁדְּבָרִים אֵלּוּ הִתְגַּלּוּ עַל יָדִי בָּעוֹלָם הַהוּא כְּמוֹ שֶׁהָיוּ מְכֻסִּים בְּלִבִּי. וְאֵין אָנוּ בְּאוֹתָם דְּרָכִים שֶׁל אֵלּוּ הַבָּרַיְתוֹת, דַּרְכֵי הַתּוֹרָה אָנוּ אוֹחֲזִים.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, מִי לְךְ גָּדוֹל בְּחָכְמָה כְּדָוִד הַמֶּלֶךְ וּשְׁלֹמֹה הַמֶּלֶךְ בְּנוֹ בַּכֶּתֶר הַזֶּה שֶׁנּוֹדַע בְּבָרַיְתוֹת אֵלּוּ. וְהַלְּבָנָה, קָרָא אוֹתָהּ דָּוִד הַמֶּלֶךְ צֶדֶק, שֶׁהֲרֵי שֶׁלּוֹ הוּא, שֶׁכָּתוּב <Nonesmall>[תהלים קיח]</small> פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. שְׁלֹמֹה הַמֶּלֶךְ כָּךְ גַּם, וְהוּא נִקְרָא צֶדֶק, וְהַשֶּׁמֶשׁ שֶׁנִּקְרָא בַבָּרַיְתוֹת בְּרִית, הוּא נִקְרָא מִשְׁפָּט, וְאֵלּוּ כִּסְאוֹת הַכָּבוֹד שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב <Nonesmall>[תהלים פט]</small> צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ. צַדִּיק וְצֶדֶק כָּךְ גַּם בְּמַדְרֵגָה אַחַת הָיוּ. לָמַדְנוּ, שִׁבְעָה כְתָרִים בֵּאֲרוּהָ, תִּשְׁעָה נִקְרָאִים. וַאֲפִלּוּ בְּאֵלּוּ הַבָּרַיְתוֹת, שִׁבְעָה רְקִיעִים אֵלּוּ – תִּשְׁעָה הָיוּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, עַד מָתַי יִקְרְאוּ הַחֲבֵרִים בְּאֵלּוּ הַדְּבָרִים. הֲרֵי אָנוּ אַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלְכִים, וְאָנוּ יוֹדְעִים דְּבָרִים, וְהִנֵּה מִתְגַּלֶּה עַל יָדֵינוּ דָּבָר זֶה מַה שֶּׁלֹּא נִגְלָה לַקַּדְמוֹנִים. מִכָּאן וּלְהָלְאָה, כָּל אֵלּוּ הַדְּבָרִים וְכָל אֵלּוּ הַבָּרַיְתוֹת סִלְּקוּ אוֹתָם לְאוֹתָם שֶׁלֹּא נִכְנְסוּ וְיָצְאוּ, וּבְנֵיהֶם בָּאִים לִשְׁאֹל. וְכַאֲשֶׁר יִשְׁאֲלוּ, יֹאמְרוּ הַחֲבֵרִים: אוֹי לַדּוֹר שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי יִסְתַּלֵּק מִמֶּנּוּ. אֲבָל בּא רְאֵה, מִכָּאן וּלְהַבָּא לֹא יִהְיֶה דוֹר כְּדוֹר זֶה, וְלֹא תִתְגַּלֶּה תוֹרָה עַל הַחֲבֵרִים.</p>"],[9522012660,"<p>בֹּא רְאֵה, דּוֹר אַחֲרוֹן שֶׁיָּצְאוּ מִמִּצְרַיִם יָדְעוּ הַכֹּל, שֶׁהֲרֵי מֹשֶׁה גִּלָּה לָהֶם כָּל אוֹתָן אַרְבָּעִים שָׁנָה שֶׁהָיוּ בַמִּדְבָּר, כְּמוֹ שֶׁאָמַרְנוּ. לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, וְאַף מֹשֶׁה לֹא גִלָּה זֶה אֶלָּא בְאוֹתוֹ יוֹם שֶׁהָיָה מִסְתַּלֵּק מִן הָעוֹלָם, שֶׁכָּתוּב <Nonesmall>[דברים לא]</small> בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם, בְּאוֹתוֹ יוֹם מַמָּשׁ. וְעִם כָּל זֶה לֹא אָמַר, עַד שֶׁנָּתְנוּ לוֹ רְשׁוּת, שֶׁכָּתוּב <Nonesmall>[שם]</small> וְעַתָּה כִתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת. וְכַאֲשֶׁר גִּלָּה, לֹא אָמַר הַאֲזִינוּ יִשְׂרָאֵל, אֶלָּא הַאֲזִינוּ הַשָּׁמַיִם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב אֶת הַשִּׁירָה, וְכִי שִׁירָה נִקְרֵאת? אָמַר רַבִּי יִצְחָק, שִׁירָה וַדַּאי. מַה שִּׁירָה נִמְשְׁכָה בְּרוּחַ הַקֹּדֶשׁ מִמַּעְלָה לְמַטָּה, אַף כָּךְ דְּבָרִים אֵלּוּ נִמְשָׁכִים בְּרוּחַ הַקֹּדֶשׁ מִמַּעְלָה לְמַטָּה, וּמִשּׁוּם זֶה אָמַר מֹשֶׁה שִׁירָה.</p>\n<p>בֹּא רְאֵה, כָּל זֶה אָמַר מֹשֶׁה וְקָרָא לָעֶלְיוֹנִים טֶרֶם יֹאמַר דָּבָר, שֶׁכָּתוּב הַאֲזִינוּ הַשָּׁמַיִם. יַעֲרֹף כַּמָּטָר וְגוֹ'. וְכָל כָּךְ לָמָּה? מִשּׁוּם כִּי שֵׁם ה' אֶקְרָא. עַד שֶׁיֹּאמַר דָּבָר, הִרְעִישׁ כָּל הָעוֹלָמוֹת.</p>\n<p>לָמַדְנוּ, בְּאוֹתָהּ שָׁעָה שֶׁאָמַר מֹשֶׁה הַאֲזִינוּ הַשָּׁמַיִם וַאֲדַבֵּרָה, הִתְרַגְּשׁוּ הָעוֹלָמוֹת. יָצָא קוֹל וְאָמַר: מֹשֶׁה מֹשֶׁה, מַדּוּעַ אַתָּה מַרְעִישׁ אֶת כָּל הָעוֹלָם? אַתָּה בְּנוֹ שֶׁל אָדָם, וּבִגְלָלְךְ נִרְגָּשׁ הָעוֹלָם?! פָּתַח וְאָמַר, כִּי שֵׁם ה' אֶקְרָא. בְּאוֹתָהּ שָׁעָה נִשְׁתַּתְּקוּ וְהִקְשִׁיבוּ לִדְבָרָיו.</p>"],[9522012661,"<p>אָמַר רַבִּי יוֹסֵי, כַּמָּה חֲבִיבִין יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. בָּרִאשׁוֹנָה קָרָא לָהֶם גּוֹי קָדוֹשׁ, שֶׁכָּתוּב <Nonesmall>[דברים יד]</small> כִּי עַם קָדוֹשׁ אַתָּה וְגוֹ', וּלְבַסּוֹף קָרָא לָהֶם קֹדֶשׁ, שֶׁכָּתוּב <Nonesmall>[ירמיה ב]</small> קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. מַה בֵּין זֶה לָזֶה? אָמַר רַבִּי אַבָּא, קֹדֶשׁ – עֶלְיוֹן מִכֻּלָּם. שֶׁכָּךְ לָמַדְנוּ, כַּאֲשֶׁר מִתְחַבְּרִים כָּל הַקְּדוֹשִׁים כְּאֶחָד, נִקְרָאִים קָדוֹשׁ. וְכֻלָּם עוֹלִים וּמִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא קֹדֶשׁ.</p>\n<p>וּמִשּׁוּם זֶה קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ. קֹדֶשׁ יִשְׂרָאֵל נַעֲשֶׂה מֵהֶם. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל מֻכְתָּרִים בְּשָׁלֹשׁ מַדְרֵגוֹת, כַּאֲשֶׁר מִתְחַבְּרִים כְּאֶחָד נִקְרָאִים קֹדֶשׁ יִשְׂרָאֵל לַה', שֶׁהִיא רֵאשִׁית. וַהֲרֵי בֵּאַרְנוּ תְּבוּאָתֹה, בְּהֵ\"א. כָּל אֹכְלָיו יֶאְשָׁמוּ. מַהוּ כָּל אֹכְלָיו יֶאְשָׁמוּ? אָמַר רַבִּי אַבָּא, הֲרֵי נֶאֱמַר, שֶׁכָּתוּב <Nonesmall>[ויקרא כב]</small> וְאִישׁ כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה. וְכָתוּב <Nonesmall>[שם]</small> וְכָל זָר לֹא יֹאכַל קֹדֶשׁ, וְיִשְׂרָאֵל נִקְרְאוּ קֹדֶשׁ, מִשּׁוּם כָּךְ כָּל אֹכְלָיו יֶאְשָׁמוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הַתְחָלָה וְסִיּוּם שֶׁל הַכֹּל נִכְלָל בַּקֹּדֶשׁ. <Nonesmall>[א']</small> וְחָכְמָה עֶלְיוֹנָה נִקְרֵאת קֹדֶשׁ, וְכַאֲשֶׁר מְאִירָה הַחָכְמָה הָעֶלְיוֹנָה הַזּוֹ, מְאִירָה חָכְמַת שְׁלֹמֹה, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[מלכים א ה]</small> וַתֵּרֶב חָכְמַת שְׁלֹמֹה, שֶׁעוֹמֶדֶת הַלְּבָנָה בִשְׁלֵמוּתָהּ, וַהֲרֵי בֵּאַרְנוּ. וְכַאֲשֶׁר מִתְבָּרֶכֶת מֵהַיְסוֹד, כָּךְ קוֹרְאִים לָהּ – קֹדֶשׁ, שֶׁהִיא מְאִירָה בִשְׁלֵמוּת. וְכַאֲשֶׁר לֹא מְאִירָה וְנִכְתֶּרֶת בִּשְׁלֵמוּתָהּ, קוֹרְאִים לָהּ רוּחַ הַקֹּדֶשׁ, וְלֹא נִקְרֵאת קֹדֶשׁ כְּאוֹתוֹ שֶׁל מַעְלָה.</p>\n<p>וְכַאֲשֶׁר מִתְבָּרְכִים מִזֶּה הַיְסוֹד וּמֵינִיקָה לְכָל אֵלּוּ שֶׁל מַטָּה, נִקְרֵאת אֵם, כְּאוֹתָהּ שֶׁלְּמַעְלָה, וְקוֹרְאִים לָהּ קָדָשִׁים. וְאָז קוֹרְאִים לָהּ קֹדֶשׁ הַקְּדָשִׁים, שֶׁבּוֹ כַלָּה, שֶׁכָּתוּב <Nonesmall>[שיר השירים ד]</small> אִתִּי מִלְּבָנוֹן כַּלָּה וְגוֹ'. מַהוּ לְבָנוֹן? זֶה עֵדֶן, שֶׁהִלְבִּין מִכָּל הַצְּדָדִים. וְעֵדֶן הֲרֵי יָדוּעַ אֵצֶל הַחֲבֵרִים.</p>"],[9522012662,"<p>לָמַדְנוּ, כָּתוּב כִּי שֵׁם ה' אֶקְרָא. מַהוּ כִּי שֵׁם ה' אֶקְרָא? אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי כָּתוּב הָבוּ גֹדֶל לֵאלֹהֵינוּ. אָמַר רַבִּי אַבָּא, הָבוּ גֹדֶל – זוֹ גְדֻלָּה. הַצּוּר תָּמִים פָּעֳלוֹ – זוֹ גְבוּרָה. כִּי כָל דְּרָכָיו מִשְׁפָּט – זוֹ תִפְאֶרֶת. אֵל אֱמוּנָה – זֶה נֵצַח. וְאֵין עָוֶל – זֶה הוֹד. צַדִּיק – זֶה יְסוֹד. וְיָשָׁר – זֶה צֶדֶק. הֲרֵי הַכֹּל שֵׁם קָדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם זֶה כִּי שֵׁם ה' אֶקְרָא.</p>\n<p>אָמַר רַבִּי יוֹסֵי, שֵׁם ה' מַמָּשׁ. וּמֹשֶׁה בְּאוֹתָהּ שָׁעָה גִּלָּה לָהֶם לְיִשְׂרָאֵל, שֶׁכָּתוּב <Nonesmall>[דברים לא]</small> בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם וְגוֹ'. מִכָּאן לָמַדְנוּ, אוֹתוֹ צַדִּיק שֶׁחָכְמָה עֶלְיוֹנָה בוֹ, כַּאֲשֶׁר מַגִּיעַ יוֹמוֹ לְהִסְתַּלֵּק מֵהָעוֹלָם, צָרִיךְ לְגַלּוֹת אוֹתָהּ הַחָכְמָה לְאֵלּוּ שֶׁרוּחַ קְדוֹשָׁה בֵינֵיהֶם. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם, וְכָתוּב <Nonesmall>[שם]</small> וְעַתָּה כִּתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת וְגוֹ'.</p>\n<p>וְאִם לֹא, עָלָיו כָּתוּב, <Nonesmall>[משלי ג]</small> אַל תִּמְנַע טוֹב מִבְּעָלָיו. כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[משלי ד]</small> כִּי לֶקַח טוֹב נָתַתִּי לָכֶם וְגוֹ'. <Nonesmall>[משלי ג]</small> בִּהְיוֹת לְאֵל יָדְךְ לַעֲשׂוֹת. טֶרֶם תִּסְתַּלֵּק מִן הָעוֹלָם, וְלֹא נִתְּנָה לְךְ רְשׁוּת לְגַלּוֹת.</p>"],[9522012663,"<p>אָמַר רַבִּי חִיָּיא, פָּסוּק זֶה לָמַדְנוּ מִמֶּנּוּ חָכְמָה עֶלְיוֹנָה, וְכָךְ הוּא. אֲבָל סוֹף הַפָּסוּק מְקַשֵּׁר קֶשֶׁר שֶׁל הָאֱמוּנָה בְּמַה שֶּׁכָּתוּב הוּא, כְּמוֹ שֶׁנֶּאֱמַר צַדִּיק וְיָשָׁר הוּא. כְּלוֹמַר, הוּא הַכֹּל, הוּא אֶחָד בְּלֹא פֵרוּד. שֶׁאִם תֹּאמַר שֶׁכָּל אֵלּוּ רַבִּים הֵם – חָזַר וְאָמַר הוּא, כֻּלָּם עוֹלִים וּמִתְקַשְּׁרִים וּמִתְאַחֲדִים בְּאֶחָד. וְהַכֹּל – הוּא הָיָה, וְהוּא הֹוֶה, וְהוּא יִהְיֶה, וְהוּא אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. <Nonesmall>[על]</small> עַד כָּאן מִתְקַשְּׁרִים דְּבָרִים וּמִתְאַחֲדִים דְּבָרִים קְדוֹשִׁים שֶׁל שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁקּוֹרֵא לַמֶּלֶךְ וְיוֹדֵעַ לִקְרֹא כְּמוֹ שֶׁצָּרִיךְ. וְאִם הוּא קוֹרֵא וְלֹא יוֹדֵעַ לְמִי קוֹרֵא, מִתְרַחֵק הַקָּדוֹשׁ בָּרוּךְ הוּא מִמֶּנּוּ, שֶׁכָּתוּב <Nonesmall>[תהלים קמה]</small> קָרוֹב ה' לְכָל קֹרְאָיו וְגוֹ'. קָרוֹב ה' לְכָל קֹרְאָיו, לְמִי קָרוֹב? חָזַר וְאָמַר, לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. וְכִי יֵשׁ מִי שֶׁיִּקְרָא לוֹ בְשֶׁקֶר? אָמַר רַבִּי אַבָּא, כֵּן, אוֹתוֹ מִי שֶׁקּוֹרֵא וְלֹא יוֹדֵעַ לְמִי קוֹרֵא. מִנַּיִן לָנוּ? שֶׁכָּתוּב לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. מַהוּ בֶאֱמֶת? בַּחֲתִימָה שֶׁל חוֹתֶמֶת הַמֶּלֶךְ, שֶׁהוּא שְׁלֵמוּת הַכֹּל. זֶהוּ שֶׁכָּתוּב <Nonesmall>[מיכה ז]</small> תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם. וּמִשּׁוּם כָּךְ, לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת כָּתוּב. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּכְנַס וְיָצָא לָדַעַת דְּרָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה כָתוּב, <Nonesmall>[משלי ד]</small> וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹ'. וְכָתוּב <Nonesmall>[ישעיה ס]</small> וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'.</p>"],[9522012664,"<p>לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, כָּל אֵלּוּ הַתִּקּוּנִים וְכָל אֵלּוּ הַדְּבָרִים נִמְסְרוּ לְקוֹצְרֵי הַשָּׂדֶה. וְלָמַדְנוּ, רְשָׁעִים כִּבְיָכוֹל עוֹשִׂים פְּגָם לְמַעְלָה. אֵיזֶה פְגָם? כְּמוֹ שֶׁכָּתוּב, שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם, שֶׁהֲרֵי כָּל אֵלּוּ הַתִּקּוּנִים לֹא נִמְצָאִים כְּמוֹ שֶׁצָּרִיךְ. כָּתוּב אֶחָד אוֹמֵר, <Nonesmall>[ישעיה נט]</small> וַיִּלְבַּשׁ צְדָקָה כַּשִּׁרְיָן, וְכָתוּב אֶחָד אוֹמֵר, <Nonesmall>[שם]</small> וַיִּלְבַּשׁ בִּגְדֵי נָקָם תִּלְבֹּשֶׁת. אֶלָּא אָמַר רַבִּי יִצְחָק, וַיִּלְבַּשׁ צְדָקָה – בִּזְמַן שֶׁיִּשְׂרָאֵל זַכָּאִים. לֹא זָכוּ – וַיִּלְבַּשׁ בִּגְדֵי נָקָם וְגוֹ'.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מָה הַפְּגָם? כְּמוֹ שֶׁלָּמַדְנוּ, שֶׁהָאָבוֹת לֹא מִסְתַּפְּקִים <Nonesmall>[מסתפקים]</small> לְהִתְבָּרֵךְ מֵאוֹתָהּ הַהַשְׁקָיָה שֶׁל הַנַּחַל, כָּל שֶׁכֵּן הַבָּנִים, כְּמוֹ שֶׁנֶּאֱמַר שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מַהוּ לוֹ לֹא – שְׁתֵּי פְעָמִים. אֶלָּא אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה.</p>\n<p>וְזְהִוּ שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּל זְמַן שֶׁהָרְשָׁעִים מִתְרַבִּים בָּעוֹלָם, כִּבְיָכוֹל שֵׁם הַקָּדוֹשׁ לֹא מִתְבָּרֵךְ בָּעוֹלָם. וְכָל זְמַן שֶׁהָרְשָׁעִים לֹא מִתְרַבִּים בָּעוֹלָם, שֵׁם הַקָּדוֹשׁ מִתְבָּרֵךְ בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב <Nonesmall>[תהלים קד]</small> יִתַּמּוּ חַטָּאִים וְגוֹ', בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. אָמַר רַבִּי אַבָּא, מִקְרָא זֶה מַמָּשׁ הוּא, שֶׁכָּתוּב שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מִי גוֹרֵם לְמוּם זֶה? דּוֹר עִקֵּשׁ וּפְתַלְתֹּל. מִשּׁוּם שֶׁאֵלּוּ הָרְשָׁעִים וְהַדּוֹר נִמְצָא כָּךְ.</p>\n<p>מִשּׁוּם זֶה, אַחַר שֶׁאָמַר מֹשֶׁה כָּל אֵלּוּ הַדְּבָרִים וְהִזְכִּיר הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁצָּרִיךְ, אָמַר, וַדַּאי צַדִּיק וְיָשָׁר הוּא, דָּבָר כְּתִקּוּנוֹ. אֲבָל שִׁחֵת לוֹ לֹא בָּנָיו מוּמָם. מָה הַטַּעַם כָּךְ? מִשּׁוּם שֶׁהֵם דּוֹר עִקֵּשׁ וּפְתַלְתֹּל. אָמַר רַבִּי יְהוּדָה, לוֹ לֹא, כְּלוֹמַר לְעַצְמָם עוֹשִׂים כָּךְ הָרְשָׁעִים, שֶׁגּוֹרְמִים לַבְּרָכוֹת לְהִסְתַּלֵּק מֵהָעוֹלָם. אָמַר רַבִּי אַבָּא, לוֹ לֹא, הֲרֵי בֵּאַרְנוּ וְכָךְ הוּא. מַה כָּתוּב אַחֲרָיו? הַלְה' תִגְמְלוּ זֹּאת, לְשַׁלֵּם גְּמוּל זֶה לְהַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל אֵלּוּ הַטּוֹבוֹת שֶׁגָּרַם לְךְ וְעָשָׂה עֲבוּרְךְ.</p>"],[9522012665,"<p>רַבִּי אֶלְעָזָר פָּתַח, <Nonesmall>[ויקרא כו]</small> וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'. זַכָּאִים הֵם יִשְׂרָאֵל עַל כָּל אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁאַף עַל גַּב שֶׁהִרְגִּיזוּ לִפְנֵי אֲדוֹנָם, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה לַעֲזֹּב אוֹתָם. שֶׁבְּכָל מָקוֹם שֶׁגָּלוּ בֵּין הָעַמִּים, הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'.</p>\n<p>רַבִּי אַבָּא אָמַר, וְאַף גַּם זֹּאת בִּהְיוֹתָם. בֹּא רְאֵה כַּמָּה הַחֲבִיבוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלַפֵּי יִשְׂרָאֵל, שֶׁאַף עַל גַּב שֶׁגּוֹרְמִים לִגְלוֹת בֵּין הָעַמִּים, הַשְּׁכִינָה לֹא סָרָה מֵהֶם לְעוֹלָמִים. שֶׁלֹּא תֹאמַר שֶׁהֵם לְבַדָּם בַּגָּלוּת נִמְצָאִים, אֶלָּא – וְאַף גַּם זֹּאת, עִמָּהֶם נִמְצָאִים. זֶהוּ שֶׁכָּתוּב וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם וְגוֹ'.</p>\n<p>לְמֶלֶךָ שֶׁהִתְרַגֵּז עַל בְּנוֹ, גָּזַר עָלָיו עֹנֶשׁ לְהִתְרַחֵק מִמֶּנּוּ וְלָלֶכֶת לְאֶרֶץ רְחוֹקָה. שָׁמְעָה הַמַּלְכָּה וְאָמְרָה: הוֹאִיל וּבְנִי הוֹלֵךְ לְאֶרֶץ רְחוֹקָה וּמַשְׁלִיךְ אוֹתוֹ הַמֶּלֶךְ מֵהֵיכָלוֹ, אֲנִי לֹא אֶעֱזֹּב אוֹתוֹ. אוֹ שְׁנֵינוּ כְאֶחָד נָשׁוּב לַהֵיכָל שֶׁל הַמֶּלֶךְ, אוֹ שְׁנֵינוּ כְאֶחָד נֵשֵׁב בְּאֶרֶץ אַחֶרֶת. לְעִתִּים פּוֹקֵד הַמֶּלֶךְ עַל הַמַּלְכָּה, וְלֹא מוֹצְאָהּ, שֶׁהָיְתָה הוֹלֶכֶת עִם בְּנוֹ. אָמַר: הוֹאִיל וְהַמַּלְכָּה שָׁם, שְׁנֵיהֶם יָשׁוּבוּ.</p>\n<p>וּבִזְמַן שֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לַמַּלְכָּה, פּוֹקֵד אוֹתָהּ בַּתְּחִלָּה, וּבִגְלָלָהּ פּוֹקֵד אֶת בָּנָיו. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמות ו]</small> וְגַם אֲנִי שָׁמַעְתִּי אֶת נַאֲקַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. מִי גוֹרֵם שֶׁאֲנִי שׁוֹמֵעַ צָרָתָם? כִּבְיָכוֹל הַמַּלְכָּה. שֶׁאֲנִי זוֹכֵר אוֹתָהּ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שם]</small> וָאֶזְכֹּר אֶת בְּרִיתִי. וְכָתוּב <Nonesmall>[שם ב]</small> וַיִּזְכֹּר הָאֱלֹהִים אֶת בְּרִיתוֹ. וְכַאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא יַחֲזִיר אֶת יִשְׂרָאֵל מִן הַגָּלוּת, מַה כָּתוּב? <Nonesmall>[דברים ל]</small> וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחֲמֶךְ. זוֹ הַמַּלְכָּה. וְעוֹד כָּתוּב, <Nonesmall>[תהלים פה]</small> רָצִיתָ ה' אַרְצֶךְ שַׁבְתָּ שְׁבוּת יַעֲקֹב.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הַלְה' תִּגְמְלוּ זֹּאת, מִשּׁוּם שֶׁאַתֶּם דּוֹר עִקֵּשׁ וּפְתַלְתֹּל, אַתֶּם הֱיִיתֶם גּוֹרְמִים שֶׁתִּגְלֶה זֹּאת בַּגָּלוּת. הַלְה' תִּגְמְלוּ זֹּאת?! זֶהוּ הַגְּמוּל שֶׁעָשָׂה עִמָּכֶם בְּכָל אוֹתָם מוֹפְתִים שֶׁל מִצְרַיִם, בְּכָל אוֹתָם אוֹתוֹת שֶׁעָשָׂה לָכֶם, הֲזֶהוּ הַגְּמוּל שֶׁאַתֶּם מְשַׁלְּמִים לָזֹּאת הַזּוֹ?! מִי גָרַם לָכֶם זֶה? מִשּׁוּם שֶׁאַתֶּם עַם נָבָל וְלֹא חָכָם, וְלֹא מִסְתַּכְּלִים בְּכָל אוֹתָן טוֹבוֹת שֶׁעָשָׂה לָכֶם עַד עַתָּה.</p>"],[9522012666,"<p>הַלְה' תִּגְמְלוּ זֹּאת – זוֹ הַשְּׁכִינָה. וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים, שֶׁלָּמַדְנוּ, אוֹת הֵ\"א שֶׁל בְּהִבָּרְאָם <Nonesmall>[בראשית ב]</small> – קְטַנָּה. הֵ\"א שֶׁבְּהַלְה' – גְּדוֹלָה. וַהֲרֵי נִתְבָּאֵר שֶׁלָּמַדְנוּ, אָמַר רַבִּי יְהוּדָה, הֵ\"א שֶׁבְּכָל מָקוֹם – הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרֵאת אֵם. וּשְׁנֵי עוֹלָמוֹת הֵם, שֶׁכָּתוּב <Nonesmall>[תהלים קו]</small> מִן הָעוֹלָם וְעַד הָעוֹלָם. וַהֲרֵי לָמַדְנוּ בְסוֹד הַפָּסוּק, <Nonesmall>[במדבר כח]</small> בְּשֶׁמֶן כָּתִית רְבִיעִת הַהִין.</p>\n<p>לָמַדְנוּ, רַבִּי יְהוּדָה אוֹמֵר, בְּכַמָּה מְקוֹמוֹת הִסְתַּכַּלְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הֵסִיר אַהֲבָתוֹ מֵהֶם מִיִּשְׂרָאֵל, שֶׁבְּכָל מָקוֹם שֶׁהֵם הָיוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּינֵיהֶם, שֶׁכָּתוּב <Nonesmall>[ויקרא כו]</small> לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים לְכַלֹּתָם לְהָפֵר בְּרִיתִי אִתָּם. אִתָּם דַּוְקָא, בֵּינֵיהֶם עִמָּהֶם, לֹא סָר מֵהֶם לְעוֹלָמִים.</p>\n<p>רַבִּי יִצְחָק הָיָה מְהַלֵּךְ בַּדֶּרֶךְ וּפָגַע בּוֹ רַבִּי חִיָּיא. אָמַר לוֹ, רוֹאֶה אֲנִי <Nonesmall>[אותם]</small> בְּפָנֶיךְ שֶׁהֲרֵי בַּמָּדוֹר שֶׁל הַשְּׁכִינָה מְקוֹמְךְ. מַהוּ שֶׁכָּתוּב <Nonesmall>[שמות ג]</small> וָאֵרֵד לְהַצִּילוֹ מִיַּד מִצְרַיִם? וָאֵרֵד?! אֵרֵד הָיָה צָרִיךְ לוֹ! וָאֵרֵד – בָּרִאשׁוֹנָה. מָתַי? כַּאֲשֶׁר יָרַד יַעֲקֹב לְמִצְרַיִם. וְלָמָּה? לְהַצִּילוֹ מִיַּד מִצְרַיִם. שֶׁאִם לֹא הָיָה בֵינֵיהֶם, לֹא יְכוֹלִים לִסְבֹּל הַגָּלוּת, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[תהלים צא]</small> עִמּוֹ אָנֹכִי בְצָרָה אֲחַלְּצֵהוּ וַאֲכַבְּדֵהוּ.</p>\n<p>אָמַר לוֹ, וַדַּאי בְּכָל מָקוֹם שֶׁיִּשְׂרָאֵל נִמְצָאִים, הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּינֵיהֶם. וְכָל מָקוֹם שֶׁחַכְמֵי הַדּוֹר הוֹלְכִים, הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ עִמָּהֶם, שֶׁכָּתוּב <Nonesmall>[שם]</small> כִּי מַלְאָכָיו יְצַוֶּה לָּךְ וְגוֹ'. מִנַּיִן לָנוּ? שֶׁכָּתוּב <Nonesmall>[בראשית לב]</small> וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וְגוֹ', וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה. עַתָּה נִשְׁתַּתֵּף כְּאֶחָד וְנֵלֵךְ בַּדֶּרֶךְ, שֶׁהֲרֵי יָדַעְתִּי שֶׁלְּמָקוֹם אֶחָד אָנוּ הוֹלְכִים, לְקַבֵּל פְּנֵי שְׁכִינָה. אָמַר לוֹ, בְּוַדַּאי. אָמַר רַבִּי יִצְחָק, לָמַדְנוּ, שְׁלוּחֵי מִצְוָה אֵינָן נִזּוֹקִין, לֹא בַהֲלִיכָתָן וְלֹא בַחֲזָרָתָן. וַאֲנַחְנוּ לְהֵרָאוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אָנוּ הוֹלְכִים, וְלֹא יְרֵאִים.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי חִיָּיא, כָּתוּב <Nonesmall>[שם ב]</small> אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. הַשָּׁמַיִם – לִכְלֹל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהָאָרֶץ – לִכְלֹל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל מַה שֶּׁלְּמַטָּה, אֵלּוּ נִקְרָאִים תּוֹלְדוֹת הַשָּׁמַיִם, מֵהֶם.</p>\n<p>אָמַר לוֹ, אִם כֵּן, מַהוּ בְּהִבָּרְאָם, וְנֶאֱמַר בְּה' בְּרָאָם? אָמַר לוֹ, הַכֹּל דָּבָר אֶחָד. כַּאֲשֶׁר הַשָּׁמַיִם הִתְחַבְּרוּ, ה' הַזּוֹ הוֹצִיאָה תוֹלָדוֹת, וְהֵם נִקְרְאוּ תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. אָמַר לוֹ, אִם כֵּן, בַּמֶּה בֵּאַרְנוּ בְּה' בְּרָאָם – בְּאַבְרָהָם? אָמַר לוֹ, הַכֹּל דָּבָר אֶחָד הוּא. בְּאַבְרָהָם – אֵלּוּ הַשָּׁמַיִם, שֶׁמִּשָּׁם מַתְחִילִים לְהִתְפַּשֵּׁט. בְּה' בְּרָאָם, וְזֶהוּ וְהָאָרֶץ, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>אָמַר לוֹ, וַדַּאי כָּךְ הוּא, וַהֲרֵי לָמַדְנוּ, שֶׁכָּתוּב אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ. וְלָמַדְנוּ, הָעוֹלָם הַזֶּה נִבְרָא בְה', שֶׁכָּתוּב בְּהִבָּרְאָם. וְהָעוֹלָם הַבָּא נִבְרָא בְי', שֶׁכָּתוּב <Nonesmall>[בראשית ב]</small> וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן – לִכְלֹל הַשָּׁמַיִם. אֶת הַגָּן – לִכְלֹל אֶת הָאָרֶץ.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁכָּתוּב <Nonesmall>[שיר השירים ד]</small> מַעְיַן גַּנִּים, זֶהוּ הַשָּׁמַיִם, בְּאֵר מַיִם חַיִּים, שֶׁכָּתוּב <Nonesmall>[בראשית כו]</small> וַיִּכְרוּ שָׁם עַבְדֵי יִצְחָק בְּאֵר, שֶׁכָּתוּב <Nonesmall>[שם]</small> וַיַּעְתֵּק מִשָּׁם וַיַּחְפֹּר בְּאֵר אַחֶרֶת וְגוֹ'. וְנֹזְלִים מִן לְבָנוֹן, שֶׁאֵלּוּ מִתְקַשְּׁטִים לְמַעְלָה וְעוֹלִים בְּרֹאשׁוֹ שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב <Nonesmall>[תהלים קח]</small> כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךְ.</p>\n<p>מִן לְבָנוֹן – מִשָּׁם יוֹצְאִים לְבִינָה. וְנִמְשָׁךְ וּמִתְפַּשֵּׁט לְכָל הַקְּצָווֹת, עַד שֶׁנִּמְשָׁכִים אֵלּוּ הַמְּקוֹרוֹת וְיוֹרְדִים לְהִתְכַּנֵּס לְמָקוֹם שֶׁנִּקְרָא הַיָּם הַגָּדוֹל, שֶׁכָּתוּב <Nonesmall>[קהלת א]</small> כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'. וְכָתוּב <Nonesmall>[ישעיה נא]</small> הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם וְגוֹ'. וְאַחַר כָּךְ כָּתוּב, <Nonesmall>[שיר השירים ד]</small> גַּן נָעוּל אֲחֹתִי כַלָּה וְגוֹ'. וּמִכָּאן יָצְאוּ תוֹלָדוֹת לְכֻלָּם, שֶׁכָּתוּב בְּהִבָּרְאָם, בְּה' בְּרָאָם מַמָּשׁ, בְּאַבְרָהָם. אָמַר רַבִּי יִצְחָק, וַאֲפִלּוּ בְּיַעֲקֹב מַמָּשׁ. וְהַכֹּל דָּבָר אֶחָד.</p>"],[9522012667,"<p>אָמַר רַבִּי יִצְחָק, כַּאֲשֶׁר אָנוּ יוֹשְׁבִים לִפְנֵי רַבִּי שִׁמְעוֹן, הַכֹּל נֶאֱמַר לְפָנָיו בְּגִלּוּי וְלֹא הִצְטָרַכְנוּ לְכָל זֶה. אָמַר לוֹ, אֵין רַבִּי שִׁמְעוֹן כִּשְׁאָר בְּנֵי אָדָם, שֶׁכֻּלָּם לְפָנָיו כְּמוֹ שְׁאָר הַנְּבִיאִים כְּלַפֵּי מֹשֶׁה. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי חִיָּיא, כָּתוּב <Nonesmall>[ישעיה מט]</small> הֲתִשְׁכַּח אִשָּׁה עוּלָהּ מֵרַחֵם בֶּן בִּטְנָהּ וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ, וְכָאן מַה הוּא עוֹסֵק? אָמַר רַבִּי יִצְחָק, אִם בַּקֶּשֶׁר שֶׁל הַחֲבֵרִים, סְמִיכָה לֹא נִסְמַכְתִּי, אָנוּ מַה נֹּאמַר?</p>\n<p>אָמַר לוֹ, שֶׁהֲרֵי קוֹל שֶׁל רֶמֶז אֶחָד שָׁמַעְתִּי יוֹם אֶחָד כַּאֲשֶׁר הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ, וְלֹא יָדַעְתִּי מִי אָמַר, וְלֹא יָדַעְתִּי דָבָר. וּבֹא רְאֵה, שִׁבְעָה יָמִים הָיוּ שֶׁנֶּחֱלַשְׁתִּי עַל זֶה וְלֹא טָעַמְתִּי דָבָר, וְעַתָּה הוֹלֵךְ אֲנִי אֵצֶל הַמְּנוֹרָה הַקְּדוֹשָׁה שֶׁיֹּאמַר לִי, שֶׁמָּא אֶזְכֹּר. אָמַר לוֹ, שֶׁמָּא אוֹתוֹ הַיּוֹם שֶׁהָיָה הוֹלֵךְ רַבִּי אֶלְעָזָר אֵצֶל חָמִיו, וְאוֹתוֹ הַיּוֹם הָלַכְתִּי עִמּוֹ, וְהִנֵּה נִזְכַּרְתִּי בַדָּבָר.</p>\n<p>בֹּא רְאֵה, כָּךְ אָמַר רַבִּי אֶלְעָזָר מִשְּׁמוֹ שֶׁל אָבִיו, אָמְרוּ יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: מִיּוֹם שֶׁנָּפַלְנוּ בַגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא עָזַב אוֹתָנוּ בַגָּלוּת וְשָׁכַח אוֹתָנוּ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה מט]</small> וַתֹּאמֶר צִיּוֹן עֲזָבַנִי ה' וַה' שְׁכֵחָנִי. אָמְרָה הַשְּׁכִינָה: הֲתִשְׁכַּח אִשָּׁה עוּלָהּ?! וְכִי יִשְׂרָאֵל שֶׁנִּקְרָאִים בָּנִים, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[דברים יד]</small> בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, מֵרַחֵם בֶּן בִּטְנָהּ, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[ירמיה ב]</small> וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת, גַּם אֵלֶּה תִּשְׁכַּחְנָה, שֶׁכָּתוּב <Nonesmall>[בראשית ב]</small> אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ?! וְאָנֹכִי לֹא אֶשְׁכָּחֵךְ. מִכָּאן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עוֹזֵב אוֹתָם אֶת יִשְׂרָאֵל לְעוֹלָמִים.</p>\n<p>עוֹד אָמַר, הֲתִשְׁכַּח אִשָּׁה עוּלָהּ מֵרַחֵם בֶּן בִּטְנָהּ. זֶהוּ סוֹד עֶלְיוֹן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא. הִנֵּה דְבָרִים אֵלּוּ בִשְׁמוֹ אֲחוּזִים. כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שׁוֹכֵחַ שְׁמוֹ שֶׁהֲרֵי הוּא הַכֹּל – כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שׁוֹכֵחַ אוֹתָם אֶת יִשְׂרָאֵל, שֶׁהֵם אֲחוּזִים בִּשְׁמוֹ מַמָּשׁ. הִתְרַגֵּשׁ רַבִּי חִיָּיא, אָמַר, וַדַּאי זֶהוּ דְּבַר חִדּוּשׁ. בָּרוּךְ יִהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּפְגַּשְׁתִּי בְךְ וְיָדַעְתִּי דָבָר, וְיָדַעְתִּי מִי אוֹתוֹ שֶׁשָּׁמַעְתִּי מִמֶּנּוּ.</p>\n<p>וּבֹא רְאֵה, שֶׁאוֹתוֹ יוֹם שֶׁרַצְתִּי אַרְבָּעָה מִילִין, וְלֹא מָצָאתִי מִי הָיָה. אָמַר לוֹ, מִשּׁוּם שֶׁנִּכְנַסְתִּי בִמְעָרָה אַחַת שֶׁרַבִּי אֶלְעָזָר נָח שָׁעָה אַחַת. קָרָא עָלָיו רַבִּי חִיָּיא אֵלּוּ הַפְּסוּקִים, <Nonesmall>[ישעיה נח]</small> אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וְגוֹ'. אָז תִּקְרָא וַה' יַעֲנֶה וְגוֹ', אָז תִּתְעַנַּג עַל ה' וְגוֹ'.</p>"],[9522012668,"<p><Nonesmall>[דברים לג]</small> זְכֹר יְמוֹת עוֹלָם בִּינוּ שְׁנוֹת דֹּר וָדוֹר וְגוֹ'. זְכֹר יְמוֹת עוֹלָם. רַבִּי אַבָּא אָמַר, מִי אֵלּוּ יְמוֹת עוֹלָם? אֵלּוּ שִׁשָּׁה יָמִים שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם בָּהֶם, שֶׁכָּתוּב <Nonesmall>[שמות לא]</small> כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' וְגוֹ'. שֵׁשֶׁת יָמִים, וְלֹא בְשֵׁשֶׁת יָמִים, וַהֲרֵי בֵּאַרְנוּ. בִּינוּ שְׁנוֹת דֹּר וָדר. כְּלוֹמַר, אֵלּוּ יְמוֹת עוֹלָם, יֵדְעוּ וְיִתְוַדְּעוּ כָּל אֵלּוּ הַשָּׁנִים וְהַיָּמִים וְכָל דּוֹר וָדוֹר, עַד דּוֹר זֶה שֶׁאַתֶּם עוֹמְדִים בּוֹ.</p>\n<p>שְׁאַל אָבִיךְ וְיַגֵּדְךְ – זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב הֲלֹא הוּא אָבִיךְ קָּנֶךְ. וְיַגֵּדְךְ, וְהוּא יְגַלֶּה עֹמֶק הַחָכְמָה. וּמַה הִיא? אֶלָּא כַּאֲשֶׁר שִׁשָּׁה יָמִים אֵלּוּ בָּנוּ אֶת הָעוֹלָם, לֹא בָנוּ אוֹתוֹ אֶלָּא בִּגְלָלְךְ, שֶׁתָּבא אַתָּה וּתְקַיֵּם אֶת הַתּוֹרָה. שֶׁלָּמַדְנוּ, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא – עַל תְּנַאי עָשָׂה, שֶׁכַּאֲשֶׁר יָבאוּ יִשְׂרָאֵל, אִם יְקַבְּלוּ אֶת הַתּוֹרָה – מוּטָב, וְאִם לֹא – שֶׁיַּחֲזִירֵהוּ לְתֹהוּ וָבהוּ. וּמִשּׁוּם זֶה, אֵלּוּ יְמוֹת עוֹלָם יוֹדְעִים וּמְבִינִים הַכֹּל.</p>\n<p>וַהֲרֵי לָמַדְנוּ, אֵלּוּ עַנְפֵי הָאִילָן אֵיךְ נֶאֱחָזִים בְּתוֹךְ הָאִילָן? וַהֲרֵי בֵּאַרְנוּ, שֶׁכַּאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַר לָהֶם לִמְמֻנֵּי הַמָּגִנִּים עַל שְׁאָר הָאֻמּוֹת, וְאַתֶּם מַה כָּתוּב? כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. שֶׁלֹּא נָתַן אוֹתָם לְשַׂר, וְלֹא לְמַלְאָךְ, וְלֹא לִמְמֻנֶּה אַחֵר, וְזֶה הָעָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל לְחֶלְקוֹ.</p>\n<p>בְּאֵיזְהִ מָקוֹם מָצָא אוֹתוֹ? יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן וְגוֹ'. שֶׁכָּתוּב <Nonesmall>[יהושע כד]</small> תֶּרַח אֲבִי אַבְרָהָם וְגוֹ', וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם וְגוֹ'. וּמִכָּאן מַנְהִיג אוֹתָם אֶת יִשְׂרָאֵל בְּכָל דּוֹר וָדוֹר וְלֹא נִפְרָד מֵהֶם וּמַנְהִיג אוֹתָם בְּרַחֲמִים. זֶהוּ שֶׁכָּתוּב <Nonesmall>[דברים לב]</small> כְּנֶשֶׁר יָעִיר קִנּוֹ וְגוֹ'.</p>"],[9522012669,"<p>כְּנֶשֶׁר יָעִיר קִנּוֹ. אָמַר רַבִּי יוֹסֵי, לֹא מָצָאנוּ מִי שֶׁמְּרַחֵם עַל בָּנָיו כַּנֶּשֶׁר הַזֶּה. וְעַל זֶה לָמַדְנוּ, כָּתוּב <Nonesmall>[יחזקאל א]</small> וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. הַנֶּשֶׁר, הֵיכָן מְקוֹמוֹ? בְּמָקוֹם שֶׁיַּעֲקֹב עוֹמֵד. זֶהוּ שֶׁכָּתוּב <Nonesmall>[משלי ל]</small> דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בְּאוֹתוֹ מָקוֹם מַמָּשׁ. מַה טַּעֲמוֹ? מִשּׁוּם שֶׁהוּא מְרַחֵם עַל בָּנָיו, וּבְדִין עִם אֲחֵרִים. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַנְהִיג אֶת בָּנָיו כְּנֶשֶׁר זֶה.</p>\n<p>מַה כָּתוּב? ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר. הוּא בִּלְבַדּוֹ, שֶׁכָּתוּב <Nonesmall>[שמות יג]</small> וַה' הֹלֵךְ לִפְנֵיהֶם וְגוֹ'. וְאֵין עִמּוֹ אֵל נֵכָר, שֶׁלֹּא הִנְהִיג לָהֶם לְיִשְׂרָאֵל לֹא מַלְאָךְ, וְלֹא מְמֻנֶּה אַחֵר, שֶׁהֵם נִקְרָאִים אֵל נֵכָר. וְזֶהוּ שֶׁאָמַר מֹשֶׁה, <Nonesmall>[שמות לג]</small> אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה. זֶהוּ שֶׁכָּתוּב ה' בָּדָד יַנְחֶנּוּ. הוּא בִּלְבַדּוֹ, וְאֵין עִמּוֹ אֵל נֵכָר.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְנַהֵג אִתָּם <Nonesmall>[בישראל]</small> כָּךְ, עֲלֵיהֶם כָּתוּב <Nonesmall>[תהלים קלה]</small> כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ, וְכָתוּב <Nonesmall>[שמואל א יב]</small> כִּי לֹא יִטֹּשׁ ה' עַמּוֹ וְגוֹ'. מָה הַטַּעַם לֹא יִטֹּשׁ ה' אֶת עַמּוֹ? בַּעֲבוּר שְׁמוֹ הַגָּדוֹל, מִשּׁוּם שֶׁזֶּה בָּזֶה נִדְבָּק. וְעַל זֶה לֹא יַעֲזֹּב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁבְּכָל מָקוֹם שֶׁהֵם נִמְצָאִים, הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>"],[9522012670,"<p>לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת <Nonesmall>[דברים לב]</small>. אָמַר רַבִּי יוֹסֵי, כָּל אֵלּוּ הַפְּסוּקִים שֶׁכָּאן תּוֹכָחוֹת הֵם שֶׁהוֹכִיחַ אוֹתָם מֹשֶׁה לְיִשְׂרָאֵל, חוּץ מֵאוֹתוֹ שֵׁם קָדוֹשׁ שֶׁגִּלָּה בִתְחִלַּת דְּבָרָיו. אָמַר רַבִּי אַבָּא, וַאֲפִלּוּ מַה שֶּׁהוֹכִיחַ לְיִשְׂרָאֵל הוּא בִּכְלַל הַשֵּׁם הַקָּדוֹשׁ, שֶׁאֵין דָּבָר בַּתּוֹרָה שֶׁיּוֹצֵא מִכְּלַל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהַתּוֹרָה כֻּלָּהּ שְׁמוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם.</p>\n<p>וְאֵלּוּ הַפְּסוּקִים יְדוּעִים הֵם. אֲבָל מִשּׁוּם שֶׁשְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא רָשׁוּם בְּפָרָשָׁה זוֹ, הָיִיתִי צָרִיךְ עַד עַתָּה. וְכָאן הֲרֵי כָּתוּב, לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת, זֹּאת וַדַּאי. וַהֲרֵי בְּכַמָּה מְקוֹמוֹת בֵּאַרְנוּ זֹּאת, שֶׁאִם יִשְׂרָאֵל יֵדְעוּ אֶת זֶה אֵיךְ זֹּאת אֲחוּזָה בְדִינֶיהָ לְהִפָּרַע מִן הָרְשָׁעִים – יָבִינוּ לְאַחֲרִיתָם, וְיִשְׁתַּמְּרוּ לִהְיוֹת בָּהּ, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[איוב כ]</small> וְאֶרֶץ מִתְקוֹמָמָה לוֹ.</p>\n<p>דָּבָר אַחֵר לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת – שֶׁהִיא קְשׁוּרָה בָהֶם בְּיִשְׂרָאֵל. כַּאֲשֶׁר שׁוֹמְרִים מִצְווֹת הַתּוֹרָה וְיוֹשְׁבִים עִמָּהּ בְּשָׁלוֹם, יֵדְעוּ שֶׁעֶזְרָה שֶׁל זֹּאת הַזּוֹ עִמָּהֶם, לְהִפָּרַע מִשּׂוֹנְאֵיהֶם. וְיִשְׂרָאֵל, שֶׁהֵם מְעַטִּים בֵּין הָאֻמּוֹת, יֵדְעוּ אֵיכָה יִרְדֹּף אֶחָד אֶלֶף וּשְׁנַיִם יָנִיסוּ רְבָבָה. וּמִי גָרַם לָהֶם? הַזֹּאת הַזּוֹ שֶׁהָיְתָה בֵינֵיהֶם בְּשָׁלוֹם כַּאֲשֶׁר עוֹשִׂים מִצְווֹת הַתּוֹרָה, וּלְעוֹלָמִים לֹא זָזָה מֵהֶם לַעֲשׂוֹת לָהֶם נְקָמוֹת.</p>\n<p>אִם לֹא כִּי צוּרָם מְכָרָם וַה' הִסְגִּירָם <Nonesmall>[דברים לב]</small>. מָה הַטַּעַם כִּי צוּרָם מְכָרָם? מִשּׁוּם שֶׁצּוּר יְלָדְךְ תֶּשִׁי, שֶׁהַתִּקּוּנִים לֹא נִמְצָאִים כְּמוֹ שֶׁצָּרִיךְ בִּמְקוֹמָם. אִם לֹא כִּי צוּרָם מְכָרָם. אָמַר רַבִּי יְהוּדָה, זֶה אַבְרָהָם, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁאָמַר אַבְרָהָם, יִתְחַיְּבוּ יִשְׂרָאֵל בְּגָלוּת וְלֹא יִכָּנְסוּ בְגֵיהִנָּם, שֶׁשְּׁנֵי אֵלּוּ – גָּלוּת וְגֵיהִנָּם – לֹא יִסְבְּלוּ יִשְׂרָאֵל. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ, שֶׁכָּל זְמַן שֶׁיִּתְחַיְּבוּ יִשְׂרָאֵל, יִפְּלוּ לְגָלוּת וְיִשְׁתַּעְבְּדוּ בָהֶם שׂוֹנְאֵיהֶם. וּמִשּׁוּם זֶה צוּרָם מְכָרָם, וַדַּאי, וַה' הִסְגִּירָם, וְהִסְכִּים עַל יָדָיו.</p>"],[9522012671,"<p>לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, מָה הַטַּעַם שֶׁהוֹכִיחַ לָהֶם מֹשֶׁה בַּשִּׁירָה הַזּוֹ כָּךְ? מִשּׁוּם שֶׁהֵם מְזֻמָּנִים לְהִכָּנֵס לָאָרֶץ וּלְהַשְׁרוֹת עֲלֵיהֶם שְׁכִינָה, וּמִשּׁוּם זֶה הוֹכִיחַ אוֹתָם עַל כָּךְ.</p>\n<p>רַבִּי יִצְחָק אָמַר, בִּשְׁנֵי מְקוֹמוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מְזֻמָּן לְהוֹכִיחַ אֶת יִשְׂרָאֵל, וְשָׂמְחוּ אֻמּוֹת הָעוֹלָם. אֶחָד – שֶׁכָּתוּב <Nonesmall>[הושע יב]</small> וְרִיב לַה' עִם יְהוּדָה וְלִפְקֹד עַל יַעֲקֹב כִּדְרָכָיו וְגוֹ'. שָׁמְעוּ אֻמּוֹת הָעוֹלָם, שָׂמְחוּ. אָמְרוּ, עַתָּה יִכָּרְתוּ מֵהָעוֹלָם. כַּאֲשֶׁר רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם שְׂמֵחִים, מַה כָּתוּב אַחֲרָיו? בַּבֶּטֶן עָקַב אֶת אָחִיו וְגוֹ'. כַּאֲשֶׁר שׁוֹמְעִים, אוֹמְרִים, זוֹ הִיא תְשׁוּבָה.</p>\n<p>מָשָׁל לְאִשָּׁה שֶׁהָיְתָה לָהּ קְטָטָה בִּבְנָהּ, הָלְכָה לִתְבֹּעַ עָלָיו דִּין. רָאֲתָה לַדַּיָּן שֶׁדָּן דִּינֵי נְפָשׁוֹת – חֶלְקָם לְמַלְקוֹת, לִתְלִיָּה, לִשְׂרֵפָה. אָמְרָה: אוֹי, מָה אֶעֱשֶׂה מִן הַבֵּן? כַּאֲשֶׁר סִיֵּם הַדִּין, אָמַר לְאוֹתָהּ אִשָּׁה: אִמָּא, מֶה עָשָׂה לָךְ בְּנֵךְ? אָמְרָה, מִתְלוֹנֶנֶת, עכ\"מ.</p>"],[9522012672,"<p>יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ. וַדַּאי לְבַסּוֹף עָשָׂה לְכָל אוֹתָן קְלִפּוֹת שֶׁיִּהְיוּ כֻלָּן מִשְׁתַּעְבְּדוֹת לוֹ. עַד כָּאן הָיָה כָתוּב בְּאוֹתוֹ סֵפֶר שֶׁל קַרְטָנָא הָרוֹפֵא. לְבַסּוֹף הָיָה רָשׁוּם בְּזֶה הַפָּסוּק, כָּל שְׁמִירָה שֶׁנִּצְרָךְ רוֹפֵא חָכָם לַעֲשׂוֹת לְחוֹלֶה שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ, בֵּית אֲסִירֵי הַמֶּלֶךְ – לַעֲבֹד לַאֲדוֹן הָעוֹלָם!</p>\n<p>שֶׁכַּאֲשֶׁר הוֹלֵךְ רוֹפֵא חָכָם אֶצְלוֹ, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן, מַחֲלוֹת הַשּׁוֹרוֹת עָלָיו. מוֹצֵא אוֹתוֹ בְּמַאֲסַר הַמֶּלֶךְ. אִם תֹּאמַר, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא <Nonesmall>[פוקד]</small> יִפְקֹד לִתְפֹּס אוֹתוֹ, שֶׁלֹּא יִשְׁתַּדֵּל אָדָם אַחֲרָיו – לֹא כָּךְ, שֶׁהֲרֵי אָמַר דָּוִד, <Nonesmall>[תהלים מא]</small> אַשְׁרֵי מַשְׂכִּיל אֶל דָּל וְגוֹ'. דַּל הוּא אוֹתוֹ שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ. וְאִם רוֹפֵא חָכָם הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ בְּרָכוֹת לְאוֹתוֹ שֶׁיִּשְׁתַּדֵּל בּוֹ.</p>\n<p>וְאוֹתוֹ רוֹפֵא, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, בְּבֵית חָלְיוֹ שׁוֹכֵב. וּבְתֹהוּ יְלֵל יְשִׁמֹן, שֶׁאוֹתָן מַחֲלוֹת מְצֵרוֹת לוֹ. מַה צָּרִיךְ לוֹ לַעֲשׂוֹת? יְסוֹבְבֶנְהוּ – יְסוֹבֵב סִבּוֹת וְיָבִיא עִלּוֹת כְּדֵי שֶׁיִּמְנַע מִמֶּנּוּ אוֹתָם דְּבָרִים שֶׁמַּזִּיקִים לוֹ. יַקִּיז לוֹ, וְיוֹצִיא מִמֶּנּוּ דָם רַע. יְבוֹנְנֵהוּ – יִסְתַּכֵּל וְיָבִין אוֹתוֹ חוֹלֶה מִמַּה הָיָה, וְיִסְתַּכֵּל כְּדֵי שֶׁלֹּא יִכְבַּד עָלָיו וִימַעֵט אוֹתוֹ. לְבַסּוֹף – יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ, כְּדֵי שֶׁיִּהְיֶה שָׁמוּר כְּמוֹ שֶׁצָּרִיךְ בְּאוֹתָם מַשְׁקִים, בְּאוֹתָן רְפוּאוֹת שֶׁצְּרִיכוֹת לוֹ, וְלֹא יִטְעֶה <Nonesmall>[מהם]</small> בֵּינֵיהֶן. שֶׁאִם יִטְעֶה אֲפִלּוּ בְדָבָר אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא חוֹשֵׁב עַל אוֹתוֹ רוֹפֵא כְּאִלּוּ שָׁפַךְ דָּמִים וַהֲרָגוֹ.</p>\n<p>מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה, שֶׁאַף עַל גַּב שֶׁאוֹתוֹ אָדָם הוּא בְּבֵית אֲסִירֵי הַמֶּלֶךְ וְהוּא אָסוּר בְּבֵית הָאֲסוּרִים, שֶׁיִּשְׁתַּדֵּל אָדָם עָלָיו וְיַעֲזֹּר לוֹ לְהוֹצִיאוֹ מִבֵּית הָאֲסוּרִים. וְהָיָה אוֹמֵר כָּךְ: הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינִים שֶׁל בְּנֵי הָעוֹלָם לְמַעְלָה, הֵן לְמָוֶת, הֵן לְשָׁרְשׁוֹ, הֵן לַעֲקֹר, הֵן לַעֲנֹשׁ בִּנְכָסָיו, וְלֶאֱסֹר אוֹתוֹ. מִי שֶׁנִּרְאֶה לַעֲנֹשׁ נְכָסִים, נוֹפֵל בְּבֵית חָלְיוֹ, וְלֹא יִתְרַפֵּא עַד שֶׁיִּתֵּן כָּל מַה שֶּׁנִּגְזַר עָלָיו. כֵּיוָן שֶׁנֶּעֱנָשׁ בְּמָמוֹנוֹ וְנוֹתֵן כָּל מַה שֶּׁנִּגְזַר עָלָיו, יִתְרַפֵּא, וְיוֹצֵא מִבֵּית הָאֲסוּרִים. וְעַל זֶה צָרִיךְ לְהִתְעַסֵּק עִמּוֹ שֶׁיִּתֵּן עָנְשׁוֹ וְיֵצֵא.</p>\n<p>מִי שֶׁרָאוּי לְשָׁרְשׁוֹ, יִתְפְּסוּ אוֹתוֹ, וְיִתְּנוּ אוֹתוֹ בְּבֵית הָאֲסוּרִים עַד שֶׁיִּשְׁתָּרֵשׁ מֵהַכֹּל. וְלִפְעָמִים מִשְׁתָּרֵשׁ בְּאֵיבָרָיו אוֹ מֵאֶחָד מֵהֶם, וּלְבַסּוֹף יוֹצִיאוּ אוֹתוֹ מִבֵּית הָאֲסוּרִים. מִי שֶׁרָאוּי לְמָוֶת – כָּךְ הוּא, שֶׁאִלּוּ יִתֵּן כָּל הַכֹּפֶר וְכָל מָמוֹן שֶׁבָּעוֹלָם, לֹא יִנָּצֵל.</p>\n<p>וְעַל זֶה צָרִיךְ לְרוֹפֵא חָכָם שֶׁיַּעֲסֹק בִּרְפוּאָתוֹ. אִם יָכוֹל לָתֵת לוֹ רְפוּאָה מִן הַגּוּף – מוּטָב, וְאִם לֹא – יִתֵּן לוֹ רְפוּאָה לְנִשְׁמָתוֹ, וְיִשְׁתַּדֵּל בִּרְפוּאַת נִשְׁמָתוֹ. וְזֶהוּ רוֹפֵא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁתַּדֵּל עָלָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, עַד עַתָּה לֹא שָׁמַעְתִּי מֵרוֹפֵא זֶה וּמִסֵּפֶר זֶה, חוּץ מִפַּעַם אַחַת שֶׁאָמַר לִי סוֹחֵר אֶחָד, שֶׁשָּׁמַע לְאָבִיו שֶׁרוֹפֵא אֶחָד הָיָה בְיָמָיו, שֶׁכַּאֲשֶׁר הָיָה מִסְתַּכֵּל בְּבֶן אָדָם כַּאֲשֶׁר הוּא בְּבֵית חָלְיוֹ, הָיָה אוֹמֵר, זֶה חַי וְזֶה מֵת. וְהָיוּ אוֹמְרִים עָלָיו שֶׁהוּא צַדִּיק אֲמִתִּי, יְרֵא חֵטְא, וְכָל מַה שֶּׁלֹּא יָכֹל לְהַשִּׂיג מַה שֶּׁנִּצְרָךְ, הוּא הָיָה קוֹנֶה וְנוֹתֵן מִשֶּׁלּוֹ. וְהָיוּ אוֹמְרִים שֶׁאֵין חָכָם בָּעוֹלָם כָּמוֹהוּ, וּבִתְפִלָּתוֹ הָיָה עוֹשֶׂה יוֹתֵר מִמַּה שֶּׁהָיָה עוֹשֶׂה בְיָדָיו. וְכִמְדֻמֶּה לָנוּ, זֶה הָיָה אוֹתוֹ רוֹפֵא.</p>\n<p>אָמַר אוֹתוֹ סוֹחֵר, וַדַּאי סִפְרוֹ בְיָדִי הוּא, שֶׁיָּרַשְׁתִּי אוֹתוֹ מֵאֲבִי אַבָּא, וְכָל דְּבָרָיו שֶׁל אוֹתוֹ סֵפֶר, כֻּלָּם מְיֻסָּדִים עַל סוֹדוֹת הַתּוֹרָה, וְסוֹדוֹת נֶעְלָמִים מָצָאתִי בוֹ וּדְבָרִים שֶׁל רְפוּאָה רַבִּים, שֶׁהוּא אָמַר שֶׁלֹּא רָאוּי לַעֲשׂוֹת אוֹתָם חוּץ <Nonesmall>[אם]</small> הוּא יְרֵא חֵטְא.</p>\n<p>וְהֵם מִמַּה שֶּׁהָיָה עוֹשֶׂה בִּלְעָם, שֶׁהָיָה לוֹחֵשׁ לְחָשִׁים עַל חוֹלֶה, וְהָיָה אוֹמֵר בְּפִיו וּמִתְרַפֵּא מִיָּד. וְכֻלָּם מְבָרֵר אוֹתָם בְּאוֹתוֹ סֵפֶר. וְאָמַר, זֶה אָסוּר, וְזֶה מֻתָּר לְמִי שֶׁיְּרֵא חֵטְא. מִשּׁוּם שֶׁחֳלָאִים רַבִּים אָמַר שֶׁתְּלוּיָה רְפוּאָתָם בִּלְחִישַׁת הַפֶּה. וְאֵלּוּ מִצַּד הַנָּחָשׁ, וּמֵהֶם מִצַּד שֶׁל קֶסֶם. וְכָל אוֹתָם שֶׁאָסוּר לוֹמַר בַּפֶּה וְאָסוּר לַעֲשׂוֹת בְּמַעֲשֶׂה הָיָה אוֹמֵר. עַד שֶׁמָּצָאתִי עַל חֳלָאִים יְדוּעִים שֶׁצָּרִיךְ לוֹמַר כָּךְ, וּלְנַדּוֹת בְּנִדּוּי וּבְשַׁמְתָּא עַל אוֹתוֹ חֹלִי, וְהוּא תְמִיהָה גְדוֹלָה אֶצְלִי.</p>\n<p>שָׂמַח רַבִּי אֶלְעָזָר, וְשָׂמְחוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, אִם אוֹתוֹ סֵפֶר הָיָה אֶצְלֵנוּ, הָיִינוּ רוֹאִים מַה הוּא אוֹמֵר. אֲנִי אֶמְסֹר בִּמְסִירָה עַל מְנָת לְהַרְאוֹת לַמְּנוֹרָה הַקְּדוֹשָׁה. וְלָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, אוֹתוֹ הַסֵּפֶר הָיָה בְיָדִי שְׁנֵים עָשָׂר חֹדֶשׁ, וּמָצָאתִי בוֹ אוֹרוֹת עֶלְיוֹנוֹת וַחֲשׁוּבִים. כַּאֲשֶׁר הִגַּעְתִּי לְאוֹתָם סוֹדוֹת שֶׁהָיוּ מִבִּלְעָם, תָּמַהְתִּי.</p>\n<p>יוֹם אֶחָד לָחַשְׁתִּי בְּמָקוֹם אֶחָד, וְהָיוּ הָאוֹתִיּוֹת עוֹלוֹת וְיוֹרְדוֹת. עַד שֶׁרָאִיתִי בַחֲלוֹם וְאָמַר לִי, מַה לְּךְ לְהִכָּנֵס בִּתְחוּם שֶׁאֵינוֹ שֶׁלְּךְ וְשֶׁאֵינוֹ נִצְרָךְ לְךְ? הִתְעוֹרַרְתִּי. וְרַע בְּעֵינַי עַל סוֹדוֹת הַסְּתוּמִים שֶׁהָיוּ שָׁם. שָׁלַחְתִּי לְאוֹתוֹ יְהוּדִי, וְרַבִּי יוֹסֵי בְּרַבִּי יְהוּדָה שְׁמוֹ, וְנָתַתִּי לוֹ אֶת הַסֵּפֶר.</p>\n<p>וּבַסּוֹדוֹת שֶׁל בִּלְעָם מָצָאתִי מֵאוֹתָם שֵׁמוֹת שֶׁל מַלְאָכִים שֶׁשָּׁלַח לוֹ בָּלָק, וְלֹא הָיוּ מִסְתַּדְּרִים עַל תִּקּוּנָם כְּמוֹ שֶׁצָּרִיךְ. אֲבָל כַּמָּה מִינֵי רְפוּאָה מָצָאתִי בוֹ שֶׁהֵם מְתֻקָּנִים עַל תִּקּוּנִי הַתּוֹרָה וְסוֹדוֹת סְתוּמִים שֶׁלָּהּ. וְרָאִיתִי שֶׁהֵם בַּחֲסִידוּת, וּתְפִלּוֹת וּבַקָּשׁוֹת לְהַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִם תֹּאמַר שֶׁהָיָה עוֹשֶׂה רְפוּאָה בִּפְסוּקֵי הַתּוֹרָה אוֹ בְסוֹדוֹת הַתּוֹרָה – חַס וְשָׁלוֹם. אֶלָּא הָיָה אוֹמֵר סוֹדוֹת הַתּוֹרָה, וְעַל אוֹתוֹ סוֹד הוֹצִיא סוֹדוֹת שֶׁל רְפוּאָה שֶׁלֹּא רָאִיתִי בְּאֹפֶן זֶה לְעוֹלָם. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁהֶחְכִּים לִבְנֵי אָדָם מֵחָכְמָה שֶׁל מַעְלָה.</p>\n<p>וּמֵאֵלּוּ הַדְּבָרִים שֶׁל בִּלְעָם לָקַחְתִּי, וְרָאִיתִי בָהֶם שֶׁלֹּא הָיָה בָעוֹלָם חָכָם בְּכִשּׁוּפִים כְּדֻגְמָתוֹ. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁבִּטֵּל מֵהָעוֹלָם הַכִּשּׁוּפִים, שֶׁלֹּא יִטְעוּ בְּנֵי אָדָם מֵאַחַר יִרְאָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יִתְבָּרַךְ וְיִתְעַלֶּה שְׁמוֹ אָמֵן.</p>"],[9522012673,"<p>בְּרֵאשִׁית בָּרָא אֱלֹהִים \"אֵת \"הַשָּׁמַיִם \"וְאֵת \"הָאָרֶץ, רָאשֵׁי תֵבוֹת אהו\"ה, שֶׁבּוֹ נִבְרְאוּ שָׁמַיִם וָאָרֶץ. א\"ה - בּוֹ נִבְרְאוּ הַשָּׁמַיִם. ו\"ה - בּוֹ נִבְרְאָה הָאָרֶץ וְכָל מַה שֶּׁיֵּשׁ בָּהּ. וְהוּא נָתַן תְּשׁוּקָה בְּכָל הָאִילָנוֹת וְהָעֲשָׂבִים שֶׁבָּאָרֶץ, שֶׁהוּא מַה שֶּׁאָמְרוּ, אֵין לְךְ כָּל עֵשֶׂב וְעֵשֶׂב מִלְּמַטָּה שֶׁאֵין מְמֻנֶּה עָלָיו מִלְמַעְלָה וְשׁוֹמֵר אוֹתוֹ, שֶׁמַּכֶּה אוֹתוֹ וְאוֹמֵר לוֹ גְּדַל, שֶׁנֶּאֱמַר (איוב לח) הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ:</p>"],[9522012674,"<p>מִשְׁנָה, קְשָׁרִים רָמִים, שָׂרִים מוֹשְׁלִים בַּמֶּמְשָׁלָה, קִרְבוּ וְשִׁמְעוּ. מִי מִכֶּם שֶׁעָלָה וְיָרַד, מִי כִנֵּס רוּחַ בְּיָדוֹ, יָקוּם וְיֵדַע, בְּשָׁעָה שֶׁעָלָה בְרָצוֹן שֶׁל הָרֹאשׁ הַלָּבָן לַעֲשׂוֹת כָּבוֹד לִכְבוֹדוֹ, עָלָה אוֹר אֶחָד נִסְתָּר בָּרֹאשׁ שֶׁל הַכֹּל, נָשַׁב בָּהּ וְהוֹצִיא קְלִפּוֹת מְאִירוֹת מִתְחַבְּרוֹת הַכֹּל כְּאֶחָד, וְעָלוּ וְיָרְדוּ וְנַעֲשָׂה הַכֹּל אֶחָד,</p>\n<p>וְאוֹתוֹ אוֹר נִסְתָּר כְּשֶׁנָּשַׁב בָּהּ וְהֵאִיר נִקְרָא אֶהְיֶ\"ה. אוֹתוֹ אוֹר עָלָה וְיָרַד וְזָרַק נִיצוֹצוֹת וְנָשַׁב בָּהּ, וְהוֹצִיא כֹּחַ טָמִיר אֶחָד, וְנִקְרָא שְׁמוֹ אֲשֶׁר אֶהְיֶ\"ה. בַּחֲקִיקָה טְמִירָה וְנִסְתֶּרֶת, אוֹתָם קְלִפּוֹת מְאִירוֹת שֶׁהִתְחַבְּרוּ מִתּוֹךְ סֶלַע אֶחָד נִסְתָּר, יָצְאוּ בַחֲקִיקָה בְּכֹחַ שֶׁל אוֹתוֹ אוֹת עֶלְיוֹן, וְנִקְרָא יְהֹוָ\"ה.</p>\n<p>עוֹד נָשַׁב בָּהּ וְהוֹצִיא זִיקִים נוֹצְצִים זוֹרְקִים לְכָל עֵבֶר, וְהוֹצִיא כֹּחַ אֶחָד טָמִיר שֶׁנּוֹצֵץ לְכָל צַד וְנִקְרָא אֵ\"ל. עוֹד אוֹתוֹ אוֹר טָמִיר נִסְתָּר נָשַׁב בָּהּ, וְעָלָה וְיָרַד וְעָלָה בְּאֶלֶף וּמָאתַיִם קִשּׁוּרִים שֶׁל אֵשׁ, וְהוֹצִיא כֹּחַ אֶחָד טָמִיר וְנִקְרָא אֱלֹהִים, וְזוֹ הַגְּבוּרָה. מִזֶּה מִתְפַּשְּׁטִים כֹּחוֹת טְמִירִים לוֹהֲטִים לְכָל צַד, מֵהֶם שֶׁמְּתֻקָּנִים בְּתִקּוּנִים יָפִים, וּמֵהֶם שֶׁמְּתֻקָּנִים בְּתִקּוּנִים אֲחֵרִים.</p>\n<p>עוֹד נָשַׁב בָּהּ וְהוֹצִיא כֹּחַ טָמִיר אֶחָד שֶׁנִּקְרָא יְהֹוָ\"ה, מִדַּת רַחֲמִים, וְנִקְרָא שָׁמַיִם. וְעוֹמֵד בֵּין שְׁנֵי חֲיָלוֹת שֶׁנִּקְרָאִים צְבָאוֹת. מִזֶּה יָצְאוּ כָּל הַחֲיָלוֹת וְכָל הַמַּחֲנוֹת הָעֶלְיוֹנִים, כָּל אֶחָד וְאֶחָד לְמִינוֹ לְקַיֵּם וּלְהַנְהִיג אֶת הָעוֹלָמוֹת, עָלָיו כָּתוּב (תהלים פד) ה' צְבָאוֹת אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ:</p>"],[9522012675,"<p>כָּתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, וְכָתוּב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. בֹּא רְאֵה, אוֹר זֶה שֶׁלְּמַטָּה, כְּשֶׁמֵּאִיר מִכֹּחַ שֶׁנִּתַּן לוֹ מֵהַטּוֹב שֶׁלְּמַעְלָה,</p>\n<p>וְלָכֵן מִנְיַן יְמוֹת הַחַמָּה שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה, אַרְבָּעִים וְתִשְׁעָה שָׁבוּעוֹת. מֵהֶם כְּנֶגֶד דַּרְגָּה זוֹ שֶׁל צַדִּיק שֶׁנִּקְרָא טוֹב, וְהוּא שְׁבִיעִי, וְיוֹנֵק מִמֶּנּוּ הַשֶּׁמֶשׁ הַזֶּה שֶׁלְּמַטָּה. שִׁבְעָה שָׁבוּעוֹת שֶׁבַע פְּעָמִים, כְּנֶגֶד שִׁבְעָה שָׁבוּעוֹת שֶׁבַע פְּעָמִים, שֶׁהוּא יוֹנֵק מֵהָאֵם הָעֶלְיוֹנָה שֶׁנִּקְרֵאת יוֹבֵל, וּכְנֶגֶד שְׁנוֹת יוֹבֵל שֶׁלְּמַטָּה.</p>\n<p>נִשְׁאֲרוּ מִשְּׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה עֶשְׂרִים וּשְׁנַיִם יָמִים, כְּנֶגֶד עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁל הַתּוֹרָה שֶׁהָעוֹלָם הַתַּחְתּוֹן עוֹמֵד עֲלֵיהֶם. שֶׁהֲרֵי צַדִּיק שֶׁלְּמַעְלָה נִקְרָא תּוֹרָה שֶׁבִּכְתָב, וּכְשֶׁהִשְׁתַּלְּמוּ אוֹתָם שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה יָמִים, שָׁבִים שֵׁנִית לְקַבֵּל מִדַּרְגָּה זוֹ שֶׁל טוֹב, שֶׁדַּרְגָּה זוֹ וְכָל אוֹתָן שֶׁבַע דְרָגוֹת עֶלְיוֹנוֹת שָׁבוֹת שֵׁנִית לְקַבֵּל מִן הָאֵם הָעֶלְיוֹנָה,</p>\n<p>וְהַדַּרְגָּה הַזּוֹ שֶׁהַלְּבָנָה שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה יוֹנֶקֶת מֵהַדַּרְגָּה הַזּוֹ שֶׁנִּקְרֵאת שְׁכִינָה תַחְתּוֹנָה, שֶׁיּוֹנֶקֶת מֵאוֹתוֹ צַדִּיק. וּבִגְלַל שֶׁאוֹתוֹ צַדִּיק מְמַלֵּא אוֹתָהּ מֵאוֹתָם תַּפְנוּקִים עֶלְיוֹנִים וְיוֹנֶקֶת מִמֶּנּוּ, (נקראת) לְבָנָה. שֶׁכְּמוֹ שֶׁהַלְּבָנָה הַתַּחְתּוֹנָה הַזּוֹ אֵין לָהּ אוֹר מֵעַצְמָהּ אֶלָּא רַק מַה שֶּׁנִּתָּן לָהּ מֵהַשֶּׁמֶשׁ, כָּךְ גַּם אוֹתָהּ דַּרְגָּה שֶׁלְּמַעְלָה,</p>\n<p>וְדַרְגָּה זוֹ נִקְרֵאת יָם הַחָכְמָה לְמַעְלָה. וְעוֹמְדִים שְׁנֵים עָשָׂר שְׁבָטִים עֶלְיוֹנִים קְדוֹשִׁים, שְׁלֹשָׁה לַצָּפוֹן וּשְׁלֹשָׁה לַדָּרוֹם, וּשְׁלֹשָׁה לַמַּעֲרָב וּשְׁלֹשָׁה לַמִּזְרָח, וְיָם הַחָכְמָה הַזֶּה עֲלֵיהֶם. וּכְנֶגְדָּם לְמַטָּה שְׁנֵים עָשָׂר שְׁבָטִים עוֹמְדִים סְבִיב הַמִּזְבֵּחַ כַּדֻּגְמָה הַ את. וּכְנֶגֶד הַדַּרְגָּה הַזּוֹ עָשָׂה שְׁלֹמֹה הַיָּם שֶׁלְּמַטָּה עוֹמֵד עַל שְׁנֵים עָשָׂר בָּקָר,</p>\n<p>וְהַיָּם הַזֶּה לְמַעְלָה נִקְרָא יָ\"ם. מָה הַטַּעַם נִקְרָא יָם? אֶלָּא מִשּׁוּם אוֹתָהּ דַּרְגָּה שֶׁל צַדִּיק שֶׁמְּמַלֵּאת הַיָּם הַזֶּה נִקְרָא יוֹם, שֶׁכָּתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, וְכָתוּב (תהלים צז) אוֹר זָרֻעַ לַצַּדִּיק, וְזֶה מֵאִיר בְּסוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁבּוֹ מְמַלֵּא לַיָּם הַזֶּה שֶׁנִּקְרָא הֵ\"א תַחְתּוֹנָה (אחרונה של השם הקדוש).</p>\n<p>זֶהוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶת הַיָּם, וְכָל זֶה דַּרְגַּת הַצַּדִּיק שֶׁנִּקְרֵאת כֹּל, מִשּׁוּם שֶׁכָּל הַתַּפְנוּקִים יוֹצְאִים מִמֶּנּוּ. הַנְּחָלִים אֵלּוּ חֲמֵשׁ הַדְּרָגוֹת שֶׁעִמּוֹ, הוֹלְכִים אֶל הַיָּם לְמַלֵּא אוֹתָהּ,</p>\n<p>וְזוֹ הַדַּרְגָּה נִקְרֵאת בַּת שֶׁבַע. וּכְשֶׁמֵּאִיר הַצַּדִּיק הַזֶּה לַדַּרְגָּה הַזּוֹ בְּסוֹד שֶׁל שִׁבְעָה שָׁבוּעוֹת שֶׁבַע פְּעָמִים הַשֶּׁמֶשׁ הַתַּחְתּוֹנָה מְאִירָה בְּסוֹד שֶׁל שִׁבְעָה שָׁבוּעוֹת, שֶׁבַע פְּעָמִים לַלְּבָנָה.</p>\n<p>מִשּׁוּם כָּךְ שְׁנַת הַלְּבָנָה שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים וַחֲמִשָּׁה יָמִים, אַרְבָּעִים וְתִשְׁעָה שָׁבוּעוֹת, מֵהֶם כְּנֶגֶד הַדַּרְגָּה הַשְּׁבִיעִית הַזּוֹ הַיָּם הָעֶלְיוֹן, שֶׁמְּאִירָה מֵהַצַּדִּיק בְּתִשְׁעָה וְאַרְבָּעִים שָׁבוּעוֹת אוֹרוֹת עֶלְיוֹנִים. נִשְׁאֲרוּ תְרֵיסַר ימִים לְחֶשְׁבּוֹן שְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וַחֲמִשִּׁים כְּנֶגֶד שְׁנֵים עָשָׂר שְׁבָטִים שֶׁסְּבִיב הַיָּם הַזֶּה לִשְׁמֹר מִשְׁמֶרֶת הַמִּשְׁכָּן בִּתְרֵיסַר שְׁעָרִים עֶלְיוֹנִים שֶׁיֵּשׁ בִּירוּשָׁלַיִם הָעֶלְיוֹנָה, (ומדרך) וְדֶרֶךְ אוֹתָם שְׁעָרִים עֶלְיוֹנִים יוֹנְקִים אוֹתָם שְׁבָטִים מֵאִמָּא תַחְתּוֹנָה, כָּל אֶחָד לְצִדּוֹ כָּרָאוּי לוֹ, זֶהוּ שֶׁכָּתוּב (יחזקאל מח) שַׁעַר יְהוּדָה אֶחָד,</p>\n<p>וְעַל זֶה כָּתוּב (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי, זוֹ דַּרְגַּת צַדִּיק שֶׁמֵּאִיר בַּכֹּחַ שֶׁל שְׁמִי. וְלִכְבוֹדִי בְּרָאתִיו - לְהָאִיר לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא כְּבוֹדִי בְּרָאתִיו, וְזֶהוּ יָם הַחָכְמָה שֶׁנִּקְרָא כְּבוֹד ה' שֶׁנִּתְגַּלָּה בַּמִּשְׁכָּן. יְצַרְתִּיו - זֶה סוֹד הַיּוֹם שֶׁלְּמַטָּה שֶׁהוּא כְּנֶגֶד כֹּל שֶׁלְּמַעְלָה, וְעַל כָּךְ כָּתוּב (שם מה) יוֹצֵר אוֹר. וּבַצַּדִּיק הַזֶּה שֶׁלְּמַעְלָה לֹא כָתוּב בּוֹ יְצִירָה, עַד שֶׁיִּתְגַּלֶּה מַעֲשֵׂהוּ לְמַטָּה וּמֵאִיר לָעוֹלָם שֶׁלְּמַטָּה מִמֶּנּוּ.</p>\n<p>אַף עֲשִׂיתִיו - זוֹ הַלְּבָנָה לְמַטָּה, זֶהוּ שֶׁכָּתוּב וּבוֹרֵא חֹשֶׁךְ. כְּשֶׁהִתְחַבְּרוּ, אָז עוֹשֶׂה שָׁלוֹם, שָׁלוֹם לָעוֹלָם, זֶהוּ שֶׁכָּתוּב (בראשית א) וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. וְאָז יִחוּד לְמַעְלָה יִחוּד לְמַטָּה, שָׁלוֹם לְמַעְלָה שָׁלוֹם לְמַטָּה.</p>\n<p>כְּמוֹ זֶה יוֹסֵף לְמַטָּה, שֶׁהֲרֵי אָחוּז בַּצַּדִּיק שֶׁלְּמַעְלָה. כְּשֶׁמִּשְׁתַּלֵּם לְמַטָּה, מוֹסִיף שָׁלוֹם בְּכָל הָעוֹלָמוֹת וּבְכָל הַיָּמִים הָעֶלְיוֹנִים. כָּתוּב כָּאן (שם טל) וַיְהִי כְּדַבְּרָה אֶל יוֹסֵף יוֹם יוֹם, וְכָתוּב שָׁם (תהלים סח) בָּרוּךְ ה' יוֹם יוֹם יַעֲמָס לָנוּ. מִשּׁוּם שֶׁלֹּא שָׁמַע לְאֵשֶׁת פּוֹטִיפַר יוֹם יוֹם, אָז יָמִים הָעֶלְיוֹנִים בְּשָׁלוֹם וּבְרָכוֹת בְּכָל הָעוֹלָמוֹת:</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם (בראשית א), שָׁם שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, מַה זֶּה שֶׁכָּתוּב (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵיךְ בָּךְ בֹּא? רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, עֲשָׂאוֹ מֵאוֹתוֹ הָאוֹר הַנֶּאֱצָל מִלְמַעְלָה, וּבָרָא אֶת הַשָּׁמַיִם מֵאוֹתוֹ רָקִיעַ הָרִאשׁוֹן שֶׁהֱכִינוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּבְרָאוֹ בַּתְּחִלָּה, וְאוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל שְׁאָר הָרְקִיעִים שֶׁנִּתְהַוּוּ מִמֶּנּוּ.</p>\n<p>וְאָמַר רַב יְהוּדָה אָמַר רַב, אוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל הַמְּאוֹרוֹת מֵאוֹתוֹ הָאוֹר שֶׁמְּקַבֵּל מִלְמַעְלָה, וּכְשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ רָקִיעַ, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמְּאוֹרוֹת וְהִנִּיחָם בְּאוֹתוֹ רָקִיעַ הַנִּקְרָא רְקִיעַ הַשָּׁמַיִם, וְאוֹתוֹ רָקִיעַ נִתְהַוָּה מִן הַשָּׁמַיִם.</p>\n<p>שֶׁאָמַר רַבִּי יְהוּדָה אָמַר רַב, הָרָקִיעַ הָעֶלְיוֹן הוֹלִיד אֶת הַשָּׁמַיִם אֲשֶׁר תַּחְתָּיו, וְהַשָּׁמַיִם הוֹלִידוּ אֶת הָרָקִיעַ הַזֶּה, וְנִקְרְאוּ רְקִיעַ הַשָּׁמַיִם, וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא הַמְּאוֹרוֹת הַלָּלוּ וּנְתָנָם בּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם.</p>\n<p>אָמַר רַבִּי יִצְחָק, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הַמְּאוֹרוֹת הַלָּלוּ וְהִנִּיחָם בְּזֶה הָרָקִיעַ לִהְיוֹת מֶמְשָׁלָה עַל הָאָרֶץ וּלְהִשְׁתַּמֵּשׁ בָּהֶם הַבְּרִיּוֹת, וּשְׁנֵיהֶם נָתְנוּ אוֹרָם בְּשָׁוֶה. אָמְרָה הַלְּבָנָה, אֵין נָאֶה לְהִשְׁתַּמֵּשׁ וּלְהִתְנַהֵג בִּשְׁנֵי כְתָרִים בְּשָׁוֶה. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִמְעִיט אוֹתָהּ, וְהַיְנוּ הַכַּפָּרָה שֶׁל שְׂעִיר רֹאשׁ חֹדֶשׁ שֶׁנֶּאֱמַר בּוֹ (במדבר כח) חַטָּאת לַה'.</p>\n<p>אָמַר רַבִּי יַעֲקֹב, בְּכַמָּה מְקוֹמוֹת שָׁנִינוּ אֶת זֶה, וְלֹא הִתְיַשֵּׁב בְּלִבִּי הָעִנְיָן. כְּשֶׁבָּא רַב נַחְמָן, בָּאוּ וְשָׁאֲלוּ אוֹתוֹ. אָמַר כְּמַשְׁמָעוֹ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יַעֲקֹב, כְּלוּם אַתָּה רוֹצֶה לַעֲבֹר עַל דִּבְרֵי חֲבֵרֶיךְ? שָׁתַק.</p>\n<p>רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא בָּא לִרְאוֹת אֶת רַבִּי אֶלְעָזָר חֲתָנוֹ. יָצְאָה בִתּוֹ וְלָקְחָה יָדָיו לְנַשֵּׁק אוֹתָם. אָמַר לָהּ, לְכִי וּמַעֲטִי עַצְמֵךְ מִלִּפְנֵי בַעְלֵךְ, שֶׁהוּא קָדוֹשׁ. שָׁמַע רַבִּי אֶלְעָזָר וְאָמַר, עַכְשָׁו יָדַעְתִּי, אֲנִי נִזְכָּר בְּדָבָר אֶחָד, שֶׁהִיא מַרְגָּלִית יְקָרָה שֶׁנֶּאֱמַר עַל הַלְּבָנָה, כְּמוֹ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לַלְּבָנָה לְכִי וּמַעֲטִי אֶת עַצְמֵךְ, שֶׁחָשְׁבָה הַלְּבָנָה שֶׁלֹּא נִתָּן לָהּ שִׁלְטוֹן. אָמַר לוֹ חָמִיו, כָּךְ אֲנִי שָׁמַעְתִּי וְכָךְ הָיָה מְסֻדָּר בְּלִבִּי, וּכְדֵי שֶׁלֹּא לַעֲבֹר עַל דַּעַת חֲבֵרַי שָׁתַקְתִּי.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ עַם נוֹשַׁע בַּה' מָגֵן עֶזְרֶךְ וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךְ. אָמַר רַבִּי אֶלְעָזָר, וְכִי גַאֲוָתָם שֶׁל יִשְׂרָאֵל בַּחֶרֶב הוּא? לֹא כָּךְ! שֶׁהֲרֵי הַחֶרֶב נִתְּנָה לְעֵשָׂו, שֶׁכָּתוּב (בראשית כז) וְעַל חַרְבְּךְ תִחְיֶה.</p>\n<p>אֶלָּא כָּךְ שָׁמַעְתִּי מֵאָבִי, שֶׁאֵלּוּ תַּלְמִידֵי חֲכָמִים, שֶׁכַּאֲשֶׁר שׁוֹמְעִים דָּבָר וְלֹא מִתְיַשֵּׁב בְּלִבָּם, וְהֵם עוֹרְכִים קְרָב זֶה עִם זֶה כְּאוֹתָם עוֹרְכֵי קְרָבוֹת בְּחֶרֶב, וְרוֹצִים לַהֲרֹג זֶה אֶת זֶה עָלֶיהָ,</p>\n<p>וְדָבָר זֶה שֶׁאָמְרוּ חֲבֵרֵינוּ כָּךְ הִיא, וְכָךְ גָּזַרְנוּ בְּסוֹד מִשְׁנָתֵנוּ.</p>\n<p>שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַשֶּׁמֶשׁ וְאֶת הַלְּבָנָה, גָּזַר עַל הַשֶּׁמֶשׁ לִהְיוֹת שִׁלְטוֹן שֶׁל עֵשָׂו, וְעַל הַלְּבָנָה לִהְיוֹת בָּעוֹלָם הַזֶּה שִׁלְטוֹן שֶׁל יַעֲקֹב, וּמִנָּה עֲלֵיהֶם גְּדוֹלִים וְתַקִּיפִים עַד שֶׁיָּבאוּ שְׁתֵּי הָאֻמּוֹת הַלָּלוּ, וְאוֹתוֹ גָדוֹל שֶׁהִתְמַנָּה עַל הַלְּבָנָה בִּשְׁבִיל הָאֻמָּה שֶׁל יַעֲקֹב, רָצָה מִן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּנָּתֵן שִׁלְטוֹן לַלְּבָנָה בָּעוֹלָם הַזֶּה, כְּלוֹמַר לָאֻמָּה שֶׁל יַעֲקֹב. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי מָה אֲנִי צָרִיךְ אֻמָּה שֶׁל יַעֲקֹב (חסר כאן). אֶלָּא בָּעוֹלָם הַבָּא, וְלִשְׁלֹט בָּהֶם עַל כָּל הָאֻמּוֹת, אֲבָל בָּעוֹלָם הַזֶּה לְכִי וּמַעֲטִי אֶת עַצְמֵךְ וְהִשְׁתַּעְבְּדִי בַּגָּלוּת לְזַכּוֹת אוֹתָךְ לָעוֹלָם הַבָּא.</p>\n<p>וּכְשֶׁבָּאוּ אֻמָּה שֶׁל יַעֲקֹב וְהִתְרַעֲמוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁנִּטַּל מֵהֶם הַשִּׁלְטוֹן וְנִתַּן לְעֵשָׂו, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: וְכִי מָה אַתֶּם רוֹצִים שִׁלְטוֹן בָּעוֹלָם הַזֶּה? שֶׁהֲרֵי אֲנִי עָרֵב לְהַשְׁלִיט אֶתְכֶם לָעוֹלָם הַבָּא עַל כָּל הָאֻמּוֹת, וְלָכֵן הָבִיאוּ כַפָּרָה עָלַי. כְּלוֹמַר, עַל אוֹתָהּ הַבְטָחָה שֶׁאֲנִי עָרֵב. לְכוּ וְהָבִיאוּ כַפָּרָה וְהִתְעַסְּקוּ בַתּוֹרָה, וְעָלַי לָתֵת לָכֶם שָׂכָר טוֹב, וְעָלַי לְהַשְׁלִיט אֶתְכֶם עַל כָּל הָעַמִּים, שֶׁעַל מְנָת כֵּן מִעַטְתִּי אֶת הַיָּרֵחַ בָּעוֹלָם.</p>\n<p>בָּא רַבִּי יוֹסֵי וּנְשָׁקוֹ בְרֹאשׁוֹ, וְקָרָא לְבִתּוֹ וְאָמַר לָהּ, כְּלִי הַגָּדוֹל שֶׁל הָאוֹר וְהַמְּנוֹרָה שֶׁנֶּחְלְקָה בְּטוֹבוֹת יֵשׁ לָךְ. אַשְׁרַיִךְ וְאַשְׁרֵי חֶלְקֵךְ, וְאַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לִרְאוֹת כָּךְ.</p>\n<p>רַבִּי יוֹחָנָן אָמַר, זָכוּ יִשְׂרָאֵל שֶׁהֵאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֵינָם צְרִיכִים לְמָאוֹר אַחֵר, שֶׁכָּתוּב (ישעיה ס) וְהָיָה לָךְ ה' לְאוֹר עוֹלָם.</p>\n<p>אָמַר רַבִּי אַבָּהוּ, כֵּיוָן שֶׁנִּתְחַלֵּף לָהֶם הַשִּׁלְטוֹן, מוֹנִים חֶשְׁבּוֹן לַלְּבָנָה שֶׁבָּהּ מְנַהֶגֶת נֹהֵג כַּצֹּאן יוֹסֵף. וּמוּם אֵין בָּךְ - שֶׁלֹּא נִמְצָא בָּהּ חִסָּרוֹן בִּשְׁבִיל מוֹעֲדִים וּזְמַנִּים:</p>"],[9522012676,"<p>רַעָיָא מְהֵימְנָא אָמַר לוֹ, מְנוֹרָה הַקְּדוֹשָׁה, אַחַר שֶׁאָמַר (בראשית א) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, מַהוּ שֶׁאָמַר אַחַר כָּךְ וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ? אָמַר לוֹ, מַה שֶּׁבֵּאֲרוּ עַל כָּךְ בַּעֲלֵי הַמִּשְׁנָה, שֶׁמֵּהֶם אָמְרוּ נִבְרָא, וּמֵהֶם אָמְרוּ לֹא נִבְרָא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ, שֶׁכָּתוּב (שם) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ.</p>\n<p>אָמַר לוֹ, אִם כָּךְ הוּא, לֹא יִתֵּן חֵלֶק בְּיַד אֶחָד מֵהֶם וְלֹא נַעֲשָׂה בַּדְּמוּת שֶׁלָּהֶם, אֶלָּא בְּאִיקוֹנִין שֶׁל הַמֶּלֶךְ, בְּצַלְמוֹ כִּדְמוּתוֹ, שֶׁהוּא צֶלֶם וּדְמוּת תַּבְנִיתוֹ. אָמַר, כָּךְ נוֹדָע? אָמַר, חַס וְשָׁלוֹם, אֶלָּא אֲנִי אוֹמֵר שֶׁנִּבְרָא בַּכֹּל וְהִשְׁלִיטוֹ עַל הַכֹּל, שֶׁאִם הָיָה כָּל אֶחָד נוֹתֵן בּוֹ חֶלְקוֹ, בִּזְמַן שֶׁהָיָה כּוֹעֵס עָלָיו כָּל אֶחָד הָיָה נוֹטֵל חֶלְקוֹ מִמֶּנּוּ, כִּי בַּמֶּה נֶחְשָׁב הוּא?</p>\n<p>אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ כָּל אֶחָד בִּדְמוּתוֹ, זוֹהִי מַלְכוּת הַקְּדוֹשָׁה שֶׁהִיא תְּמוּנַת כֹּל, שֶׁבָּהּ הִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא וּבָרָא אֶת הָעוֹלָם וְכָל הַבְּרִיּוֹת שֶׁבָּרָא בָּעוֹלָם, וְכָלַל בָּהּ עֶלְיוֹנִים וְתַחְתּוֹנִים בְּלִי פֵּרוּד כְּלָל, וְכָלַל בָּהּ עֶשֶׂר סְפִירוֹת, וְכָל הַשֵּׁמוֹת וְהַכִּנּוּיִים וְהַהֲוָיוֹת, וְעִלַּת עַל הַכֹּל שֶׁהוּא אָדוֹן עַל הַכֹּל, וְאֵין אֱלוֹהַּ מִבִּלְעָדָיו, וְלֹא נִמְצָא בְּכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים פָּחוֹת מִמֶּנּוּ. בִּגְלַל שֶׁהוּא קֶשֶׁר שֶׁל כֻּלָּם וְהַשְּׁלֵמוּת שֶׁל כֻּלָּם, לְקַיֵּם בּוֹ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וּבִגְלַל שֶׁלֹּא נִמְצָא עִלַּת עַל הַכֹּל בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים פָּחוֹת מִמֶּנּוּ אֲפִלּוּ בְּאֶחָד מֵהֶם, הִיא (נקראת) הִתְקָרְבָה אֱמוּנַת יִשְׂרָאֵל. וּמִצַּד שֶׁל עִלַּת עַל הַכֹּל נֶאֱמַר בָּהּ (דברים ד) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. אֲבָל מִצַּד שֶׁל שְׁאָר הָעַמִּים נֶאֱמַר בָּהֶם (בה) (במדבר יב) וּתְמוּנַת ה' יַבִּיט.</p>\n<p>בָּא הַמְּנוֹרָה הַקְּדוֹשָׁה וּשְׁאָר הַחֲבֵרִים וְהִשְׁתַּחֲווּ לְפָנָיו וְאָמְרוּ, כָּעֵת אֵין מִי שֶׁיָּכוֹל לִטֹּל מִמֶּנּוּ אֶת חֶלְקוֹ, שֶׁלֹּא נָתַן לוֹ אֶחָד מֵהָעוֹלָם, אֶלָּא בּוֹרֵא הָעוֹלָמוֹת עִלַּת עַל הַכֹּל, וּבוֹ תָלוּי עָנְשׁוֹ אוֹ שְׂכָרוֹ, וְלֹא בְמַלְאָךְ וְשָׂרָף וְלֹא בְּשׁוּם בְּרִיָּה מֵהָעוֹלָם, וּבִגְלַל כָּךְ פֵּרְשׁוּהָ חַכְמֵי הַמִּשְׁנָה, הַמְשַׁתֵּף שֵׁם שָׁמַיִם וְדָבָר אַחֵר נֶעֱקָר מִן הָעוֹלָם: ע\"כ.</p>"],[9522012677,"<p>לֹבֶן שֶׁל הַתּוֹרָה, וּכְשֶׁאוֹתוֹ אוֹר מִתְלַבֵּשׁ בַּחֹשֶׁךְ, נֶאֱמַר בַּתּוֹרָה שְׁחוֹרָה אֲנִי וְנָאוָה. וּכְשֶׁמִּתְעַלֶּה מִשָּׁם אוֹר שֶׁהוּא לָבָן, אוֹמֶרֶת אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, וְהַתּוֹרָה כְּמוֹ שֶׁבַּת עַיִן, שֶׁהִיא שְׁחוֹרָה וְיָפָה בָּאוֹר שֶׁמֵּאִיר בָּהּ,</p>\n<p>וְלָכֵן בַּת עַיִן וְהָאוֹר שֶׁמֵּאִיר בָּהּ אָמְרָה ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא. אוֹרִי - אוֹר י', שֶׁהִיא בַּת עַיִן, וּשְׁנֵי גְוָנִים יֵשׁ לָהּ - אוֹר מִבִּפְנִים וְחֹשֶׁךְ מִבַּחוּץ, לִהְיוֹת שׁוֹלֵט בָּהֶם עַל כָּל הַקִּלּוּסִים (קלפות). זֶהוּ שֶׁכָּתוּב (תהלים קג) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה.</p>\n<p>בִּלְבוּשׁ שֶׁל אוֹר הִיא שׁוֹלֶטֶת עַל כָּל אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (שמות י) וּלְכָל בְּנֵי יִשְׂרָאֵל הָיָה אוֹר בְּמוֹשְׁבֹתָם, וּבִלְבוּשׁ שָׁחֹר שׁוֹלֶטֶת עַל הָרְשָׁעִים שֶׁנֶּאֱמַר בָּהֶם (שמואל א ב) וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ.</p>\n<p>וְעוֹד, אוֹר הוּא מִצַּד הַיָּמִין (חסד), שֶׁהוּא אוֹר שֶׁל יוֹם רִאשׁוֹן שֶׁנֶּאֱמַר בּוֹ יְהִי אוֹר, זֶה אַבְרָהָם, וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. חֹשֶׁךְ מִצַּד הַשְּׂמֹאל, שֶׁנֶּאֱמַר בּוֹ בְּיִצְחָק (שם כז) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, וְלַחֹשֶׁךְ קָרָא לָיְלָה. יַעֲקֹב שֶׁהָיָה לָבוּשׁ מִשְּׁנֵיהֶם בָּאוֹר שֶׁל יָמִין וּבַחֹשֶׁךְ שֶׁל שְׂמֹאל,</p>\n<p>וּבִשְׁנֵיהֶם עַמּוּד הָאֶמְצָעִי הוּא עַמּוּד. עֵמּוּד הֶעָנָן יוֹמָם וְעַמּוּד הָאֵשׁ לַיְלָה לִפְנֵי הָעָם. הֶעָנָן מִצַּד שֶׁלּוֹ מַיִם. הַחֹשֶׁךְ מִצַּד שֶׁלּוֹ אֵשׁ. עַמּוּד הוּא שָׁלוֹם בֵּינֵיהֶם. זֶהוּ שֶׁכָּתוּב (איוב כח) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. וּכְשֶׁהוּא בָּאֶמְצַע - וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלַּיְלָה. לֹא קָרַב הַמַּיִם לָאֵשׁ, וְלֹא אֵשׁ לַמַּיִם, שֶׁהוּא מַפְרִיד בֵּינֵיהֶם. וְזוֹהִי מַחֲלֹקֶת בֵּית הִלֵּל וּבֵית שַׁמַּאי שֶׁהִיא לְשֵׁם שָׁמַיִם, וּכְנֶגְדָּם שְׁנֵי אָמוֹרָאִים שֶׁל הָרָקִיעַ, מִיכָאֵל וְגַבְרִיאֵל, וְשַׂר שָׁלוֹם מַכְרִיעַ בֵּינֵיהֶם, שֶׁהוּא נוּרִיאֵל. אוּרִיאֵל נִקְרָא מִצַּד הַיָּמִין, נוּרִיאֵל מִצַּד הַשְּׂמֹאל, וְהוּא אָדָם שֶׁלְּמַטָּה, מטטרו\"ן שְׁמוֹ, שׁוֹלֵט עַל כָּל בַּעֲלֵי הַמִּשְׁנָה. זֶהוּ שֶׁכָּתוּב (בראשית א) וְיִּרְדּוּ בִּדְגַת הַיָּם, אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁמִּתְרַבִּים בְּמֵי הַתּוֹרָה, שֶׁיּוֹרְשִׁים מִשָּׁם נֶפֶשׁ חַיָּה.</p>\n<p>וּבְעוֹף הַשָּׁמַיִם - אֵלּוּ בַּעֲלֵי זְכֻיּוֹת, שֶׁבִּזְכוּתָם פּוֹרְחִים לְמַעְלָה, וְיוֹרְשִׁים מִשָּׁם רוּחַ שֶׁהוּא עוֹף יְעוֹפֵף בַּכְּנָפַיִם בְּמִצְווֹת עֲשֵׂה. וּבַבְּהֵמָה - אֵלּוּ עַמֵּי הָאָרֶץ שֶׁנֶּאֱמַר בָּהֶם (במדבר יד) אַל תִּירְאוּ אֶת עַם הָאָרֶץ כִּי לַחְמֵנוּ הֵם. ע\"כ.</p>\n<p>כְּשֶׁהָאוֹר הוּא, רַנְּנוּ צַדִּיקִים בַּה', וְזוֹ דַּרְגָּה שֶׁל צַדִּיק חַי הָעוֹלָמִים, וּמִשָּׁם רִנָּה וּבוֹ הַגְּאֻלָּה. זֶהוּ שֶׁכָּתוּב (ירמיה כג) צֶמַח צַדִּיק, וַדַּאי שֶׁהוּא עֲשִׂירִי, וְצַדִּיק נוֹסֵעַ מִשְּׂמֹאל, וְעַמּוּד הָאֶמְצַע מִיָּמִין. זֶהוּ שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ.</p>\n<p>בֹּא רְאֵה, כָּל הָאוֹתִיּוֹת הֵן מִצַּד אוֹתִיּוֹת הַתּוֹרָה שֶׁכְּלוּלוֹת בַּשְּׁכִינָה, וְצַדִּיק נוֹסֵעַ מִשְּׂמֹאל, קֵץ חַי שֶׁהוּא יִצְחָק בְּהִפּוּךְ. חַי הָעוֹלָמִים קָשׁוּר בִּשְׂמֹאל,</p>\n<p>וּשְׁכִינָה תַּחְתּוֹנָה מִצַּד שְׂמֹאל נֶאֱמַר בָּהּ וְהָאָרֶץ הָיְתָה. מִצַּד הַיָּמִין תֹּהוּ וָבֹהוּ, בּוֹ הוּא מִצַּד עַמּוּד הָאֶמְצָעִי. וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם - זוֹ שְׁכִינָה הַתַּחְתּוֹנָה.</p>\n<p>וּמִי גָרַם לָהּ אֶת זֶה? אֶלָּא הַקָבָּ\"ה קֹדֶם שֶׁבָּרָא אֶת הָעוֹלָם הָיָה נִסְתָּר יְהֹוָ\"ה, אַחַר כָּךְ הִתְפַּשְּׁטָה ה' לְמַטָּה, וְנֶאֱמַר בָּהּ וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ, וְסוֹד הַדָּבָר - אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. הֲרֵי לְךְ שֶׁהָיָה לְבוּשָׁהּ תֹּהוּ.</p>\n<p>וּבִגְלַל זֶה כִּי לֹא הִמְטִיר ה' אֱלֹהִים, עֲדַיִן לֹא הָיָה יוֹרֵד הַשֶּׁפַע שֶׁלָּהּ בִּגְלַל שֶׁאָדָם אַיִן, שֶׁהָיָה בַּעְלָהּ נִסְתָּר בְּאַיִן. עַד שֶׁהִתְפַּשֵּׁט ה' מִן יה\"ו, שֶׁהוּא בִּינָה, שֶׁהוּא מְקוֹר הַשֶּׁפַע, שֶׁהִיא נְקֻדָּה נִסְתֶּרֶת, וּמִשָּׁם הִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה.</p>\n<p>וְקֹדֶם שֶׁיָּרְדָה הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן, בִּגְלַל זֶה הָיָה הַשֶּׁפַע יוֹרֵד בְּאוֹתוֹ זְמַן הִיא רֵאשִׁית מֵחֶסֶד, זֶהוּ שֶׁכָּתוּב (תהלים פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. וּבִגְלַל זֶה לֹא תֹהוּ בְּרָאָהּ לָשֶׁבֶת יְצָרָהּ, וְנֶאֱמַר בָּהּ לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ, שֶׁלֹּא תֹהוּ בְּרָאָהּ.</p>\n<p>וּבִזְמַן שֶׁהָיָה תֹהוּ, אָמַר אֱלֹהִים לְנֹחַ, קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגוֹ', קֵץ שֶׁל יִצְחָק שֶׁנֶּאֱמַר בּוֹ כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי, שֶׁאִם אַתָּה הָיִיתָ מְבַקֵּשׁ רַחֲמִים עֲלֵיהֶם, לֹא נֶחְרְבוּ. וְהוּא הָיָה אוֹמֵר לוֹ בְּרֶמֶז כְּדֵי שֶׁיְּבַקֵּשׁ רַחֲמִים עֲלֵיהֶם, וְלֹא יָמוּת מָשִׁיחַ שֶׁהוּא מִצַּד הַשְּׂמֹאל.</p>\n<p>אָמַר לוֹ, וַהֲרֵי הָיָה בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן קֹדֶם שֶׁנִּבְרָא הָעוֹלָם? אֶלָּא מַגִּיד מֵרֵאשִׁית אַחֲרִית, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה בְמַחֲשַׁבְתּוֹ כָּל הַדּוֹרוֹת שֶׁהָיָה בּוֹנֶה, וְנֶחְרְבוּ קֹדֶם שֶׁנִּבְרְאוּ. רָאָה שֶׁהָיוּ עוֹשִׂים מַעֲשִׂים שֶׁיֶּחֶרְבוּ, וְכֵיוָן שֶׁבָּרָא, חָשַׁב כְּאִלּוּ הֶחֱרִיבָם, וְזֶה מְדַבֵּר עַד סוֹף הַיָּמִים שֶׁאֵלֶּה תּוֹלָדוֹת רָעוֹת, וְהָיוּ גוֹרְמִים דְּנָהָר יֶחֱרַב וְיָבֵשׁ. יֶחֱרַב בְּבַיִת רִאשׁוֹן, וְיָבֵשׁ בְּבַיִת שֵׁנִי. הַנְּבִיעָה שֶׁלּוֹ בִּשְׁנֵי עוֹלָמוֹת, שְׁכִינָה עֶלְיוֹנָה וּשְׁכִינָה תַּחְתּוֹנָה.</p>\n<p>וּלְנֹחַ הִתְגַּלָּה מַה שֶּׁהָיָה וּמַה שֶּׁעָתִיד לִהְיוֹת, וְלֹא בִקֵּשׁ עֲלֵיהֶם רַחֲמִים, עַד שֶׁבָּא מֹשֶׁה וּבִקֵּשׁ רַחֲמִים, שֶׁעֲתִידִים הָיוּ יִשְׂרָאֵל שֶׁלֹּא יֵצְאוּ אֶלָּא אֶחָד מֵעִיר וּשְׁנַיִם מִמִּשְׁפָּחָה, מִצַּד הַגְּבוּרָה שֶׁהָיוּ דָנִים, וְהֻחְזַר הָעוֹלָם לְתֹהוּ. וּבִגְלַל שֶׁמֹּשֶׁה בִּקֵּשׁ עֲלֵיהֶם רַחֲמִים, הַשְּׂמֹאל דּוֹחָה וְלֹא יָצְאוּ בָהּ בְּנֵי יִשְׂרָאֵל,</p>\n<p>וְיָמִין מְקָרֶבֶת שֶׁהִיא יָמִין מַטֶּה כְּלַפֵּי חֶסֶד. וּמֹשֶׁה, בִּגְלַל שֶׁנָּתַן עַצְמוֹ עֲלֵיהֶם, נָתַן תֹּקֶף לְדַרְגָּתוֹ, שֶׁהִיא עַמּוּד הָאֶמְצָעִי, שֶׁהִיא תּוֹרָה שֶׁנִּתְּנָה בְּיָמִין. זֶהוּ שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, וּבִגְלַל זֶה הַגְּאֻלָּה תְּלוּיָה בּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית מט) לֹא יָסוּר שֵׁבֶט מִיהוּדָה, עַד כִּי יָבֹא \"שִׁילֹה\", שֶׁהוּא מֹשֶׁה בְּחֶשְׁבּוֹן.</p>\n<p>יְסוֹד צַדִּיק בּוֹ סוֹ\"ד תְּהֵא שְׂמֹאל דּוֹחָה, אַף עַל פִּי שֶׁפֵּרַשְׁנוּ בוֹ כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה שִׁשִּׁים וָשֵׁשׁ, בִּגְלַל שֶׁנִּקְשָׁר בִּשְׂמֹאל, וְיָמִין מְקָרֶבֶת כִּי תָלוּי מִמֶּנָּה עַמּוּד הָאֶמְצָעִי,</p>\n<p>שֶׁשִּׁשִּׁים וָשֵׁשׁ הֵם שִׁשִּׁים מַסֶּכְתּוֹת, וְשִׁשָּׁה סִדְרֵי מִשְׁנָה שֶׁנִּתְּנוּ מִגְּבוּרָה שֶׁהִיא שְׂמֹאל. שִׁשִּׁים גִּבּוֹרִים נִקְרְאוּ שֶׁנּוֹסְעִים מִגְּבוּרָה, שֶׁשָּׁם תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁהִיא שְׁכִינָה תַּחְתּוֹנָה, כְּלָל שֶׁל שִׁשִּׁים מַסֶּכְתּוֹת וְשִׁשָּׁה סִדְרֵי מִשְׁנָה.</p>\n<p>שֶׁתּוֹרָה שֶׁבִּכְתָב, לַפֶּה לֹא הִתְגַּלְּתָה, בִּגְלַל שֶׁעָתִיד שְׂמֹאל, שֶׁהִיא פֶּה, לְהִדָּחוֹת. וְלָכֵן הוּא מַסְתִּיר כָּךְ הַגְּאֻלָּה בַּלֵּב, וְהַפֶּה שֶׁהוּא גָלוּי לֹא מִתְגַּלָּה הַגְּאֻלָּה,</p>\n<p>וּבִגְלַל שֶׁהַכֹּל תָּלוּי בַּיָּמִין, אָמַר הַנָּבִיא (ישעיה נג) וּזְרוֹעַ ה' עַל מִי נִגְלָתָה. עַל מִי וַדַּאי, שֶׁנֶּאֱמַר בָּהּ מִי יִרְפָּא לָךְ,</p>\n<p>זֶהוּ שֶׁכָּתוּב (איכה ב) מָ\"ה אֲעִידֵךְ מָ\"ה אֲדַמֶּה לָּךְ, וְאָמְרוּ לִי מַ\"ה שְּׁמוֹ, בְּמַ\"ה יָבא הַזְּמַן, וּבְמַ\"ה תָּבא רְפוּאָה. זֶהוּ שֶׁכָּתוּב (שם) מָה אַשְׁוֶה לָּךְ וַאֲנַחֲמֵךְ וְגוֹמֵר, מִ\"י יִרְפָּא לָךְ, שֶׁמֹּשֶׁה הוּא מַ\"ה שְּׁמוֹ וּבוֹ תְּהֵא נֶחָמָתֵךְ. וּבִגְלַל כָּךְ כָּפַל הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁמוֹ מֹשֶׁה מֹשֶׁה, אֶחָד עַל גְּאֻלָּה הָרִאשׁוֹנָה, וְאֶחָד עַל הָאַחֲרוֹנָה, וּבִגְלַל זֶה אָז יָשִׁיר מֹשֶׁה. אָז שָׁר לֹא נֶאֱמַר, אֶלָּא אָז יָשִׁיר.</p>\n<p>עָשִׂירִי בַּתְּפִלָּה, וְזוֹ שְׁכִינָה, וְעָלֶיהָ נֶאֱמַר (תהלים יז) תְּפִלָּה לְדָוִד שִׁמְעָה ה' צֶדֶק. וְדָוִד בְּרוּחַ הַקֹּדֶשׁ אָמַר בְּאַחֲרִית הַיָּמִים שֶׁל הַגָּלוּת, אָמַר עַל יִשְׂרָאֵל (שם) בָּחַנְתָּ לִבִּי פָּקַדְתָּ לַּיְלָה, וְאֵין לַיְלָה אֶלָּא גָּלוּת, וּמַה שֶּׁאָמַר אִיּוֹב הַכֹּל הָיָה מָשָׁל עַל יִשְׂרָאֵל שֶׁאָמַר כָּלָה עָנָן וַיֵּלַךְ, וְהַשָּׁטָן רָצָה לְקַטְרֵג לוֹ, וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִיּוֹב לֹא בְדַעַת יְדַבֵּר. אַף בְּיַעֲקֹב כָּךְ, בִּגְלַל שֶׁרָאָה בְּרוּחַ קָדְשׁוֹ אֶת דּחַק הַגָּלוּת: ע\"כ.</p>"],[9522012678,"<p>זֶרַע אַבְרָהָם אֹהֲבִי. אֵין מִי שֶׁעוֹמֵד לִפְנֵי שַׁעַר הַתְּפִלָּה, וְעָלָיו נֶאֱמַר (שם קכז) לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אֹיְבִים בַּשָּׁעַר, שֶׁהוּא שַׁעַר הַמֶּלֶךְ, בִּגְלַל שֶׁתְּפִלָּה הִיא מִצְוָה, וְזוֹ שְׁכִינָה, וְתוֹרָה זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא צָרִיךְ בֵּינֵיהֶם הַפְסָקָה, וְצָרִיךְ לְהַעֲלוֹת תּוֹרָה וּמִצְוָה בְּיִרְאָה וְאַהֲבָה, שֶׁכָּל מִצְווֹת עֲשֵׂה וְלֹא תַעֲשֶׂה תְּלוּיוֹת מִשֵּׁם יְהֹוָ\"ה, כְּמוֹ שֶׁבֵּאַרְנוּ סוֹד זֶה שְּׁמִי עִם י\"ה - שס\"ה מִצְווֹת לֹא תַעֲשֶׂה, וְזֶה זִכְרִי עִם ו\"ה - רמ\"ח מִצְווֹת עֲשֵׂה,</p>\n<p>וַהֲרֵי כָּאן מָאתַיִם וּשְׁמוֹנָה וְאַרְבָּעִים, וּשְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁשִּׁים, וְהֵן מָאתַיִם וּשְׁמוֹנֶה וְאַרְבָּעִים תֵּבוֹת שֶׁבִּקְרִיאַת שְׁמַע, וְנִתְּנוּ מֵאַהֲבָה וְיִרְאָה שֶׁל אוֹת ה', וּמִשּׁוּם כָּךְ תִּקְּנוּ הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה, וְהֵם כְּלוּלִים בְּאַבְרָהָם שֶׁנֶּאֱמַר בּוֹ (ישעיה מא) זֶרַע אַבְרָהָם אֹהֲבִי.</p>\n<p>תְּפִלִּין הֵן עֹז שֶׁנִּתְּנוּ מִיִּרְאָה שֶׁהִיא לִשְׂמֹאל, וְזֶה פַּחַד יִצְחָק, שֶׁשָּׁם כָּל הַמְקַטְרְגִים עוֹלִים לִתְבֹּעַ כָּל הַדִּינִים, וְלָכֵן וּבִזְרוֹעַ עֻזּוֹ - זֶה תְּפִלִּין, י\"ה בְּיִרְאָה, ו\"ה בְּאַהֲבָה. זֶהוּ שֶׁכָּתוּב (תהלים לא) אֶהֱבוּ אֶת ה' כָּל חֲסִידָיו. בּא רְאֵה, יְהֹוָ\"ה כּוֹלֵל הַכֹּל, וְלָכֵן נֶאֱמַר בְּיַעֲקֹב וְהִנֵּה יְהֹוָ\"ה נִצָּב עָלָיו, שֶׁהוּא עַמּוּד הָאֶמְצָעִי לְאַחַר שֶׁהוּקַם. (כתוב בדפוס, עד בדמות של רבונו ודאי)</p>\n<p>שֶׁכַּאֲשֶׁר תְּפִלָּתוֹ עוֹלָה לְמַעְלָה, הַכָּרוֹז יוֹצֵא מִן הָרְקִיעִים וְיֹאמַר הָבוּ כָבוֹד לִדְיוֹקַן הַמֶּלֶךְ, וְאֵין שַׁעַר שֶׁעוֹמֵד לִפְנֵי הַתְּפִלָּה הַזּוֹ. אֲדנָי שְׂפָתַי תִּפְתָּח - לְהוֹצִיא מָזוֹן לַבָּנִים הַקְּדוֹשִׁים, שֶׁבַּהֵיכָל הַזֶּה שָׁם הַמָּזוֹן.</p>\n<p>בָּנִים חַיִּים וּמְזוֹנוֹת מִצַּד עַמּוּד הָאֶמְצָעִי, שֶׁהוּא בְּנִי בְכֹרִי יִשְׂרָאֵל, וְהוּא עֵץ הַחַיִּים שֶׁיּוֹצֵא מֵהַחַיִּים שֶׁלְּמַעְלָה, וְהוּא הָעֵץ שֶׁבּוֹ מָזוֹן לְכֻלָּם.</p>\n<p>וּבְנֵי הַשְּׁכִינָה הֵם יִשְׂרָאֵל לְמַטָּה, הַחַיִּים שֶׁלָּהּ תּוֹרָה, הַמָּזוֹן שֶׁלָּהּ תְּפִלָּה, שֶׁחֲשׁוּבָה כְּקָרְבָּן, וּבַגָּלוּת נֶאֱמַר אֵצֶל יִשְׂרָאֵל הָבָה לִּי בָנִים, וּשְׁכִינָה הִיא קָרְבָּן לַקָּדוֹשׁ-בָּרוּךְ- הוּא שֶׁמְּקַבֵּל אוֹתָהּ בְּיָמִין וּשְׂמֹאל וְגוּף, וְיִחוּדוֹ עִמָּהּ בְּצַדִּיק, שֶׁהוּא אוֹת תְּפִלִּין וְשַׁבָּת וְיָמִים טוֹבִים.</p>\n<p>וְיִשִׁ לִשְׁאֹל, לָמָּה מִתְפַּלְלִים אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכַמָּה דְרָגוֹת? לִפְעָמִים מִתְפַּלְלִים אֵלָיו בִּסְפִירָה יְדוּעָה וּבְמִדָּה יְדוּעָה, לִפְעָמִים תְּפִלָּה לְיָמִין - זֶהוּ שֶׁנֶּאֱמַר הָרוֹצֶה לְהַחְכִּים יַדְרִים, לִפְעָמִים לִשְׂמֹאל - זֶהוּ שֶׁנֶּאֱמַר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, לִפְעָמִים שֶׁל אָב וָאֵם הֵם לְיָמִין וְלִשְׂמֹאל, וְלִפְעָמִים לָעַמּוּד הָאֶמְצָעִי, לִפְעָמִים לְצַדִּיק, כָּל תְּפִלָּה עוֹלָה לְדַרְגָּה יְדוּעָה. אֶלָּא וַדַּאי יְהֹוָ\"ה הוּא בְּכָל סְפִירָה וּסְפִירָה, וּתְפִלָּה הִיא שְׁכִינָה.</p>\n<p>בִּזְמַן שֶׁמְּבַקֵּשׁ לְרַחֵם עַל הָעוֹלָם עוֹלָה בְּיָמִין, וּבִזְמַן שֶׁמְּבַקֵּשׁ לַעֲשׂוֹת דִּין בָּעוֹלָם עוֹלָה בִּשְׂמֹאל, וְהַכֹּל אֶל יְהֹוָ\"ה שֶׁהוּא בְּכָל מָקוֹם, וְלָכֵן זֹּאת תּוֹרַת הָעֹלָה, עוֹלָה לַה', וְזוֹ תְּפִלָּה שֶׁהִיא שְׁכִינָה קָרְבָּן לַה', וְזוֹ תְּפִלָּה שֶׁהִיא קָרְבָּנוֹ, וּכְשֶׁעוֹלָה אֵלָיו, צָרִיךְ לְהַכְלִיל עִמָּהּ אֶת כָּל הַסְּפִירוֹת, שֶׁאֵין קְדֻשָּׁה פָּחוֹת מֵעֲשָׂרָה: ע\"כ.</p>"],[9522012679,"<p>הַצַדִּיק אָבָד - כָּל זְמַן שֶׁלֹּא יָבֹא הַשֶּׁפַע אָבַד, וְעָלָיו נֶאֱמַר (ישעיה יט) וְנָהָר יֶחֱרַב וְיָבֵשׁ. וּבְעֵת הַבְּרָכָה - (תהלים ה) כִּי אַתָּה תְבָרֵךְ צַדִּיק, בְּרָכוֹת לְרֹאשׁ צַדִּיק: ע\"כ.</p>"],[9522012680,"<p>לָמַדְנוּ, עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים, וּכְשֶׁיֵּשׁ צַדִּיקִים - מִתְגַּבֵּר, וְאִם לָאו - מִתְחַלֵּשׁ, וְהוּא סוֹבֵל כָּל הָעוֹלָם, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְאִם חַלָּשׁ, לֹא יוּכַל לְהִתְקַיֵּם הָעוֹלָם: ע\"כ.</p>"],[9522012681,"<p>וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת. לָמַדְנוּ מִכָּאן, שֶׁהָאֲחֵרִים לֹא הָיוּ בַּדְּמוּת שֶׁלּוֹ, וְזֶה בִּדְמוּתוֹ כְּצַלְמוֹ נַעֲשָׂה, בְּתִקּוּן הַגּוּף וּבְתִקּוּן הַנֶּפֶשׁ, בְּדֶרֶךְ יָשָׁר כָּרָאוּי. בֹּא רְאֵה, הַנָּחָשׁ הִטִּיל זֻהֲמָה בְּחַוָּה, וְאוֹתָה זֻהֲמָה הָיְתָה מְכַשְׁכֶּשֶׁת בְּמֵעֶיהָ וְלֹא יָכְלָה לְהִצְטַיֵּר,</p>\n<p>מִשּׁוּם שֶׁעַד שֶׁלֹּא חָטָא אָדָם, הָיוּ אוֹתִיּוֹת הָא\"ב מְתֻקָּנִים בּוֹ וּמִצְטַיְּרִים בּוֹ בָּעוֹלָם הַזֶּה, עַד שֶׁהִגִּיעוּ לָאוֹת כָּ\"ף, נִתְקְנוּ זָכָר וּנְקֵבָה בַּחֲבִיבוּת בַּגַּן, וּמַלְאָכִים עֶלְיוֹנִים לִפְנֵיהֶם. מִיָּד הֵרַע לְסמא\"ל בָּרָקִיעַ, וְיָרַד וְרָכַב עַל נָחָשׁ חָזָק וְנִרְאָה לְפָנָיו. מִיָּד הִתְעָרְבוּ הָאוֹתִיּוֹת,</p>\n<p>וְאָז הִתְחַבֵּר סמא\"ל עִם אוֹתוֹ הַנָּחָשׁ וְנַעֲשׂוּ אֶחָד, וְלָקְחוּ אוֹתִיּוֹת, וְעָשׂוּ מִשָּׁם וָהָלְאָה אֻמָּנוּת רָעָה בְּאוֹתִיּוֹת צ\"ד צי\"ד, וְהַיְנוּ צ\"ץ, וְצָדוּ אוֹתָם בְּפִתּוּי רַע, וְעָשׂוּ אֻמָּנוּת יְתֵרָה בְּאוֹתִיּוֹת ק\"ר, אֻמָּנוּת שֶׁל שֶׁקֶר, מִשּׁוּם שֶׁחָזְרוּ לַהֲפֹךְ אוֹתִיּוֹת בְּאֻמָּנוּת רָעָה. קוֹ\"ף, שֶׁלֹּא יָכוֹל לַעֲמֹד, שֶׁאֵין לוֹ רַגְלַיִם. קוֹף לִפְנֵי בְּנֵי אָדָם אֵין לוֹ קִיּוּם. רֵי\"שׁ, רַע אֵלּוּ הִתְהַפְּכוּ בְּאֻמָּנוּת רָעָה עַד שֶׁנָּפְלוּ אָדָם וְאִשְׁתּוֹ,</p>\n<p>וּבָאוֹתִיּוֹת הַלָּלוּ ק\"ר הוֹלִידוּ בָנִים וְלֹא הָיוּ בְּקִיּוּם בִּשְׁבִיל זֻהֲמַת הַנָּחָשׁ שֶׁנִּשְׁאֲבָה בְּחַוָּה, מֵאוֹתָהּ זֻהֲמָה מַמָּשׁ נוֹלַד קַיִן, וְלָכֵן נִמְצָא הַהֶרֶג, מִשּׁוּם שֶׁאֻמָּנוּת הַנָּחָשׁ הִיא הֶרֶג, וְהִתִעַכְּבוּ הָאוֹתִיּוֹת עַד כָּאן.</p>\n<p>בְּשָׁעָֹה שֶׁאָדָם שָׁב בִּתְשׁוּבָה וְחָזַר כְּמוֹ קֹדֶם לְשַׁמֵּשׁ עִם נְקֵבָתוֹ, מַה כָּתוּב? וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, זֶה הָיָה מִתִּקּוּן שֶׁל רוּחַ וְגוּף כָּרָאוּי, וְאָז כָּתוּב (קהלת ח) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, וְחָזְרוּ הָאוֹתִיּוֹת בַּהַתְחָלָה שֶׁל שִׁי\"ן וְתָי\"ו, שֶׁכָּתוּב (בראשית ד) כִּי 'שָׁת' לִי אֱלֹהִים זֶרַע אַחֵר תַּחַת הֶבֶל. שֵׁת הוּא בְּצֶלֶם וּדְמוּת, שֶׁהָרִאשׁוֹנִים לֹא כָּךְ, וּמִכָּאן נִבְנָה הָעוֹלָם בְּגָוֶן אַחֵר שֶׁל אַלְפָא בֵּיתָא. קֵינָן וּמַהֲלַלְאֵל יֶרֶד,</p>\n<p>נוֹסַף לְתַקֵּן סִדּוּר הָעוֹלָם בְּשִׁבְעָה קְשָׁרִים. שֶׁבַע אֲרָצוֹת הֵן זוֹ לְמַעְלָה מִזּוֹ, כְּמוֹ שֶׁאוֹתָם שִׁבְעָה רְקִיעִים זֶה לְמַעְלָה מִזֶּה, וְהֵם: אֶרֶץ, אֲדָמָה, אַרְקָא, גֵּיא, נְשִׁיָּה, צִיָּה, תֵּבֵל. תֵּבֵל הִיא לְמַעְלָה מִכֻּלָּם, שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק.</p>\n<p>כְּשֶׁיָּצָא אָדָם מִגַּן עֵדֶן וְגֹרַשׁ מִשָּׁם, הוּא נִזְרַק לְאוֹתָהּ שֶׁנִּקְרֵאת אֶרֶץ, וְהוּא מָקוֹם חָשׁוּךְ שֶׁאֵין שָׁם אוֹר כְּלָל וְלֹא מְשַׁמֵּשׁ כְּלוּם. כֵּיוָן שֶׁאָדָם נִכְנַס לְשָׁם, הוּא פָּחַד פַּחַד גָּדוֹל, וְלַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת הָיְתָה לוֹהֶטֶת בְּכָל הַצְּדָדִים בְּכָל הָאָרֶץ.</p>\n<p>כֵּיוָן שֶׁיָּצְאָה שַׁבָּת וְהִרְהֵר תְּשׁוּבָה, הוֹצִיא אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֲדָמָה, שֶׁכָּתוּב (בראשית ג) לַעֲבֹד אֶת הָאֲדָמָה. בָּזֹאת יֵשׁ אוֹר שֶׁמֵּאִיר וּדְמֻיּוֹוֹת שֶׁל כּוֹכָבִים וּמַזָּלוֹת,</p>\n<p>וְשָׁם יוֹם, וְצִיּוּרִים שֶׁל בְּנֵי אָדָם עֶלְיוֹנִים, גְּבָרִים שֶׁיָּצְאוּ מֵאָדָם בְּמֵאָה וּשְׁלֹשִׁים הַשָּׁנִים שֶׁהָיָה מְשַׁמֵּשׁ עִם רוּחוֹת נְקֵבוֹת, וְהֵם תָּמִיד עֲצוּבִים, שֶׁאֵין בָּהֶם חֶדְוָה, וְאֵלֶּה מְשׁוֹטְטִים וְיוֹצְאִים לָעוֹלָם הַזֶּה וּמִתְהַפְּכִים לְצַד רַע, וְחוֹזְרִים לְשָׁם וּמִתְפַּלְלִים תְּפִלָּה, וּמִתְיַשְּׁבִים בִּמְקוֹמָם שָׁם, וְזוֹרְעִים זְרָעִים בָּרֵחַיִם וְאוֹכְלִים, וְאֵין שָׁם חִטִּים. וְלָא אֶחָד מִז' מִינֵי תְבוּאָה. בְּזְהִ הַמָּקוֹם נוֹלְדוּ קַיִן וְהֶבֶל,</p>\n<p>כֵּיוַן דְחָטָא קַיִן הוֹרִיד אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֲדָמָה, שֶׁכָּתוּב (שם ד) הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה, מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֲדָמָה. וְהָיִיתִי נָע וָנָד בָּאָרֶץ, מִשּׁוּם שֶׁשָּׁם נִדְחָה וְגֹרַשׁ. וְהָיָה כָל מֹצְאִי יַהַרְגֵנִי - אוֹתָהּ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת,</p>\n<p>וְהָיָה פּוֹחֵד, וְהִרְהֵר תְּשׁוּבָה, וְהֶעֱלָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַרְקָא, וְהָיָה שָׁם וְהוֹלִיד בָּנִים בְּאַרְקָא, וּבְאַרְקָא יֵשׁ אוֹר שֶׁמֵּאִיר מִתּוֹךְ הַשֶּׁמֶשׁ, וְזוֹרְעִים זְרָעִים וְנוֹטְעִים אִילָנוֹת, וְאֵין שָׁם חִטִּים וְלֹא מֵאוֹתָם שִׁבְעָה מִינֵי תְבוּאָה.</p>\n<p>כָּל אוֹתָם שֶׁשָּׁם הֵם מִתּוֹלְדוֹת קַיִן, וְהֵם עִם שְׁנֵי רָאשִׁים, מֵהֶם גְּבָרִים עֶלְיוֹנִים וּמֵהֶם גְּבָרִים קְטַנִּים, וְאֵין בָּהֶם דַּעַת שְׁלֵמָה כִּשְׁאָר בְּנֵי אָדָם שֶׁכָּאן. לִפְעָמִים הֵם צַדִּיקִים וְחוֹזְרִים לַצַּד הַטּוֹב, וְלִפְעָמִים חוֹזְרִים לַצַּד הָרָע, וּמוֹלִידִים וּמֵתִים כִּשְׁאָר בְּנֵי הָאָדָם.</p>\n<p>אָדָם הָיָה בַּאֲדָמָה (וארקא), עַד שֶׁהוֹלִיד שֵׁת, וּמִשָּׁם עָלָה לְמַעְלָה אַרְבַּע דְּרָגוֹת, וְעָלָה לַמָּקוֹם הַזֶּה שֶׁנִּקְרָא תֵּבֵל. וְתֵבֵל זוֹ הִיא הָעֶלְיוֹנָה שֶׁל כָּל הַדְּרָגוֹת. כֵּיוָן שֶׁעָלָה, עָלָה לִמְקוֹם בֵּית הַמִּקְדָּשׁ שֶׁנִּקְרָא בְּאוֹתָם שֵׁמוֹת שֶׁדִּיּוּרוֹ הָיָה בָּהֶם, אֶרֶץ אֲדָמָה כָּךְ נִקְרָא.</p>\n<p>דִּלֵּג אָדָם שְׁלֹשָׁה מְקוֹמוֹת - גֵּיא, נְשִׁיָּה, צִיָּה. גֵּיא הוּא אֲתַר וּמָקוֹם גָּדוֹל כְּמוֹ רֹחַב וְאֹרֶךְ הַגֵּיהִנֹּם. בְּגֵיא וּנְשִׁיָּה וְצִיָּה הִתְפַּזְּרוּ אוֹתָם שֶׁבָּנוּ מִגְדָּל וְהוֹלִידוּ שָׁם עַל שֶׁהִרְגִּיזוּ אֶת הַמֶּלֶךְ הָעֶלְיוֹן, לָכֵן זֶה קָרוֹב לָאֵשׁ הַדּוֹלֶקֶת. וְיִשִׁ בְּנֵי אָדָם נִכְבָּדִים בְּכָל עֹשֶׁר וְעַפְרוֹת זָהָב וַאֲבָנִים יְקָרוֹת. מִי שֶׁנִּכְנַס לְשָׁם וְהָיָה מִתֵּבֵל, בְּחֶמְדַּת אוֹתוֹ הָעֹשֶׁר נוֹתְנִין לוֹ, וְלִפְעָמִים עוֹלֶה לְמָקוֹם שֶׁנִּקְרָא נְשִׁיָּה, מִשּׁוּם שֶׁנִּשְׁכָּח שָׁם. יוֹרֵד לַגֵּיא הַזֶּה וְלֹא יוֹדֵעַ אֶת הַמָּקוֹם שֶׁהָיָה מִשָּׁם.</p>\n<p>גֵּיא הוּא בָּאֶמְצַע שֶׁל מַעְלָה וּמַטָּה, וְזֶה נִקְרָא גֵּיא בֶן הִנֹּם, וּרְצוּעָה אַחַת יוֹצֵאת מִשָּׁם לְמַעְלָה לַתֵּבֵל הַזֹּאת, וְנִקְרֵאת אַף כָּךְ גֵּיא בֶן הִנֹּם, וְשָׁם פֶּתַח הַגֵּיהִנֹּם. אוֹתָם בְּנֵי אָדָם שֶׁשָּׁם, כֻּלָּם יוֹדְעִים כְּשָׁפִים וְחָכְמוֹת נִכְבָּדוֹת, וְשָׁם זוֹרְעִים וְנוֹטְעִים עֵצִים, וְאֵין שָׁם לֹא חִטִּים וְלֹא אֶחָד מִשִּׁבְעַת הַמִּינִים.</p>\n<p>בַּנְּשִׁיָּה יֵשׁ בְּנֵי אָדָם כֻּלָּם קְטוּעִים קְטַנִּים, וְאֵין לָהֶם חֳטָמִים, פְּרָט לִשְׁנֵי נְקָבִים שֶׁיּוֹצֵאת בָּהֶם רוּחַ, וְכָל מַה שֶּׁעוֹשִׂים מִיָּד שׁוֹכְחִים, וְעַל כָּךְ נִקְרֵאת נְשִׁיָּה, וְזוֹרְעִים וְנוֹטְעִים עֵצִים, וְאֵין שָׁם חִטִּים וְלֹא מִשִּׁבְעַת הַמִּינִים.</p>\n<p>צִיָּ\"ה הוּא מָקוֹם כִּשְׁמוֹ, יֵשׁ שָׁם יֹבֶשׁ שֶׁל הַכֹּל, וְשָׁם בְּנֵי אָדָם יָפִים לְמַרְאֶה, וּמִתּוֹךְ שֶׁהוּא צִיָּה, כְּשֶׁיּוֹדְעִים מָקוֹם שֶׁל מְקוֹר מַיִם נוֹבְעִים, נִכְנָסִים לְשָׁם, וְלִפְעָמִים שֶׁעוֹלִים מִתּוֹךְ הַמָּקוֹם שֶׁל הַמַּיִם וְעוֹלִים לַתֵּבֵל הַזּוֹ, וְהֵם בְּנֵי אֱמוּנָה יוֹתֵר מִבְּנֵי אָדָם אֲחֵרִים, וּבֵינֵיהֶם דִּיּוּרִים טוֹבִים וְעֹשֶׁר רַב, וְזוֹרְעִים מְעַט מִתּוֹךְ הַיֹּבֶשׁ שֶׁל שָׁם, וְנוֹטְעִים עֵצִים וְלֹא מַצְלִיחִים, וּתְשׁוּקָתָם לִבְנֵי אָדָם שֶׁל כָּאן,</p>\n<p>וּמִכֻּלָּם אֵין אוֹכְלֵי לֶחֶם - כְּמוֹ (רק) אֵלֶּה שֶׁכָּאן בַּתֵּבֵל, כָּאן מֵעַל כָּל אֵלֶּה תֵּבֵל, וְכָתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. כְּמוֹ שֶׁכָּל אֵלּוּ הָאֲרָצוֹת יֵשׁ בַּתֵּבֵל הַ את, וְכָל אֵלֶּה הַשֵּׁמוֹת יֵשׁ לָהֶם אַף כָּךְ, מִשּׁוּם שֶׁהוּא שְׁבִיעִי, יֵשׁ כָּאן כְּמוֹ שֶׁל אוֹתָם מְקוֹמוֹת תְּחוּמִים וּמְקוֹמוֹת כָּאן, וְנִקְרָא כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁאוֹתוֹ מָקוֹם שֶׁלְּמַטָּה, וְכָל אֵלֶּה בַּדִּיּוּרִים שֶׁל בְּנֵי אָדָם מְשֻׁנִּים אֵלֶּה מֵאֵלֶּה, שֶׁכָּתוּב (שם קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךְ: ע\"כ מההשמטות.</p>"],[9522012682,"<p>רַבִּי חִזְקִיָּה אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהִתְרַצָּה בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן לָהֶם תּוֹרָה הַקְּדוֹשָׁה, וְהִזְהִיר אוֹתָם וְנָתַן לָהֶם עֵצָה לְהִשָּׁמֵר מִמַּעְלָה וּמִמַּטָּה כְּדֵי שֶׁלֹּא יִשְׁלֹט בָּהֶם - רַק הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם יוֹדְעִים לִדְחוֹת מֵהֶם כָּל הַמְקַטְרְגִים וְכָל הָרוּחוֹת, כְּדֵי שֶׁיִּהְיוּ חֵלֶק גּוֹרָלוֹ וִירֻשָּׁתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>בֹּא רְאֵה, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם, וְכָל בְּנֵי הָעוֹלָם יוֹשְׁבִים בְּחֶשְׁבּוֹן, וְאֵין מִי שֶׁלֹּא נִכְנָס בְּחֶשְׁבּוֹן, וְסִפְרֵי חַיִּים וּמֵתִים נִפְתָּחִים בְּאוֹתוֹ יוֹם. וּבִגְלַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, נָתַן לָהֶם עֵצָה לְהִנָּצֵל מִכָּל הַקִּטְרוּגִים שֶׁל מַעְלָה שֶׁהֵם הִתְמַנּוּ, וְכֵן בְּכָל זְמַן שֶׁהַדִּין שׁוֹרֶה עַל הָעוֹלָם. בְּיוֹם זֶה מֻזְמָנִים יִשְׂרָאֵל לְעוֹרֵר עֲלֵיהֶם רַחֲמִים, וּבַמֶּה? בַּשּׁוֹפָר, שֶׁהַקּוֹל הַזֶּה שֶׁיּוֹצֵא עוֹלֶה לְמַעְלָה וּמְעוֹרֵר שׁוֹפָר הָעֶלְיוֹן, אָז מִתְעוֹרְרִים רַחֲמִים מִמְּקוֹמָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָם מִכִּסֵּא דִין וְיוֹשֵׁב בְּכִסֵּא רַחֲמִים וּמְרַחֵם עַל יִשְׂרָאֵל, וְלֹא נִתֶּנֶת רְשׁוּת לַמְקַטְרֵג.</p>\n<p>וְיִשְׂרָאֵל יוֹשְׁבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְשׁוּבָה וְתוֹקְעִים בַּשּׁוֹפָר (ומעוררים) וּמִתְעוֹרְרִים רַחֲמִים, שֶׁהֲרֵי אוֹתוֹ קוֹל שֶׁיּוֹצֵא הוּא הִתְעוֹרְרוּת הָרַחֲמִים, וְאָז הַמַּלְשִׁין לֹא יָכוֹל לַעֲמֹד לִפְנֵי כִּסֵּא הָרַחֲמִים, שֶׁהֲרֵי לֹא בָא מֵאוֹתוֹ צַד וְלֹא נִמְצָא קָטֵגוֹרְיָא.</p>\n<p>בְּיוֹם הַכִּפּוּרִים שֶׁהוּא חֲתִימַת הַדִּין, וְיִשְׂרָאֵל עוֹמְדִים בִּקְדֻשַּׁת רִבּוֹנָם, בְּאוֹתוֹ יוֹם, כְּדֵי שֶׁלֹּא יִקְרַב מַלְשִׁין לַמִּקְדָּשׁ, נוֹתְנִים לוֹ שָׂעִיר, שֶׁבָּא מִצַּד רוּחַ הַטֻּמְאָה וְהוּא טָמֵא, וְרוּחַ טֻמְאָה נֶהֱנֶה מִמֶּנּוּ. (והוא) הוּא מִתְעַסֵּק בּוֹ, וְלֹא מִתְקָרֵב לַמִּקְדָּשׁ לְטַמֵּא, וְאָז הַפָּנִים מְאִירוֹת, וְיִשְׂרָאֵל נִצּוֹלִים מִמֶּנּוּ.</p>\n<p>בִּזְמַן אַחֵר, כְּשֶׁרַבִּים חֲטָאֵי בְּנֵי הָאָדָם, הַמַּלְשִׁין הַזֶּה בִּשְׁעַת הַדִּין מִתְעוֹרֵר עַל חֲטָאֵי הָעוֹלָם, אָז הוּא בָּא, וְנִמְצֵאת הַלְשָׁנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַמִּקְדָּשׁ נִטְמָא, וְכָל הַפָּנִים עֲצוּבוֹת וְנִמְצָא הַדִּין, וְעַל זֶה (בראשית ו) קֵץ כָּל בָּשָׂר בָּא לְפָנַי, בָּא לְפָנַי וַדַּאי, לִתְבּעַ חֲטָאֵי הָעוֹלָם מִשּׁוּם שֶׁהֵם גָּרְמוּ: (ע\"כ מההשמטות).</p>"],[9522012683,"<p>צִוָּה ה'. אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי יִשְׂרָאֵל שֶׁנִּתְּנָה לָהֶם תּוֹרָה קְדוֹשָׁה וְהֵם מִשְׁתַּדְּלִים בָּהּ יָמִים וְלֵילוֹת. בּא רְאֵה, שֶׁהֲרֵי מַשְׁמָע שֶׁלּוּלֵא שֶׁנִּמְצָא נֹחַ עִם הַתֵּבָה בְּהִתְחַבְּרוּת כְּאֶחָד, לֹא הָיָה נִצָּל, (ולכן) נִסְתַּר מִן הָעַיִן בְּתוֹךְ הַתֵּבָה. קָמוּ וְהָלְכוּ. אָמַר אוֹתוֹ יְהוּדִי, כָּתוּב עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר, לְךְ וּלְעַצְמְךְ, כְּדֵי לְהִתְחַבֵּר עִמָּהּ וּלְהִנָּצֵל בָּהּ. מַה כָּתוּב? וַיַּעַשׂ נֹחַ כְּכָל אֲשֶׁר צִוָּהוּ וְגוֹמֵר.</p>"],[9522012684,"<p>מַה הֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ כְּשֶׁיָּצָא מֵהַתֵּבָה וְרָאָה אֶת הָעוֹלָם חָרֵב, וְהִתְחִיל לִבְכּוֹת לְפָנָיו וְאָמַר: רִבּוֹנוֹ שֶׁל עוֹלָם, נִקְרֵאתָ רַחוּם, הָיָה לְךְ לְרַחֵם עַל בְּרִיּוֹתֶיךְ וְכוּ'? הֱשִׁיבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר: רוֹעֶה שׁוֹטֶה, עַכְשָׁו אַתָּה אוֹמֵר אֶת זֶה? לָמָּה לֹא אָמַרְתָּ בְּשָׁעָה שֶׁאָמַרְתִּי לְךְ כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי וְגוֹ', וְאַחַר הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם, וְאַחַר כָּךְ עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר? כָּל זֶה הִתְעַכַּבְתִּי וְאָמַרְתִּי לְךְ כְּדֵי שֶׁתְּבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם, וּמֵאָז שֶׁשָּׁמַעְתָּ שֶׁתִּנָּצֵל בַּתֵּבָה, לֹא נִכְנַס בְּלִבְּךְ לְבַקֵּשׁ רַחֲמִים עַל יִשּׁוּב הָעוֹלָם, וְעָשִׂיתָ תֵּבָה וְנִצַּלְתָּ, וְכָעֵת, אַחַר שֶׁנֶּאֱבַד הָעוֹלָם, פָּתַחְתָּ פִּיךְ לוֹמַר לְפָנַי בַּקָּשׁוֹת וְתַחֲנוּנִים!? כֵּיוָן שֶׁרָאָה נֹחַ כָּךְ, הִקְרִיב קָרְבָּנוֹת וְעוֹלוֹת, שֶׁכָּתוּב (בראשית ח) וַיִּקַּח מִכֹּל הַבְּהֵמָה הַטְּהֹרָה וּמִכֹּל הָעוֹף הַטָּהוֹר וְגוֹמֵר.</p>\n<p>אָמַר רַבִּי יוֹחָנָן, בֹּא רְאֵה מַה בֵּין צַדִּיקִים שֶׁהָיוּ לָהֶם לְיִשְׂרָאֵל אַחַר נֹחַ וּבֵין נֹחַ. נֹחַ לֹא הֵגֵן עַל דּוֹרוֹ וְלֹא הִתְפַּלֵּל עֲלֵיהֶם כְּאַבְרָהָם, שֶׁכֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם (שם יח) זַעֲקַת סְדֹם וַעֲמֹרָה כִּי רָבָּה - מִיָּד נִגַּשׁ אַבְרָהָם וַיֹּאמַר וְגוֹמֵר, וְהִרְבָּה תַחֲנוּנִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁשָּׁאַל שֶׁאִם יִמְצָא עֲשָׂרָה צַדִּיקִים, שֶׁיְּכַפֵּר לְכָל הַמָּקוֹם בַּעֲבוּרָם, וְחָשַׁב אַבְרָהָם שֶׁהָיוּ בָּעִיר עִם לוֹט וְאִשְׁתּוֹ וּבְנוֹתָיו עֲשָׂרָה צַדִּיקִים, וּלְפִיכָךְ לֹא הִתְפַּלֵּל.</p>\n<p>אַחַר כָּךְ בָּא מֹשֶׁה וְהִתְפַּלֵּל וְהֵגֵן עַל דּוֹרוֹ. כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לב) סָרוּ מַהֵר מִן הַדֶּרֶךְ - מִיָּד עָמַד מֹשֶׁה בִּתְפִלָּה, וַיְחַל מֹשֶׁה וְגוֹמֵר, עַד שֶׁאֲחָזַתּוּ חַלְחָלָה. רַבּוֹתֵינוּ אָמְרוּ, לֹא הִנִּיחַ מֹשֶׁה לַקָּדוֹשׁ-בָּרוּךְ-הוּא עַד שֶׁנָּתַן נַפְשׁוֹ עֲלֵיהֶם מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא, שֶׁכָּתוּב (שם) וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. אָמַר רַבִּי יוֹסֵי, מִכָּאן (תהלים קו) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו.</p>\n<p>אָמַר רַבִּי יְהוֹשֻׁעַ, מָה רָאָה נֹחַ שֶׁלֹּא בִקֵּשׁ רַחֲמִים עַל דּוֹרוֹ? אָמַר בְּלִבּוֹ, אוּלַי לֹא אֲמַלֵּט, שֶׁכָּתוּב (בראשית ז) כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה, כְּלוֹמַר לְפִי הַדּוֹר, וּלְפִיכָךְ לֹא בִקֵּשׁ רַחֲמִים עֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר, אֲפִלּוּ כָּךְ הָיָה לוֹ לְבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם, מִשּׁוּם שֶׁנּוֹחַ לַקָּדוֹשׁ-בָּרוּךְ- הוּא מִי שֶׁיֹּאמַר טוֹב עַל בָּנָיו, מִנַּיִן לָנוּ? מִגִּדְעוֹן בֶּן יוֹאָשׁ, שֶׁלֹּא הָיָה צַדִּיק וְלֹא בֶּן צַדִּיק, וּמִשּׁוּם שֶׁאָמַר טוֹב עַל יִשְׂרָאֵל, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (שופטים ו) לֵךְ בְּכֹחֲךְ זֶה וְהוֹשַׁעְתָּ אֶת יִשְׂרָאֵל מִיַּד מִדְיָן. מַה זֶּה בְּכֹחֲךְ זֶה? הַטּוֹב שֶׁאָמַרְתָּ עַל בָּנַי. ע\"כ מההשמטות.</p>"],[9522012685,"<p>עוֹד פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, (שיר השירים א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים, לְרֵיחַ מִי? אֶלָּא יֵשׁ רֵיחַ וְיֵשׁ רֵיחַ, רֵיחַ הַקָּרְבָּן וְרֵיחַ הַקְּטֹרֶת. רֵיחַ הַקָּרְבָּן מַקְרִיב וּמְיַחֵד כָּל אוֹתָם שְׁבָטִים שֶׁל הֵיכַל בֵּית דָּוִד, וְרֵיחַ הַקְּטֹרֶת מַקְרִיב וּמְיַחֵד וּמֵאִיר אוֹתָם נִרוֹת עֶלְיוֹנִים נַהֲרוֹת אֲפַרְסְמוֹן זַךְ.</p>\n<p>וְעַל זֶה הָיוּ שְׁנֵי מִזְבְּחוֹת - מִזְבַּח הַקְּטֹרֶת וּמִזְבַּח הָעוֹלָה. מִזְבַּח הַקְּטֹרֶת הוּא פְּנִימִי, מִזְבַּח הָעוֹלָה הוּא חִיצוֹנִי. רֵיחַ מִזְבַּח הָעוֹלָה מַתְקִין לְהָאִיר מְנוֹרוֹת תַּחְתּוֹנוֹת, רֵיחַ מִזְבַּח הַקְּטֹרֶת מַתְקִין לְהָאִיר מְנוֹרוֹת עֶלְיוֹנוֹת. וְעַל זֶה לְרֵיחַ שְׁמָנֶיךְ טוֹבִים, לָרֵיחַ שֶׁל אוֹתָהּ הַקְּטֹרֶת, שְׁמָנֶיךְ טוֹבִים.</p>\n<p>בֹּא רְאֵה שְׁתֵּי מִזְבֶּחוֹת הֵן מִזְבֵּחַ פְּנִימִי לְמַעְלָה מִזְבֵּחַ חִיצוֹן לְמַטָּה. מִזְבֵּחַ הַפְּנִימִי הוּא שָׁלֵם. וְזֶהוּ שֶׁכָּתוּב הַמִּזְבֵּחָה, בְּתוֹסֶפֶת הֵ\"א, וְכָךְ הוּא בְּכָל מָקוֹם. וּמִזְבֵּחַ הַחִיצוֹן הוּא חָסֵר הֵ\"א, כְּמוֹ נַעֲרָה, נַעַר חָסֵר ה'.</p>\n<p>נִמְצָא שֶׁמֵּהִתְעוֹרְרוּת הַמִּזְבֵּחַ (החיצון) שֶׁל מַטָּה מִתְעוֹרֵר מִזְבֵּחַ הַפְּנִימִי שֶׁל מַעְלָה, וּבַמֶּה מִתְעוֹרֵר? בְּרֵיחַ (שמהתעוררות מזבח החיצון של מטה מתעורר מזבח החיצון של מעלה, ובמה מתעורר? בריח הקרבנות, ובריח הקטרת של מזבח הפנימי של מטה מתעורר מזבח הפנימי של מעלה, ובמה מתעורר? בריח הקטרת, ועל זה) הַקְּטֹרֶת שֶׁל מַטָּה. וְעַל זִה (שם) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים, אוֹתָם נִרוֹת מְאִירִים נוֹצְצִים. כָּתוּב כָּאן טוֹבִים, וְכָתוּב שָׁם (בראשית א) וַיַּרְא אֶלֹהִים אֶת הָאוֹר כִּי טוֹב: ע\"כ מההשמטות.</p>"],[9522012686,"<p>וַיְהִי כְּבוֹא אַבְרָם מִצְרָיְמָה (שם יב). כְּבוֹאָם הָיָה צָרִיךְ (לכתב) ! וְשָׂרָה הֵיכָן הָיְתָה? אֶלָּא אַבְרָהָם הִכְנִיסָהּ לְתֵבָה וְסָגַר עָלֶיהָ. כֵּיוָן שֶׁהִגִּיעַ לְמִצְרַיִם, אָמְרוּ לוֹ: שַׁלֵּם מֶכֶס. אָמַר: אֲנִי אֶתֵּן מֶכֶס. אָמְרוּ לוֹ: כֵּלִים אַתָּה טוֹעֵן. אָמַר לָהֶם: אֶתֵּן מֶכֶס שֶׁל כֵּלִים. אָמְרוּ לוֹ: בִּגְדֵי מֵשִּׁי מְשׁוּבָּח אַתָּה טוֹעֵן. אָמַר לָהֶם: אֶתֵּן מֶכֶס שֶׁל בִּגְדֵי מֵשִּׁי מְשׁוּבָּח. אָמְרוּ לוֹ: מַרְגָּלִיּוֹת אַתָּה טוֹעֵן. אָמַר לָהֶם: אֶתֵּן מֶכֶס שֶׁל מַרְגָּלִיּוֹת. אָמְרוּ לוֹ: אִי אֶפְשָׁר אֶלָּא לִפְתֹּחַ אֶת הַתֵּבָה וְנִרְאֶה מַה בְּתוֹכָהּ. כֵּיוָן שֶׁפָּתְחוּ אֶת הַתֵּבָה, הֵאִירָה אֶרֶץ מִצְרַיִם מֵהָאוֹר שֶׁלָּהּ, זֶהוּ שֶׁכָּתוּב (שם) וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה וְגוֹמֵר. אָמַר רַבִּי יְהוּדָה, וַיְהִי כְּבוֹאָם מִצְרַיְמָה הָיָה לוֹ לוֹמַר! אֶלָּא בַּתֵּבָה וְכוּ':</p>"],[9522012687,"<p>חֲמִשִּׁים הֵם כְּנֶגֶד חֲמִשִּׁים שַׁעֲרֵי בִינָה, וְהֵם רְאוּיִים לְהַצִּיל כָּל הָעוֹלָם בְּצִדְקָתָם, וַה' הוֹדָה לִדְבָרֶיהָ. וּכְשֶׁרָאֲתָה שֶׁלֹּא מָצְאָה, אָמְרָה (שם יח) אוּלַי יַחְסְרוּן חֲמִשִּׁים הַצַּדִּיקִים חֲמִשָּׁה, כְּלוֹמַר, אוּלַי יֵשׁ בָּהֶם בְּנֵי אָדָם שֶׁעָסְקוּ בִּידִיעַת שְׁמֶךְ, שֶׁהוּא הַשֵּׁם בְּמִלּוּאוֹ, שֶׁהוּא חֲמִשָּׁה וְאַרְבָּעִים, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, כְּמִסְפַּר אָדָם, שֶׁנֶּאֱמַר (דברים י) וְעַתָּה יִשְׂרָאֵל מָה ה' אֱלֹהֶיךְ שֹׁאֵל. וּכְשֶׁלֹּא מָצְאָה, חוֹזֶרֶת לוֹמַר אוּלַי יִמָּצְאוּן שָׁם אַרְבָּעִים.</p>"],[9522012688,"<p>עוֹד פּוֹתַחַת וְאוֹמֶרֶת, רִבּוֹנוֹ שֶׁל עוֹלָם, אוּלַי יִמָּצְאוּן שָׁם שְׁלֹשִׁים, כְּלוֹמַר, אוּלַי יֵשׁ בֵּינֵיהֶם צַדִּיקִים שֶׁעָסְקוּ וְהִשִּׂיגוּ אוֹתָם הַשְּׁלֹשִׁים מַעֲלוֹת הָרְמוּזוֹת בִּנְבוּאַת יְחֶזְקֵאל בַּפָּסוּק וַיְהִי בִּשְׁלֹשִׁים (שנה), וְהֵם כְּלוּלִים בִּשְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה, שֶׁהֵם עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת וְעֶשֶׂר סְפִירוֹת,</p>\n<p>וְכֵן אוּלַי יֵשׁ בֵּינֵיהֶם אֲנָשִׁים צַדִּיקִים יְחִידֵי סְגֻלָּה הַמְיַחֲדִים שְׁתֵּי פְעָמִים בַּיּוֹם בְּפָסוּק שְׁמַע יִשְׂרָאֵל, שֶׁבָּהּ כְּלוּלִים עֶשֶׂר סְפִירוֹת בְּמִלַּת אֶחָד. הָאָלֶ\"ף עִם הַחֵי\"ת הֵם תִּשְׁעָה, וְהַמִּלָּה א' הֲרֵי עֲשָׂרָה, וְהַד' אָמַר דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם עָלֶיהָ (תהלים קיח) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבוֹאוּ בוֹ, וְדָלֶ\"ת מִלְּשׁוֹן שַׁעַר, וּשְׁתֵּי פְעָמִים בַּיּוֹם הֲרֵי עֶשְׂרִים.</p>\n<p>וּכְשֶׁאֵינָהּ מוֹצְאָה, חוֹזֶרֶת וּפוֹתַחַת וְאוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה, כְּלוֹמַר, אוּלַי יִמָּצֵא בֵינֵיהֶם מִי שֶׁעוֹסֵק בַּעֲשָׂרָה מַאֲמָרוֹת וּבַעֲשֶׂרֶת הַדִּבְּרוֹת בְּכָל יוֹם. וְכֵן אוּלַי יִמָּצְאוּן בֵּינֵיהֶם עֲשָׂרָה שֶׁמַּקְדִּימִים לְבֵית הַכְּנֶסֶת, שֶׁהֲרֵי שָׁנִינוּ, כָּל (הנמצא) הַנִּמְנֶה מֵעֲשָׂרָה רִאשׁוֹנִים לְבֵית הַכְּנֶסֶת, נוֹטֵל שָׂכָר כְּנֶגֶד כֻּלָּם שֶׁבָּאִים אַחֲרָיו. מַה כָּתוּב? לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה.</p>\n<p>כָּל זֶה יֵשׁ לְנִשְׁמַת הַצַּדִּיק לְלַמֵּד סָנֵגוֹרְיָה וּזְכוּת עַל הָרְשָׁעִים, לְהַשְׁקִיט הָאַף וְהַחֵמָה. וְכֵיוָן שֶׁלֹּא מָצְאָה שׁוּם זְכוּת לְלַמֵּד, מַה כָּתוּב? (בראשית יח) וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקֹמוֹ. מַהוּ לִמְקוֹמוֹ? לִמְקוֹם מַעֲלָתוֹ הַיְדוּעָה, וְאָז נִסְתַּלֵּק הַדַּיָּן וְנִסְתַּלֵּק הַסָּנֵגוֹר, וְהַקָּטֵגוֹר מְקַטְרֵג. וְזֶהוּ (שם יט) וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה בָּעֶרֶב וְגוֹמֵר.</p>\n<p>וְלוֹט הוּא שָׂטָן, הוּא יֵצֶר הָרָע, יוֹשֵׁב בְּשַׁעַר סְדם כִּי שָׁם בֵּיתוֹ, שֶׁכָּתוּב לַפֶּתַח חַטָּאת רֹבֵץ, וּמִתְחַבֵּר עִם בְּנֵי אָדָם וּמַטְעֶה אוֹתָם עַד שֶׁמּוֹרִידָם לִבְאֵר שַׁחַת, וְהוּא גַּם כֵּן עִמָּהֶם נִדּוֹן עַל שֶׁהִטְעָה אוֹתָם, וְיוֹרֵד עַד צַעֲרָהּ שֶׁל גֵּיהִנֹּם, וְזֶהוּ (שם) הִנֵּה נָא הָעִיר הַזֹּאת קְרֹבָה לָנוּס שָׁמָּה. הָרוֹצֵחַ הוּא עֵשָׂו שׁוֹפֵךְ דָּמִים, וְהוּא מִצְעָר. וְאַף עַל פִּי שֶׁיּוֹרֵד וְנִדּוֹן שָׁם עַל כָּל זֶה, תַּאֲוָתוֹ וְחִשְׁקוֹ לַחֲזר וּלְהַטְעוֹת לַאֲחֵרִים, וְזֶהוּ (שם) וַיַּעַל לוֹט מִצּוֹעַר: ע\"כ מההשמטות.</p>"],[9522012689,"<p>פַּעַם אַחַת יָצָא רַבִּי שִׁמְעוֹן וְרָאָה (וראה) שֶׁהָעוֹלָם חָשׁוּךְ וְאָפֵל וְנִסְתָּם אוֹרוֹ. אָמַר לוֹ רַבִּי אֶלְעָזָר, בּא רְאֵה מָה רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בָּעוֹלָם. הָלְכוּ וּמָצְאוּ מַלְאָךְ אֶחָד שֶׁדּוֹמֶה לְהַר גָּבוֹהַּ וּמוֹצִיא שְׁלֹשִׁים שַׁלְהָבוֹת מִפִּיו.</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, מָה אַתָּה רוֹצֶה לַעֲשׂוֹת? אָמַר לוֹ, רְצוֹנִי לְהַחֲרִיב אֶת הָעוֹלָם, מִשּׁוּם שֶׁלֹּא נִמְצָא שְׁלֹשִׁים צַדִּיקִים בַּדּוֹר, שֶׁכָּךְ גָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַבְרָהָם, שֶׁכָּתוּב (בראשית יח) הָיוֹ 'יִהְיֶה', בְּגִימַטְרִיָּא שְׁלֹשִׁים. אָמַר לוֹ רַבִּי שִׁמְעוֹן, בְּבַקָּשָׁה מִמְּךְ, לֵךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וֶאֱמֹר לוֹ, בַּר יוֹחַאי מָצוּי בָּאָרֶץ.</p>\n<p>הָלַךְ אוֹתוֹ מַלְאָךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לוֹ: רִבּוֹן הָעוֹלָם, גָּלוּי וְיָדוּעַ לְפָנֶיךְ מַה שֶּׁאָמַר לִי בַּר יוֹחַאי? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: לֵךְ תַּחֲרִיב אֶת הָעוֹלָם וְאַל תַּשְׁגִּיחַ בְּבַר יוֹחַאי.</p>\n<p>כְּשֶׁבָּא, רָאָה רַבִּי שִׁמְעוֹן אֶת הַמַּלְאָךְ. אָמַר לוֹ: אִם לֹא תֵלֵךְ, גּוֹזְרַנִי עָלֶיךְ שֶׁלֹּא תִכָּנֵס לַשָּׁמַיִם, וְתִהְיֶה בַּמָּקוֹם שֶׁל עֲזָא וַעֲזָאֵל, וּכְשֶׁתִּכָּנֵס לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֱמֹר לוֹ, אִם אֵין שְׁלֹשִׁים צַדִּיקִים בָּעוֹלָם - שֶׁיִּהְיוּ עֶשְׂרִים, שֶׁכָּךְ כָּתוּב: (בראשית יח) לֹא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים. וְאִם אֵין עֶשְׂרִים - שֶׁיִּהְיוּ עֲשָׂרָה, שֶׁכָּךְ כָּתוּב: לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה, וְאִם אֵין עֲשָׂרָה - שֶׁיִּהְיוּ שְׁנַיִם, שֶׁהֵם אֲנִי וּבְנִי, שֶׁכָּךְ כָּתוּב: (דברים יט) עַל פּיּ שּנַיּם שְׁנֵי עֵדִים יָקוּם דָּבָר, וְאֵין דָּבָר אֶלָּא עוֹלָם, שֶׁכָּתוּב (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ, וְאִם אֵין שְׁנַיִם - הֲרֵי יֵשׁ אֶחָד, וַאֲנִי הוּא, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. בְּאוֹתָהּ שָׁעָה יָצָא קוֹל מִשָּׁמַיִם וְאָמַר: אַשְׁרֵי חֶלְקְךְ רַבִּי שִׁמְעוֹן, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר לְמַעְלָה - וְאַתָּה מְבַטֵּל לְמַטָּה. בְּוַדַּאי עָלֶיךְ נֶאֱמַר (שם קמה) רְצוֹן יְרֵאָיו יַעֲשֶׂה: ע\"כ מההשמטות.</p>"],[9522012690,"<p>שֶׁהוּא רֵאשִׁית עַד עֲשָׂרָה, שֶׁהוּא עֲשָׂרָה סוֹף הַדְּרָגוֹת. וְכֵיוָן שֶׁמַּגִּיעַ עַד עֲשָׂרָה אָמַר: מִכָּאן וּלְמַטָּה אֵין מָקוֹם לַעֲמֹד בִּתְשׁוּבָה. וְשָׁב וְאָמַר אַרְבָּעִים כְּדֵי שֶׁיִּנָּצְלוּ אַרְבַּע קְרָיוֹת, וְשָׁב וְאָמַר שְׁלֹשִׁים כְּדֵי שֶׁיִּנָּצְלוּ שָׁלֹשׁ קְרָיוֹת, וְשָׁב וְאָמַר עֶשְׂרִים כְּדֵי שֶׁיִּנָּצְלוּ שְׁתֵּי קְרָיוֹת, וְשָׁב וְאָמַר עֲשָׂרָה כְּדֵי שֶׁתִּנָּצֵל קִרְיָה אַחַת מֵאוֹתָן הֶחָמֵשׁ, מִשּׁוּם כָּךְ לֹא יָרַד לְמַטָּה מִן עֲשָׂרָה:</p>"],[9522012691,"<p>וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וְגוֹמֵר (בראשית כא). רַבִּי בְּרוֹקָא אָמַר, מַה זֶּה שָׂם עַל שִׁכְמָהּ? אֶלָּא שֶׁהִזְהִירָהּ עַל עֹל הָאֱמוּנָה וְלַעֲמֹד בְּמַה שֶּׁהָיְתָה בַּתְּחִלָּה. כָּתוּב כָּאן שָׂם עַל שִׁכְמָהּ, וְכָתוּב שָׁם (שמות טו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. מַה לְּהַלָּן עַל הַשְּׁכִינָה, אַף כָּאן עַל הַשְּׁכִינָה. מֶה עָשְׂתָה? כֵּיוָן שֶׁרָאֲתָה עַצְמָהּ יוֹצֵאת מֵרְשׁוּתוֹ שֶׁל אַבְרָהָם, חָזְרָה לְקִלְקוּלָהּ, שֶׁכָּתוּב (בראשית כא) וַתֵּלֶךְ וַתֵּתַע. מַה זֶּה וַתֵּתַע? שֶׁתִּעְתְּעָה אַחַר עֲבוֹדָה זָרָה וְגִלּוּלֵי בֵּית אָבִיהָ. כָּתוּב כָּאן וַתֵּתַע, וְכָתוּב שָׁם (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים:</p>"],[9522012692,"<p>כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּם בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ (בראשית ז). שָׁאַל רַבִּי חִיָּיא אֶת רַבִּי אַבָּא, אֲמַרְתֶּם שֶׁנְּשָׁמָה לֹא נִכְנֶסֶת לְבֶן אָדָם עַד שֶׁמִּסְתַּכֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז תִּהְיֶה לוֹ אוֹתָהּ נְשָׁמָה, וַאֲמַרְתֶּם שֶׁהַנְּשָׁמָה הִיא קְדוֹשָׁה מְעֻלָּה עַל הַכֹּל. אִם כֵּן, מַה זֶּה שֶׁאָמַר הַכָּתוּב כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים וְגוֹ'? הוֹאִיל וְהָיְתָה לָהֶם נְשָׁמָה, הָיָה לָהֶם לְהִנָּצֵל! לֹא הָיָה בְיָדוֹ.</p>\n<p>בָּאוּ וְשָׁאֲלוּ אֶת רַבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן. אָמַר לָהֶם, כָּךְ הוּא, וּפָסוּק זֶה מְסַיֵּעַ לוֹ, שֶׁכָּךְ אָמַר אָבִיו (אבי), שֶׁכַּאֲשֶׁר בָּא הַמַּבּוּל, לֹא רָאָה (היה) אָדָם שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁבִילוֹ אֶלָּא נֹחַ, וּזְכוּתוֹ לֹא הָיְתָה אֶלָּא לְהָגֵן עֲלֵיהֶם וְעַל בָּתֵּיהֶם, שֶׁלֹּא הָיְתָה זְכוּתוֹ כָּל כָּךְ לְהָגֵן עַל כָּל הַדּוֹר,</p>\n<p>וְאוֹתָם שֶׁהָיוּ צַדִּיקִים בַּתְּחִלָּה, כְּמוֹ חֲנוֹךְ וְיֶרֶד, שֶׁהָיְתָה לָהֶם נְשָׁמָה קְדוֹשָׁה וּרְאוּיִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲשֶׂה בִּשְׁבִילָם - בֶּחָרָבָה מֵתוּ. וְהַיְנוּ שֶׁאָמַר כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו, אוֹתָם שֶׁנְּשָׁמָה קְדוֹשָׁה הָיְתָה בָהֶם. וְאַל תֹּאמַר שֶׁעַל אֵלּוּ שֶׁהָיוּ בַּמַּבּוּל הוּא אָמַר, אֶלָּא בָּא הַכָּתוּב וְאָמַר מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ:</p>"],[9522012693,"<p>אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂרֵקָה בְּנִי אֲתֹנוֹ כִּבֵּס בַּיַּיִן לְבֻשׁוֹ וּבְדַם עֲנָבִים סוּתֹה (בראשית מט). שְׁמוֹנֶה דְרָגוֹת כְּלוּלוֹת בְּפָסוּק זֶה. אַרְבַּע מֵהֶן דּוֹמוֹת זוֹ לָזוֹ, שְׁתַּיִם מֵהֶן דּוֹמוֹת זוֹ לָזוֹ, וּשְׁתַּיִם אֲחֵרוֹת דּוֹמוֹת זוֹ לָזוֹ. אַרְבַּע שֶׁדּוֹמוֹת זוֹ לָזוֹ הֵן גֶּפֶן שּרֵקָה, הַיְנוּ גֶפֶן הַיְנוּ שּׁרֵקָה, שֶׁמֵּהֶם יוֹצְאִים עֲנָבִים וּמֵהֶם נַעֲשֶׂה יַיִן שֶׁנִּקְרָא יַיִן, וְכֻלָּן סוֹד אֶחָד וּמִשֹּׁרֶשׁ אֶחָד יוֹצְאוֹת וְשׁוֹפְעוֹת. וּשְׁתַּיִם שֶׁדּוֹמוֹת זוֹ לָזוֹ - עִירֹה אֲתֹנוֹ, הַיְנוּ עִירֹה הַיְנוּ אֲתֹנוֹ, וְסוֹד אֶחָד הֵם, וּבְדַרְגָּה אַחַת כְּלוּלוֹת וּמִסּוֹד אֶחָד שׁוֹפְעוֹת.</p>\n<p>לְבֻשׁוֹ סוּתֹה זֶה דָּבָר אֶחָד וְסוֹד אֶחָד, (שמות כב) כִּי הִיא כְסוּתֹה לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעֹרוֹ. פַּעַם קוֹרֵא לוֹ כְּסוּת, וּפַעַם אַחֶרֶת קוֹרְאֵהוּ לְבוּשׁ, וּפַעַם אַחֶרֶת קוֹרְאֵהוּ שִׂמְלָה, וְכֻלָּם מִשֹּׁרֶשׁ אֶחָד שׁוֹפְעִים וְדָבָר אֶחָד עוֹשִׂים, וְחִלּוּף הַשֵּׁמוֹת כְּלוּלִים בָּהֶם סוֹדוֹת עֶלְיוֹנִים, וּמִי שֶׁדִּיֵּק טָעַם מַשֶּׁהוּ, וּמִי שֶׁלֹּא דִיֵּק - לֹא טָעַם וְלֹא מַשֶּׁהוּ. וּשְׁמוֹנֶה הַדְּרָגוֹת הַלָּלוּ רְמוּזִים בָּהֶן סוֹדוֹת עֶלְיוֹנִים, אֲבָל הַפָּסוּק עוֹמֵד כִּפְשׁוּטוֹ.</p>\n<p>בֹּא רְאֵה, יַעֲקֹב הַשָּׁלֵם שֶׁבָּאָבוֹת הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כה) וְיַעֲקֹב אִישׁ תָּם וְגוֹ'. מַה זֶּה אִישׁ תָּם? שֶׁנִּתְקַן מִן הַחָכְמָה שֶׁלְּמַעְלָה וּמֵהַחָכְמָה שֶׁלְּמַטָּה, וְהַיְנוּ שֶׁכָּתוּב יֹשֵׁב אֹהָלִים. שְׁנֵי אֹהָלִים הֵם - אֹהֶל שֶׁנִּקְרָא לִפְנִים מִן הַפַּרְגּוֹד, וְאֹהֶל שֶׁנִּקְרָא אֲחוֹרֵי הַפַּרְגּוֹד, וְכָלוּל הָיָה מִשְּׁנֵי צְדָדִים - מִבָּתִּים פְּנִימִיִּים וּמִבָּתִּים חִיצוֹנִיִּים,</p>\n<p>וּמִי לִמֵּד אֶת יַעֲקֹב כָּל זֶה? בֹּא רְאֵה, שֶׁהֲרֵי אוֹתָן שָׁנִים שֶׁהָיָה טָמוּן וְגָנוּז עִם שֵׁם וָעֵבֶר, שֵׁם לִמֵּד אוֹתוֹ חָכְמָה עֶלְיוֹנָה שֶׁל בָּתִּים פְּנִימִיִּים. וְעֵבֶר לִמֵּד אוֹתוֹ כִּשְׁפוּת (חכמה) תַּחְתּוֹנָה, וְסִימָן לַדָּבָר - (יהושע כד) בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם.</p>\n<p>מַה זֶּה בְּעֵבֶר הַנָּהָר? אֶלָּא סוֹד הוּא, שֶׁכָּל יְמֵיהֶם שֶׁל אוֹתָם קַדְמוֹנִים לֹא הָיוּ לוֹמְדִים אֶלָּא חָכְמָה תַּחְתּוֹנָה שֶׁבָּאָה מִבָּתִּים חִיצוֹנִיִּים שֶׁנִּקְרָאִים אֲחוֹרֵי הַפַּרְגּוֹד, וּבְאוֹתָם שֶׁאֲחוֹרֵי הַפַּרְגּוֹד הָיוּ דְבֵקִים, וְהָיוּ מוֹדִיעִים לָהֶם דְּבָרִים שֶׁעֲתִידִים לָבא לָעוֹלָם, טוֹב אוֹ רַע, וְאָז הָיוּ כָּל אוֹתָם דּוֹרוֹת,</p>\n<p>עַד שֶׁבָּא אוֹתוֹ צַד הַקְּדֻשָּׁה וְהִמְשִׁיךְ לוֹ לְאַבְרָהָם וְהוֹדִיעוֹ דְבָרִים שֶׁל שֹׁרֶשׁ שֶׁנִּמְשָׁכִים לָעוֹלָם שֶׁלָּהֶם מִבָּתִּים פְּנִימִיִּים, וּמִשָּׁם שׁוֹאֲבִים כָּל אֵלּוּ שֶׁנִּקְרָאִים בָּתִּים חִיצוֹנִיִּים, וּמִשָּׁם מִתְהַוִּים קְצָת דְּבָרִים, לֹא הַכֹּל, וְסִימָן לַדָּבָר - מִתַּמְצִית גּוּפָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הָעוֹלָם שׁוֹתֶה.</p>\n<p>וּמִשָּׁעָה זוֹ שֶׁעָמַד אַבְרָהָם אָבִינוּ, עָלָיו הַשָּׁלוֹם, עַל אוֹתוֹ צַד הַקְּדֻשָּׁה, שֶׁמִּמֶּנּוּ הַכֹּל יוֹצֵא וְשׁוֹפֵעַ וּבוֹ הַכֹּל תָּלוּי, יָצָא לוֹ לִשְׁעָתוֹ מִצַּד זֶה שֶׁהֵם בְּנֵי עֵבֶר הַנָּהָר, וּבָא לוֹ לְהִשְׁתַּעֲשֵׁעַ בָּאָרֶץ הַקְּדוֹשָׁה. זֶהוּ שֶׁכָּתוּב (יהושע כד) וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם מֵעֵבֶר הַנָּהָר וָאוֹלֵךְ אוֹתוֹ בְּכָל אֶרֶץ כְּנָעַן, אֶרֶץ כְּנַעַן מַמָּשׁ, אֶרֶץ שֶׁשְּׁאָר הַחֲיָלוֹת הָעֶלְיוֹנִים נִשְׁבָּרִים תַּחְתֶּיהָ שָׁם, וְאֵין לָהֶם קִיּוּם עִמָּהּ: ע\"כ מההשמטות</p>"],[9522012694,"<p>וְשַׁחֲטוּ הַפָּסַח. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִבֶּעָשׂוֹר לַחֹדֶשׁ קְחוּ יִרְאָתָם שֶׁל מִצְרַיִם וְתִפְסוּ אוֹתוֹ, וְיִהְיֶה אָסוּר וְתָפוּס שְׁלֹשָׁה יָמִים, וּבַיּוֹם הָרְבִיעִי הוֹצִיאוּ אוֹתוֹ לְדִין וְתִתְכַּנְּסוּ עָלָיו לְהָרְגוֹ, וְיִרְאוּ אוֹתוֹ הַמִּצְרִים אֵיךְ אַתֶּם עוֹשִׂים בּוֹ דִּין, וְזֶה קָשֶׁה לָהֶם מִכָּל הַמַּכּוֹת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵלּוּ הַדִּינִים שֶׁעָשׂוּ בֵאלֹהֵיהֶם.</p>\n<p>וְאַחַר כָּךְ דָּנִים אוֹתוֹ בָּאֵשׁ, מִשּׁוּם שֶׁכָּתוּב (דברים ז) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, (שמות יב) אַל תֹּאכְלוּ מִמֶּנּוּ נָא, שֶׁלֹּא יֹאמְרוּ בְּתֵאָבוֹן שֶׁל פַּחַד אָכְלוּ אוֹתוֹ, אֶלָּא תְּתַקְּנוּ אוֹתוֹ צָלִי וְלֹא מְבֻשָּׁל. שֶׁאִם הָיָה מְבֻשָּׁל, יְהֵא מֻסְתָּר וְלֹא יִרְאוּ אוֹתוֹ. אֶלָּא תַּקְּנוּ אוֹתוֹ צָלוּי בָּאֵשׁ, שֶׁרֵיחוֹ נוֹדֵף.</p>\n<p>וְעוֹד, רֹאשׁוֹ עָלָיו, שֶׁלֹּא יֹאמְרוּ שֶׁחַיָּה אוֹ דָבָר אַחֵר הִיא. וְעוֹד, עֶצֶם לֹא תִשְׁבְּרוּ בוֹ, אֶלָּא שֶׁיִּרְאוּ עַצְמוֹתָיו מֻשְׁלָכִים בַּשּׁוּק וְלֹא יִהְיוּ יְכוֹלִים לְהַצִּיל אוֹתוֹ, וְעַל זֶה כָּתוּב (במדבר לג) וּבֵאלֹהֵיהֶם עָשָׂה ה' שְׁפָטִים.</p>\n<p>אוֹתוֹ רִאשׁוֹן שֶׁנִּמְצָא בְּבֵית הַכְּנֶסֶת וּמַאֲרִיךְ בְּבֵית הַכְּנֶסֶת, אַשְׁרֵי חֶלְקוֹ, שֶׁהוּא עוֹמֵד בְּמַדְרֵגָה שֶׁל צַדִּיק עִם הַשְּׁכִינָה, וְזֶהוּ סוֹד (משלי ח) וּמְשַׁחֲרַי יִמְצָאֻנְנִי. זֶה עוֹלֶה בְמַדְרֵגָה רִאשׁוֹנָה. וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבֵית הַכְּנֶסֶת וְלֹא מוֹצֵא שָׁם עֲשָׂרָה - מִיָּד כּוֹעֵס.</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁשָּׁלַח לְכָל מַלְכֵי (אנשי) הַמְּדִינָה שֶׁיִּמָּצְאוּ עִמּוֹ בְּיוֹם פְּלוֹנִי בְּמָקוֹם פְּלוֹנִי. עַד שֶׁהָיוּ מְכִינִים עַצְמָם אֵלּוּ בְּנֵי הָעִיר, הִקְדִּים אֶחָד וּבָא לְאוֹתוֹ מָקוֹם. בֵּין כָּךְ וּבֵין כָּךְ בָּא הַמֶּלֶךְ וּמָצָא לְאוֹתוֹ אָדָם שֶׁהִקְדִּים שָׁם. אָמַר לוֹ, בְּנֵי עִיר פְּלוֹנִית הֵיכָן הֵם? אָמַר לוֹ, אֲדוֹנִי, אֲנִי הִקְדַּמְתִּי מֵהֶם וְהִנֵּה הֵם בָּאִים אַחֲרַי לְצִוּוּי הַמֶּלֶךְ. אָז טוֹב בְּעֵינֵי הַמֶּלֶךְ וְיוֹשֵׁב שָׁם עִמּוֹ וּמְדַבֵּר עִמּוֹ וְנַעֲשֶׂה אָהוּב שֶׁל הַמֶּלֶךְ. בֵּין כָּךְ בָּאוּ כָּל הָעָם וְהִתְפַּיֵּס עִמָּהֶם. אֲבָל אִם בְּנֵי הָעִיר לֹא בָאִים וְאֶחָד לֹא מַקְדִּים וּמְדַבֵּר לִפְנֵי הַמֶּלֶךְ לְהֵרָאוֹת בִּשְׁבִילָם, מִיָּד כּוֹעֵס הַמֶּלֶךְ. מַה כָּתוּב? (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ.</p>\n<p>וּמִי שֶׁמְּדַבֵּר בְּבֵית הַכְּנֶסֶת - אוֹי לוֹ שֶׁמַּרְאֶה פֵרוּד! אוֹי לוֹ שֶׁגּוֹרֵעַ מֵהָאֱמוּנָה! אוֹי לוֹ שֶׁאֵין לוֹ חֵלֶק בֵּאלֹהֵי יִשְׂרָאֵל, שֶׁמַּרְאֶה שֶׁאֵין לוֹ אֱלוֹהַּ וְלֹא נִמְצָא שָׁם, וּמַנְהִיג קָלוֹן בַּגְּבוּרָה הָעֶלְיוֹנָה.</p>\n<p>כָּל הַצְּבָעִים טוֹבִים בַּחֲלוֹם חוּץ מִתְּכֵלֶת, מִשּׁוּם שֶׁהוּא כִּסֵּא לָדוּן דִּינִים שֶׁל הַנְּשָׁמוֹת, וַהֲרֵי מַדְרֵגָה אַחַת הִיא. אֶלָּא בְּשָׁעָה שֶׁעוֹמְדִים בְּדִינֵי נְפָשׁוֹת, אָז הוּא צֶבַע תְּכֵלֶת, וַהֲרֵי בֵּאַרְנוּ. וּבְשָׁעָה שֶׁרוֹאֶה אָדָם לְזֶה הַצֶּבַע, נִזְכָּר אָדָם לַעֲשׂוֹת מִצְוַת אֲדוֹנוֹ, כְּגוֹן הַנָּחָשׁ שֶׁהָיוּ רוֹאִים אוֹתוֹ וְהָיוּ יְרֵאִים מִפְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹמְרִים עַצְמָם, וּבְאוֹתָהּ יִרְאָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָה עֲלֵיהֶם מַיִם וּמִתְכַּסִּים. מִי גָרַם לָהֶם? אוֹתוֹ הַנָּחָשׁ, אוֹתָהּ רְצוּעָה שֶׁמִּסְתַּכְּלִים בָּהּ. אַף כָּךְ הַתְּכֵלֶת - וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְוֹת ה'. מֵאוֹתָהּ יִרְאָה שֶׁלּוֹ:</p>"],[9522012695,"<p>בֹּא רְאֵה, הָהָר הַזֶּה, לָשׁוֹן קָשָׁה הוּא. אוֹתָם הָרִים לְמַעְלָה, וְצַדִּיקִים הָאֵלּוּ שֶׁאֲחוּזִים בִּכְנֶסֶת יִשְׂרָאֵל, וְנִקְרָאִים הַר צִיּוֹן אוֹתָם הָרִים שֶׁסְּבִיב יְרוּשָׁלַיִם, בִּגְלַל שֶׁהֵם מְצֻיָּנִים וְאוֹמְרִים זֶה לָזֶה בְּצַד הַיִּחוּד (עובדיה א) לִשְׁפֹּט אֶת הַר עֵשָׂו, שֶׁקִּטְרוּג הַמְקַטְרֵג מִצַּד הַשְּׂמֹאל.</p>\n<p>בְּאוֹתוֹ זְמַן, וְהָיְתָה לַה' הַמְּלוּכָה. בַּהַתְחָלָה נִקְרֵאת מַמְלָכָה, מִשּׁוּם שֶׁמֵּינִיקָה לִשְׁנֵי צְדָדִים - לְיָמִין וְלִשְׂמֹאל. וְעַכְשָׁו נִקְרֵאת מְלוּכָה, בִּגְלַל שֶׁמֵּינִיקָה לְיָמִין. זֶהוּ שֶׁכָּתוּב (הושע ב) וְאֵרַשְׂתִּיךְ לִי לְעוֹלָם. וּבִגְלַל שֶׁהַגָּלוּת לֹא לְעוֹלָם הִיא, שֶׁהֲרֵי יוֹשֶׁבֶת בַּגָּלוּת.</p>\n<p>בֹּא רְאֵה, שֶׁסָּמוּךְ לוֹ (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בִּגְלַל שֶׁעַד עַכְשָׁו, כְּשֶׁיִּשְׂרָאֵל בַּגָּלוּת - שְׁכִינָה עִמָּהֶם, וּמֶלֶךְ בְּלִי גְבִירָה אֵינוֹ מֶלֶךְ, אֲבָל אוֹתוֹ זְמַן, וְהָיָה ה' מֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. כְּשֶׁנִּדְבֶּקֶת הַשְּׁכִינָה בְּצַדִּיק, אָז הוּא הַיִּחוּד. שֶׁכָּךָ לָמַדְנוּ בַּסּוֹד שֶׁל קְרִיאַת שְׁמַע, שֶׁצָּרִיךְ אָדָם לְיַחֵד לַאֲדוֹנוֹ וּלְקַשֵּׁר קִשְׁרֵי הָאֱמוּנָה בִּרְצוֹן הַלֵּב.</p>\n<p>וּכְשֶׁמַּגִּיעַ לְ\"אֶחָד\", צָרִיךְ לוֹ לְכַוֵּן בְּא' נִסְתֶּרֶת עַתִּיקָה (עמקה) שֶׁל הַכֹּל, וְח' - שְׁמוֹנֶה דְרָגוֹת עֶלְיוֹנוֹת מֵחָכְמָה עֶלְיוֹנָה עַד צַדִּיק. וְד' גְּדוֹלָה - הִתְדַּבְּקוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא חֶלְקוֹ שֶׁל דָּוִד שֶׁנִּקְרָא (תהלים פו) עָנִי וְאֶבְיוֹן, כְּשֶׁנִּדְבֶּקֶת לְאוֹתָן דְּרָגוֹת שֶׁלְּמַעְלָה שֶׁרְמוּזוֹת בְּא\"ח. אָז הִיא גְּדוֹלָה וְכָל הָעוֹלָם יוֹנֵק מִמֶּנָּה, וְאוֹתָם שָׁדַיִם שֶׁהֵם כַּמִּגְדָּלוֹת, (שיר ח) אָז הָיִיתִי בְעֵינָיו כְּמוֹצְאֵת שָׁלוֹם. בֹּא רְאֵה, פָּסוּק זֶה עַל כְּנֶסֶת יִשְׂרָאֵל נִתְבָּאֵר. כְּשֶׁהִיא בַּגָּלוּת עִם בָּנֶיהָ בֵּין אֻמּוֹת הָעוֹלָם נִקְרֵאת קְטַנָּה, זֶהוּ שֶׁכָּתוּב (שם) אָחוֹת לָנוּ קְטַנָּה. וּכְשֶׁיִּשְׂרָאֵל נִדְבָּקִים בַּתּוֹרָה וְהוֹלְכִים בְּדֶרֶךְ אֱמֶת, אָז מִתְמַלֵּאת, וְשָׁלוֹם מִתְחַבֵּר בָּהֶם. מְשִׁיבָה הִיא וְאוֹמֶרֶת, אֲנִי חוֹמָה וְשָׁדַי כַּמִּגְדָּלוֹת.</p>\n<p>בְּאוֹתוֹ זְמַן שֶׁהִתְחַבֵּר עִמִּי, אָז וְשָׁלוֹם. א' סוֹד הָעַתִּיק הַקָּדוֹשׁ שֶׁל הַכֹּל. ז' שֶׁבַע דְּרָגוֹת, וְשָׁלוֹם שֶׁנִּקְרָא צַדִּיק. כֵּיוָן שֶׁהַדְּרָגוֹת הַלָּלוּ מִתְחַבְּרוֹת, אָז הָיִיתִי בְעֵינָיו כְּמוֹצְאֵת שָׁלוֹם. וְאֵיזֶה עֵינַיִם אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁנִּקְרָאוֹת עֵינֵי ה', פְּנֵי ה', וְאָז שָׁלוֹם לָעוֹלָם, וְשׁוֹרֶה הַטּוֹב שֶׁל הָעַתִּיק בְּמָקוֹם שֶׁל זָכָר וּנְקֵבָה, וְלָכֵן צִוָּה מֹשֶׁה בַּתּוֹרָה וְאָמַר (דברים יד) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. לְקַשֵּׁר אֶת כָּל קִשְׁרֵי הָאֱמוּנָה.</p>\n<p>בֹּא רְאֵה, כָּל הַמַּאֲרִיךְ בְּאֶחָד, מַאֲרִיכִין לוֹ יָמָיו וּשְׁנוֹתָיו. מָה הַטַּעַם בִּגְלַל שֶׁהוּא מָקוֹם שֶׁכָּל יְמֵי וּשְׁנוֹת הָעוֹלָם בּוֹ תְּלוּיִים בְּסוֹד אוֹתָם הַדְּרָגוֹת שֶׁרְמוּזוֹת בְּאֶחָד, וְהֵם עֲשָׂרָה, וְכֻלָּם אֶחָד. וְהִתְעוֹרְרוּ בוֹ הַחֲבֵרִים וְאָמְרוּ, בְּדָלֶ\"ת וְיָפֶה, בִּגְלַל שֶׁמָּקוֹם זֶה שֶׁל דָּלֶ\"ת הוּא, וְאֵין לָהּ אוֹר מִשֶּׁלָּהּ, וְצָרִיךְ אָדָם לְהַאֲרִיךְ בָּהּ וְלִמְשֹׁךְ לָה בְּרָכוֹת מֵאוֹתָם שִׁשָּׁה צְדָדִים, שִׁשָּׁה בָנִים עֶלְיוֹנִים עַל יְדֵי הַצַּדִּיק, וְאוֹתָם שִׁשָּׁה צְדָדִים רְמוּזִים בְּח', בְּסוֹד שֶׁל שְׁמוֹנָה.</p>\n<p>שֵׁשֶּׁת אֵלֶּה, וּשְׁנַיִם לְמַעְלָה - חָכְמָה וּבִינָה, אָב וָאֵם - לְהוֹסִיף וּלְהַכְלִילָם לְמַעְלָה וְלָתֵת לָהֶם בְּרָכוֹת מֵאָב וָאֵם הָעֶלְיוֹנִים, שֶׁהֲרֵי אֵין שׁוֹרֶה הַטּוֹב שֶׁל הָעַתִּיק אֶלָּא בְּמָקוֹם שָׁלֵם, בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹמֵר. בְּיוֹם חֲתֻנָּתוֹ וְגוֹמֵר. בְּיוֹם חֲתֻנָּתוֹ דַּוְקָא.</p>\n<p>וְעַל זֶה אָמְרוּ, וּבִלְבַד שֶׁלֹּא יַחֲטֹף בְּחֵי\"ת, אֶלָּא צָרִיךְ לִמְשֹׁךְ בְּרָכוֹת מִמָּקוֹם עֶלְיוֹן שֶׁל הַכֹּל, וּלְהָרִיק בְּאוֹתָם שִׁשָּׁה בָנִים. אַחַר כָּךְ לַבַּת הַ את שֶׁאֵין לָהּ יְרֻשָּׁה בְּבֵית אָבִיהָ וְאִמָּהּ, אֶלָּא רַק הַבֵּן הַזֶּה. וּמִכָּאן לָמַדְנוּ שֶׁבֵּן יוֹרֵשׁ אָב וָאֵם, וּבַת לֹא, אֶלָּא שֶׁיֵּשׁ לָהּ מְזוֹנוֹת מִן הַבֵּן, אֶלָּא צָרִיךְ לְהַאֲרִיךְ בַּדָּלֶ\"ת הַ את.</p>\n<p>וְשָׁם אוֹמְרִים כַּמָּה צָרִיךְ אָדָם לְהַאֲרִיךְ בָּהּ, כְּשִׁעוּר שֶׁיַּמְלִיךְ אוֹתָהּ לְמַעְלָה וּלְמַטָּה וּלְאַרְבַּע זָוִיּוֹת הָעוֹלָם, סוֹד שֶׁל שִׁשָּׁה צְדָדִים עֶלְיוֹנִים שֶׁכֻּלָּם יִתְחַבְּרוּ עִמָּהּ וְלֹא יִפָּרְדוּ לְעוֹלָמִים, וּכְשֶׁאָדָם מַאֲרִיךְ בָּזֶה, כָּל אוֹתָם יָמִים וְשָׁנִים עֶלְיוֹנִים מוֹשְׁכִים בְּרָכָה עַל רֹאשׁוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>בֹּא רְאֵה, כְּלַל הַתּוֹרָה בַּפָּסוּק הַזֶּה רְמוּזִים, וּכְלָל שֶׁל כָּל אוֹתָן הָאֲמִירוֹת שֶׁבָּהֶן נִבְרָא הָעוֹלָם רְמוּזִים בְּאֶחָד. זֶהוּ שֶׁכָּתוּב (איוב כג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֶנּוּ וְנַפְשׁוֹ אִוְּתָה וַיָּעַשׂ. וּבָהֶם נִבְרָא הָעוֹלָם. וְעַל זֶה שָׁנִינוּ, בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם וְכוּ', וּפֵרַשְׁנוּ שֶׁכֻּלָּם עֲשָׂרָה, וְכֻלָּם כְּלוּלִים בַּפָּסוּק הָרִאשׁוֹן שֶׁל הַתּוֹרָה.</p>"],[9522012696,"<p>בְּרֵאשִׁית - סוֹד הַחָכְמָה. בָּרָא - הָעֶלְיוֹן הַנִּסְתָּר שֶׁלֹּא נוֹדָע. אֱלֹהִים - בִּינָה. אֵת - כְּלָל שֶׁל חֶסֶד וּגְבוּרָה. הַשָּׁמַיִם - תִּפְאֶרֶת. וְאֵת - כְּלָלוּת שֶׁל נֵצַח וְהוֹד. וָא\"ו שֶׁל \"וְאֶת\" - לְהַכְלִיל הַצַּדִּיק. הָאָרֶץ - כְּלָלוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל, אֶרֶץ הַחַיִּים, וְאַחַר כָּךְ פְּרָט שֶׁל תּוֹרָה בְּסוֹד אוֹתָם יָמִים עֶלְיוֹנִים. בְּרֵאשִׁית הוּא מַאֲמָר, כְּנֶגֶד הַדַּרְגָּה שֶׁל חָכְמָה, וְנִקְרָא רֵאשִׁית.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר - כְּנֶגֶד הַדַּרְגָּה שֶׁל חֶסֶד שֶׁהִיא לְיָמִין, שֶׁהֲרֵי מִשָּׁם יוֹצֵא אוֹר לְכָל הָעוֹלָמוֹת בְּסוֹד שֶׁל יוֹם, זֶהוּ שֶׁכָּתוּב (תהלים נב) חֶסֶד אֵל כָּל הַיּוֹם. וּכְנֶגְדּוֹ לְמַטָּה, אַבְרָהָם שֶׁאוֹחֵז בַּחֵלֶק הַזֶּה, וְלָכֵן כָּתוּב כָּאן יוֹם אֶחָד, וְכָאן - אֶחָד הָיָה אַבְרָהָם, וּבוֹ כָּתוּב (ישעיה מא) מִי הֵעִיר מִמִּזְרָח, בְּסוֹד שֶׁל אוֹר שֶׁיּוֹצֵא מִמִּזְרָח.</p>\n<p>וּבֹא רְאֵה, לֹא תִמְצָא בְּכָל שִׁבְעַת הַצַּדִּיקִים שֶׁאֲחוּזִים לְמַעְלָה בְּסוֹד שֶׁל שְׁמוֹתֵיהֶם בַּתְּחִלָּה אָלֶף, אֶלָּא אַבְרָהָם וְאַהֲרֹן שֶׁאֲחוּזִים בַּחֶסֶד הַזֶּה, שֶׁהֲרֵי כֹּהֲנִים מִצַּד הַחֶסֶד בָּאִים. אַף עַל גַּב שֶׁאַהֲרֹן אָחוּז בְּהוֹד, גַּם בְּחֶסֶד הוּא אָחוּז. וּמֹשֶׁה, אַף עַל גַּב שֶׁאָחוּז בְּנֵצַח, גַּם בְּתִפְאֶרֶת אָחוּז הוּא, לְהַרְאוֹת שֶׁהַכֹּל אֶחָד. וְאַבְרָהָם רֹאשׁ לְכָל הַצַּדִּיקִים, וּמִמֶּנּוּ נִפְרְדוּ לְמַטָּה, שֶׁהוּא לִימִין הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרָא כֹּהֵן, זֶהוּ שֶׁכָּתוּב (תהלים קי) אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק. וְאַהֲרֹן אָחוּז בָּזֶה בִּגְלַל שֶׁהוּא כֹּהֵן, אֲבָל דַּרְגָּתוֹ הוּא הוֹד.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל וְכוּ' - כְּנֶגֶד הַדַּרְגָּה שֶׁל גְּבוּרָה שֶׁשָּׁם אָחוּז יִצְחָק, וּכְנֶגְדּוֹ תִּפְאֶרֶת. הַמַּיִם הוֹלִידוּ אֵשׁ, בִּגְלַל כָּךְ יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל, וּבִגְלַל כָּךְ לְמַטָּה (בראשית כה) אַבְרָהָם הוֹלִיד אֶת יִצְחָק, וּבְאוֹתוֹ יוֹם נִבְרָא גֵיהִנֹּם, שֶׁיָּצָא מֵאוֹתָהּ אֵשׁ חֲזָקָה בְּאוֹתָהּ מַחֲלֹקֶת, וְלָכֵן אוֹתוֹ יוֹם הוּא יוֹם הַדִּין.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם - כְּנֶגֶד דַּרְגַּת תִּפְאֶרֶת שֶׁנִּקְרָא קַו הָאֶמְצָעִי, וּכְנֶגֶד יַעֲקֹב שֶׁהוּא שְׁלִישִׁי, וְנוֹטֵל שְׁנֵי חֲלָקִים בְּאוֹתוֹ שֶׁל אֵשׁ וּמַיִם (של אש השמים) מִשָּׁמַיִם, וּכְנֶגְדּוֹ יוֹם שְׁלִישִׁי, וְעַל זֶה נִקְרָא יַעֲקֹב (שם) אִישׁ תָּם יֹשֵׁב אֹהָלִים. שָׁלֵם בַּכֹּל. שָׁלֵם בְּחֶסֶד. שָׁלֵם בְּדִין. שָׁלֵם בְּמַיִם. שָׁלֵם בְּאֵשׁ. יֹשֵׁב אֹהָלִים - שְׁנַיִם, חֶסֶד וּגְבוּרָה, וְנוֹטֵל הַכֹּל, וְנַעֲשֶׂה בְיָדָיו רַחֲמִים.</p>\n<p>וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי וְגוֹמֵר. הַדַּרְגָּה שֶׁל צַדִּיק שֶׁנִּקְרָא עֵץ הַחַיִּים, וְהוּא עוֹשֶׂה פְּרִי, שֶׁהֲרֵי אֵין בְּכֻלָּם שֶׁיַּעֲשֶׂה פְּרִי פְּרָט לוֹ. זַרְעוֹ בוֹ עַל הָאָרֶץ, דַּוְקָא, וּכְנֶגְדּוֹ לְמַטָּה (שם מט) בֵּן פֹּרָת יוֹסֵף בֵּן פֹּרָת עֲלֵי עָיִן, וְנִקְרָא בְּרִית שָׁלוֹם.</p>\n<p>וְלָכֵן פַּעֲמַיִם בַּיּוֹם הַזֶּה כִּי טוֹב, אֶחָד כְּנֶגֶד דַּרְגַּת תִּפְאֶרֶת, וְאֶחָד כְּנֶגֶד דַּרְגַּת צַדִּיק, שֶׁהוּא יוֹם הַשַּׁבָּת שֶׁלְּמַעְלָה, וּמַעֲשֶׂה אַחֵר אֵין בּוֹ אֶלָּא זִוּוּג לְהוֹצִיא פְּרִי נְשָׁמוֹת לָעוֹלָם, פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כָּךְ גַּם לְמַטָּה, שֶׁזִּוּוּג מֻתָּר בּוֹ מִשַּׁבָּת לְשַׁבָּת.</p>\n<p>בֹּא רְאֵה סוֹד עֶלְיוֹן שֶׁל הַתּוֹרָה, מַה זֶּה עֵץ פְּרִי עֹשֶׂה פְּרִי, הוּא כְּנֶגֶד יוֹם הַשַּׁבָּת, מָה הַטַּעַם נִכְלָל בְּיוֹם שְׁלִישִׁי סוֹד עֶלְיוֹן הוּא, בִּגְלַל שֶׁשָּׁנִינוּ, רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי אוֹמֵר, מָה הַטַּעַם כָּתוּב בַּתּוֹרָה (דברים כד) כִּי יִקַּח אִישׁ אִשָּׁה, וְלֹא כִּי תִלָּקַח אִשָּׁה לְאִישׁ בִּגְלַל שֶׁדֶּרֶךְ הָאִישׁ לְחַזֵּר וּלְבַקֵּשׁ אִשָּׁה. מָשָׁל לְאָדָם שֶׁאָבְדָה לוֹ אֲבֵדָה, בַּעַל הָאֲבֵדָה מְחַזֵּר אַחַר אֲבֵדָתוֹ. וְצַדִּיק (יסוד) זֶה נִקְרָא אִישׁ. זֶהוּ שֶׁכָּתוּב (בראשית מג) וְהוֹרִידוּ לָאִישׁ מִנְחָה, כְּפִי שֶׁבֵּאַרְנוּ.</p>\n<p>וּכְנֶסֶת יִשְׂרָאֵל שֶׁרְמוּזָה בְּיוֹם רְבִיעִי בְּסוֹד שֶׁל מְאֹרֹת חָסֵר, הָעַמּוּד הָרְבִיעִי מַלְכוּת שֶׁל דָּוִד, לָכֵן אַף עַל גַּב שֶׁמְּקוֹמוֹ שֶׁל צַדִּיק זֶה יוֹם הַשַּׁבָּת, נִכְלַל וְנִרְמַז בַּיּוֹם הַשְּׁלִישִׁי, לִהְיוֹת סָמוּךְ לְיוֹם רְבִיעִי, וְהִיא אִשְׁתּוֹ, לָכֵן בַּעַל הָאֲבֵדָה מְחַזֵּר עַל אֲבֵדָתוֹ, וְלָכֵן כָּתוּב לְמַטָּה (שם מב) וְיוֹסֵף הוּא הַשַּׁלִּיט עַל הָאָרֶץ.</p>\n<p>אֲבָל לֶעָתִיד לָבֹא, שֶׁהוּא בְּאַחֲרִית הַיָּמִים, בַּיּוֹם הַשִּׁשִּׁי שֶׁהוּא הָאֶלֶף הַשִּׁשִּׁי, כְּשֶׁיָּבֹא הַמָּשִׁיחַ, שֶׁיּוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלֶף שָׁנָה, אַף עַל גַּב שֶׁחֶלְקָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל הוּא יוֹם הָרְבִיעִי, הָלְכָה וְנִרְמְזָה בַּיּוֹם הַשִּׁשִּׁי לִהְיוֹת סְמוּכָה לְבַעְלָהּ שֶׁנִּקְרָא צַדִּיק, יוֹם הַשַּׁבָּת, לְתַקֵּן לוֹ שֻׁלְחָן. וְזֶהוּ שֶׁכָּתוּב (ירמיה לא) כִּי בָרָא ה' חֲדָשָׁה בָּאָרֶץ נְקֵבָה תְּסוֹבֵב גָּבֶר. זֶהוּ בִּזְמַן הַמָּשִׁיחַ שֶׁהוּא בַּיּוֹם הַשִּׁשִּׁי,</p>\n<p>וְלָכֵן כָּתוּב וַיְהִי עֶרֶב וַיְהִי בקֶר יוֹם הַשִּׁשִּׁי. מָה הַטַּעַם נוֹסָף ה', מַה שֶּׁלֹּא הָיָה כֵּן בִּשְׁאָר הַיָּמִים אֲבָל בְּכָל מָקוֹם ה' זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁבָּאָה לְהִזְדַּוֵּג עִם בַּעְלָהּ בְּיוֹם שַׁבָּת, כְּשֶׁיָּבא בַּעְלָהּ לַהֲקִימָהּ מִן הֶעָפָר. וּבִגְלַל כָּךְ כָּתוּב (ישעיה כז) וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר, זֶה צַדִּיק וּכְנֶסֶת יִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר, מָה הַטַּעַם נִכְלָל הַיּוֹם הַשְּׁלִישִׁי הַסּוֹד שֶׁל צַדִּיק בִּגְלַל שֶׁשָּׁלֹשׁ דְּרָגוֹת מִיָּמִין וְשָׁלֹשׁ מִשְּׂמֹאל, וְהוּא הָיָה בְּאֶמְצַע הַגּוּף לְהַשְׁקוֹת לַכֹּל כְּדֵי לְהַשְׁפִּיעַ הַשְׁפָּעָתוֹ לְיוֹם רְבִיעִי שֶׁהוּא כְּנֶסֶת יִשְׂרָאֵל, שֶׁאֵין לָהּ אוֹר מֵעַצְמָהּ סָמוּךְ לַצַּדִּיק הַזֶּה. וּבֹא תִרְאֶה, יוֹם הַשַּׁבָּת הַזֶּה אָסוּר לַעֲשׂוֹת בּוֹ מְלָאכָה, מִשּׁוּם כָּךְ נִכְלְלוּ בוֹ שְׁנֵי וַיֹּאמֶר, כְּנֶגֶד שְׁתֵּי דְרָגוֹת, וְהֻכְפַּל בּוֹ כִּי טוֹב.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת - כְּנֶגֶד דַּרְגָּה שֶׁל צֶדֶק, מַלְכוּת שֶׁלְּמַעְלָה שֶׁאֵין לָהּ אוֹר מִשֶּׁלָּהּ אֶלָּא מַה שֶּׁנּוֹתֵן לָהּ עַל יְדֵי צַדִּיק, וְלָכֵן דָּוִד לְמַטָּה עָנִי וְאֶבְיוֹן אָחוּזּ בָּהּ, וְהִצְטָרֵךְ לְהוֹסִיף לוֹ יָמִים וְשָׁנִים, וַהֲרֵי בֵּאַרְנוּ דַּוְקָא שִׁבְעִים שָׁנָה, וְנִקְרָא יוֹם רְבִיעִי.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמַּיִם - כְּנֶגֶד דַּרְגָּה שֶׁל נֵצַח, שֶׁהוּא עַמּוּד יָמִין שֶׁל הַתּוֹרָה, וּכְנֶגְדּוֹ מֹשֶׁה לְמַטָּה סוֹמֵךְ לָעוֹלָם בַּתּוֹרָה. זֶהוּ שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה וְגוֹמֵר.</p>\n<p>וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ - כְּנֶגֶד דַּרְגָּה שֶׁל הוֹד שֶׁאוֹחֵז אַהֲרֹן, וְנִקְרֵאת יוֹם שִׁשִּׁי. בֹּא רְאֵה, אַהֲרֹן לְמַטָּה אַף עַל גַּב שֶׁבָּא מֵחֶסֶד, אָחוּז לְמַטָּה בַּיּוֹם הַשִּׁשִּׁי שֶׁנִּקְרָא הוֹד, וְעוֹשֶׂה קָרְבָּנוֹת בְּאוֹתָם מִינֵי בְהֵמוֹת טְהוֹרוֹת שֶׁנִּבְרְאוּ בַּיּוֹם שֶׁלּוֹ, לְקָרֵב אֶת כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּרְמְזָה בְּצַדִּיק, לִקְשֹׁר דַּרְגוֹת הָאֱמוּנָה וּלְהוֹרִיד רַחֲמִים לָעוֹלָם.</p>\n<p>וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם. הָאֲמִירָה הַזּוֹ כְּנֶגֶד הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁל הַכֹּל נִסְתֶּרֶת הַנִּסְתָּרִים, רָצָה לַעֲשׂוֹת כָּבוֹד לִדְמוּתוֹ בְּסוֹד שֶׁל אָדָם, וּבְכָל הַדְּרָגוֹת לְמַטָּה נָתַן כֹּחַ לְהוֹצִיא, כָּל אֶחָד כָּרָאוּי לוֹ, וְעָשָׂה אָדָם שֶׁשּׁוֹלֵט בַּכֹּל, בְּעֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וּבֹא רְאֵה, עַד שֶׁלֹּא הִשְׁתַּלְּמוּ אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁל יָמִים עֶלְיוֹנִים, לֹא הִשְׁתַּלֵּם אָדָם לְמַעְלָה. כֵּיוָן שֶׁהִשְׁתַּלֵּם לְמַעְלָה אָדָם הָעֶלְיוֹן, הִשְׁתַּלֵּם לְמַטָּה אָדָם הַתַּחְתּוֹן וְכָל הָעוֹלָמוֹת בִּשְׁלֵמוּת. לָכֵן הִשְׁלִיט אֶת הָאָדָם הַתַּחְתּוֹן עַל כָּל מַה שֶּׁנִּבְרָא בָּעוֹלָם, בִּגְלַל שֶׁאָדָם הָעֶלְיוֹן שׁוֹלֵט עַל הַכֹּל. וְלָכֵן רָמַז בְּפָסוּק זֶה שֶׁבַע דְּרָגוֹת, שֶׁיֵּשׁ בּוֹ שֶׁבַע דְּרָגוֹת עֶלְיוֹנוֹת שֶׁנִּקְרָא בָהֶם אָדָם שֶׁלְּמַעְלָה וְהִשְׁתַּלֵּם בָּהֶם. בִּגְלַל כָּךְ, נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ, לָתֵת לוֹ שֶׁפַע מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא חֶסֶד.</p>\n<p>בֹּא רְאֵה, מִי שֶׁצֶּלֶם זֶה עָלָיו, חֶסֶד אֵל לֹא זָז מִמֶּנּוּ וְיוֹשֵׁב עַל רֹאשׁוֹ, וּמִתְחַבֶּרֶת בּוֹ שְׁכִינָה בְּסוֹף יָמָיו, בִּגְלַל שֶׁחֶסֶד זֶה הוּא יוֹם רִאשׁוֹן, וְהוּא רֹאשׁ שֶׁל כָּל הַיָּמִים שֶׁלְּמַעְלָה. וְצֶלֶם זֶה שֶׁבָּא לוֹ מִמֶּנּוּ לֹא מִסְתַּלֵּק, עַד שֶׁנִּשְׁלָמִים יָמָיו בְּאוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת אַחֲרִית הַיָּמִים. וְהִיא הַדַּרְגָּה שֶׁל צֶדֶ\"ק, וְהִיא שְׁבִיעִית, שְׁנַת הַשְּׁמִטָּה. וּבְאוֹתָהּ דַּרְגָּה נִשְׁלָמִים יְמֵי הָאָדָם, כְּשֶׁנִּשְׁלְמוּ שִׁבְעִים שָׁנָה כְּנֶגֶד שֶׁבַע דְּרָגוֹת, עֶשֶׂר לְכָל דַּרְגָּה. זֶהוּ שֶׁכָּתוּב (תהלים צ) יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה. מַה זֶּה בָּהֶם בְּאוֹתָם יָמִים וְשָׁנִים שֶׁלְּמַעְלָה,</p>\n<p>וְאִם בִּגְבוּרֹת שְׁמוֹנִים. בֹּא רְאֵה, בָּנִים חַיִּים וּמְזוֹנוֹת לֹא בִזְכוּת תְּלוּיִים הַדְּבָרִים, הַסּוֹד שֶׁל אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁבָּהֶן זְכוּת וְחוֹבָה בְּסוֹד חֶסֶד וּגְבוּרָה, שֶׁאִם כָּךְ לֹא הָיָה לוֹ לָאָדָם לִהְיוֹת חַי פְּרָט לְשִׁבְעִים, אֶלָּא שֶׁבַּמַּזָּל הָעֶלְיוֹן הָעַתִּיק שֶׁל הַכֹּל תְּלוּיִים, בִּגְלַל כָּךְ הוּא מוֹסִיף עַל כָּל יְמֵי הָאָדָם כִּרְצוֹנוֹ.</p>\n<p>וּבֹא רְאֵה, כָּךְ לָמַדְנוּ בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁבַּלַּיְלָה הָאַחֲרוֹן שֶׁל חַג, אִם יִסְתַּכֵּל אָדָם בְּצַלְמוֹ וְיִרְאֶה אוֹתוֹ שָׁלֵם, לֹא נִגְזְרָה עָלָיו מִיתָה. וּמָה הַטַּעַם בַּלַּיְלָה הַזֶּה בִּגְלַל שֶׁשִּׁבְעַת יְמֵי הֶחָג כְּנֶגֶד שִׁבְעָה יָמִים עֶלְיוֹנִים הֵם, שֶׁכָּל הַיָּמִים וְהַשָּׁנִים שֶׁל הָעוֹלָם תְּלוּיִים בָּהֶם, וְהֵם רְמוּזִים בַּכָּתוּב שֶׁל (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְגוֹמֵר. רֵאשִׁיתָם חֶסֶד וְסִיּוּמָם מַמְלָכָה. כְּנֶסֶת יִשְׂרָאֵל. אַחֲרִית הַיָּמִים שֶׁנִּמְצֵאת שְׁבִיעִית אַחֲרִית. וּכְשֶׁבָּא לֵיל הַשְּׁבִיעִי הַזֶּה, נִרְאֶה אִם הִשְׁתַּלְּמוּ הַיָּמִים בָּאַחֲרִית הַ את. וְאִם הַצֶּלֶם הָעֶלְיוֹן הַזֶּה נִרְאֶה עָלָיו, אָז חֶסֶד אֵל כָּל הַיּוֹם יַחֲזֹר עָלָיו כְּבַתְּחִלָּה, וְלֹא פוֹחֵד מֵהַדִּין הַזֶּה שֶׁל צֶדֶק, וְהִיא עִמּוֹ בִּשְׁלֵמוּת בְּחֶדְוָה וּמַחֲזִירָה לוֹ פָּנִים.</p>\n<p>וְלָכֵן הִזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לְהִנָּצֵל מִדִּינֵי הַצֶּדֶק הַזּוֹ, וּלְכַסּוֹת סֻכַּת שָׁלוֹם עֲלֵיהֶם, וְלָשֶׁבֶת בְּצֵל הָאֱמוּנָה. זֶהוּ שֶׁכָּתוּב (ויקרא כג) בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים, לְהַכְלִיל אֶת הַדַּרְגָּה הַזּוֹ לְמַעְלָה וּלְהוֹסִיף בָּהּ בְּרָכָה מִמַּיִם הָעֶלְיוֹנִים, בִּגְלַל שֶׁיּוֹם זֶה הוּא שְׁבִיעִי הוּא כְּנֶסֶת יִשְׂרָאֵל. אָנוּ מַקִּיפִים אֶת הַמִּזְבֵּחַ הַזֶּה הָעֶלְיוֹן בְּאוֹתָם שְׁנֵי לִמּוּדִים שֶׁהֵם עַרְבֵי נַחַל, וְעוֹשִׂים בָּהּ נִסּוּךְ הַמַּיִם, וְנוֹתֵן צַדִּיק בְּאוֹתָם שִׁתִּין שֶׁהֵם מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, הַכֹּל בְּסוֹד הַחָכְמָה.</p>\n<p>וּלְאַחַר מִכֵּן (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם, תַּעֲשׂוּ כִנּוּס לְאוֹתָם שִׁבְעָה יָמִים עֶלְיוֹנִים, וַעֲשׂוּ יוֹם טוֹב בִּגְלַל שֶׁנִּצָּלְתֶם מִדִּינוֹ שֶׁל אוֹתוֹ יוֹם שְׁבִיעִי. בִּגְלַל כָּךְ כָּתוּב בְּצַלְמֵנוּ</p>\n<p>כִּדְמוּתֵנוּ, כְּנֶגֶד יוֹם שֵׁנִי גְּבוּרָה, חֶלְקוֹ שֶׁל יִצְחָק, וְאָז יֵשׁ לָאָדָם לָשִׂים אֶת 'דְּמוּתֵנוּ' הַזֹּאת וּלְהִדָּמוֹת בְּמַעֲשָׂיו לְאוֹתָם הָעֶלְיוֹנִים. וְכָל זֶה לָמָּה בִּגְלַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן בִּידֵי הָאִישׁ, אִם רוֹצֶה הָאִישׁ לְדַמּוֹת עַצְמוֹ לְאוֹתָם שֶׁלְּמַעְלָה, מִשְׁתַּלֵּם בָּהֶם, וְלֹא פוֹחֵד מִמִּדַּת הַדִּין הָעֶלְיוֹנָה.</p>\n<p>וְיִרְדּוּ בִדְגַת הַיָּם - כְּנֶגֶד הַדַּרְגָּה שֶׁל נֵצַח שֶׁאָחוּז בָּהּ מֹשֶׁה, שֶׁדְּגַת הַיָּם נִבְרְאוּ בְּאוֹתָהּ דַּרְגָּה (ספירה), וְנָתַן לָהֶם נִסְתַּר הַנִּסְתָּרִים כֹּחַ לִשְׁלֹט עֲלֵיהֶם אִם דּוֹמֶה אָדָם לָעֶלְיוֹנִים, וְאִם לֹא דוֹמֶה לָעֶלְיוֹנִים - יִרְדּוּ, וּדְגֵי הַיָּם שׁוֹלְטִים בָּהֶם בִּבְנֵי אָדָם, וְלָכֵן הִזְהִירָה אוֹתָם הַתּוֹרָה שֶׁנִּתְּנָה עַל יְדֵי מֹשֶׁה, (דברים ל) וּבָחַרְתָּ בַּחַיִּים.</p>\n<p>בֹּא רְאֵה, מֹשֶׁה, כְּשֶׁנִּזְרַק לַיָּם, לֹא שָׁלְטוּ עָלָיו דְּגֵי הַיָּם וְלֹא פָחַד מֵהֶם, בִּגְלַל שֶׁהוּא הָיָה עָתִיד לְהִתְקָרֵב לְמַעְלָה וְלִדְבֹּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלְאַחַר שֶׁנִּדְבַּק, שָׁלַט עַל דְּגֵי הַיָּם, וְרָמַז לְאַהֲרֹן אָחִיו שֶׁיַּכֶּה אֶת הַיָּם וְיָמוּתוּ הַדָּגִים, וְהוּא לֹא עָשָׂה כָּךְ, בִּגְלַל שֶׁאוֹתָהּ דַּרְגָּה שֶׁלּוֹ שׁוֹלֶטֶת עֲלֵיהֶם וּבָהּ נִבְרְאוּ, וְלֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּכֶּה הוּא בִּשְׁבִיל לְהִתְהַפֵּךְ לָהֶם לְאוֹיֵב. וּכְשֶׁאָדָם הוֹלֵךְ בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּתוּב עָלָיו (ישעיה מג) כִּי תַעֲבֹר בַּמַּיִם אִתְּךְ אָנִי וְגוֹמֵר. שֶׁזֶּה וְיִרְדּוּ בִדְגַת הַיָּם</p>\n<p>וּבְעוֹף הַשָּׁמַיִם. כְּנֶגֶד דַּרְגָּה שֶׁל שָׁמַיִם, שֶׁבְּאוֹתָהּ דַּרְגָּה שׁוֹלֵט עֲלֵיהֶם, וְזוֹ תִפְאֶרֶת. וְאַף עַל גַּב שֶׁבְּדַרְגַּת הַנֶּצַח נַעֲשׂוּ כָּל דְּגֵי הַיָּם וְהָעוֹפוֹת, לֹא כָתוּב שָׁם אֶלָּא עוֹף כָּנָף, אֲבָל עַכְשָׁו קָרָא לָהֶם עוֹף הַשָּׁמַיִם, בִּגְלַל שֶׁבֶּן אָדָם לֹא שׁוֹלֵט עֲלֵיהֶם אֶלָּא מִצַּד שֶׁל שָׁמַיִם.</p>\n<p>וּבַבְּהֵמָה - שׁוֹלֵט עֲלֵיהֶם בְּסוֹד שֶׁל הוֹד שֶׁנּוֹתֵן לוֹ סִיּוּעַ, שֶׁהֲרֵי בְּאוֹתוֹ יוֹם נִבְרְאוּ הַבְּהֵמוֹת. וּבְכָל הָאָרֶץ - שׁוֹלֵט בְּסוֹד שֶׁל צַדִּיק שֶׁנִּקְרָא כֹּל, וְהוּא שׁוֹלֵט עַל הָאָרֶץ, אֶרֶץ הָעֶלְיוֹנָה. כָּךְ גַּם אָדָם לְמַטָּה שׁוֹלֵט עַל אֶרֶץ הַתַּחְתּוֹנָה, מִשּׁוּם שֶׁהַכֹּל בּוֹ. וּבְכָל הָרֶמֶשׂ הָרֹמֵשׂ עַל הָאָרֶץ - שׁוֹלֵט עֲלֵיהֶם אָדָם מִסִּיּוּעַ שֶׁנִּתָּן לוֹ מֵאֶרֶץ הַחַיִּים, הַמַּלְכוּת הָעֶלְיוֹנָה: (ע\"כ מההשמטות)</p>"]]});
